// AGENTS — one reusable movement system for everything that moves with INTENT
// in a 3D world: fireflies drifting round a fire, fish shoaling and fleeing,
// monsters hunting, birds flocking, minions following a leader. Reynolds'
// point-mass vehicle with Buckland's weighted-truncated-running-sum-with-
// prioritisation blend (avoidance claims the force budget first), topological
// k-nearest flocking (the starling ~7), a counting-sort spatial hash, fields
// (attract/repel + panic), and damped body language (banked turns, swim
// wiggle). Behaviours are DATA, composed into named presets.
//
// It is a CPU system, NOT a render layer: agents write x/y/z + yaw/pitch/roll
// straight onto retained render handles (Mesh3d/Billboard3d/model/group), so
// rendering costs nothing new — one instanced draw per shape however many
// agents there are. Fixed-step sim + render interpolation (the physics
// accumulator discipline). Module load is DOM/GPU-free so the kernel is
// dist-tested in Node.

import type { Path3d } from './path3d.js';
import type { FlowField } from './navgrid3d.js';
import { buildNavMesh, type NavMesh3d, type NavMeshOptions, type PathPlanner } from './agentnav3d.js';

export interface Vec3 { x: number; y: number; z: number }
type Vec3Like = Vec3;
/** A steering target: a fixed point, another agent (tracked live), or a fn. */
export type TargetLike = Vec3Like | Agent3d | (() => Vec3Like);

// ── Behaviours are data (the EffectDef/VfxDef shape) ────────────────────────

export interface BehaviorBase { weight?: number; priority?: number }
export type BehaviorSpec =
  | (BehaviorBase & { kind: 'seek'; target: TargetLike })
  | (BehaviorBase & { kind: 'flee'; target: TargetLike; radius?: number })
  | (BehaviorBase & { kind: 'arrive'; target: TargetLike; slowRadius?: number; tolerance?: number })
  | (BehaviorBase & { kind: 'pursue'; target: Agent3d; maxPredict?: number })
  | (BehaviorBase & { kind: 'evade'; target: Agent3d; maxPredict?: number; radius?: number })
  | (BehaviorBase & { kind: 'wander'; radius?: number; distance?: number; jitter?: number; vertical?: number })
  | (BehaviorBase & { kind: 'follow'; path: Path3d; lookAhead?: number; loop?: boolean; speed?: number })
  | (BehaviorBase & { kind: 'flock'; separation?: number; alignment?: number; cohesion?: number; radius?: number; neighbors?: number })
  | (BehaviorBase & { kind: 'avoid'; lookAhead?: number; radius?: number; planar?: boolean })
  | (BehaviorBase & { kind: 'terrain'; clearance: number; groundAt: (x: number, z: number) => number; lookAhead?: number })
  | (BehaviorBase & { kind: 'ceiling'; below: number | ((x: number, z: number) => number); margin?: number })
  | (BehaviorBase & { kind: 'contain'; box?: { min: Vec3; max: Vec3 }; sphere?: { center: Vec3; radius: number }; soft?: number })
  | (BehaviorBase & { kind: 'leader'; leader: Agent3d; behind?: number })
  // Stay ON a walkable surface (planks/platforms/ledges): whisker-samples a
  // predicate ahead + to the sides and turns back from any edge. XZ-planar.
  | (BehaviorBase & { kind: 'edge'; walkable: (x: number, z: number) => boolean; lookAhead?: number })
  // Plan a path to a (moving) target over any planner — the built-in NavGrid
  // (Tier-1 A*) OR a baked recast NavMesh3d (Tier-3) — re-planning on a timer /
  // when the goal drifts; steer along the smoothed waypoints.
  | (BehaviorBase & { kind: 'navigate'; grid: PathPlanner; target: TargetLike; repathEvery?: number; arrive?: number; tolerance?: number })
  // Tier-2 flow field: sample a precomputed direction toward the goal (O(1)) —
  // the horde-chase behaviour (one field, N followers + separation).
  | (BehaviorBase & { kind: 'flow'; field: FlowField })
  | (BehaviorBase & { kind: 'custom'; fn: (agent: Agent3d, out: Vec3, dt: number) => void });

// Default priority per kind — avoidance/containment claim the budget first,
// flocking next, goal-seeking last (Buckland's prioritisation).
const PRIORITY: Record<string, number> = {
  avoid: 4, terrain: 4, ceiling: 4, contain: 4, edge: 4,
  flock: 2, leader: 2,
  seek: 1, flee: 1, arrive: 1, pursue: 1, evade: 1, wander: 1, follow: 1, navigate: 1, flow: 1, custom: 1,
};

// ── Pure vector helpers (allocation-free where it matters) ──────────────────

const vlen = (x: number, y: number, z: number): number => Math.hypot(x, y, z);
const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v);

/** Deterministic per-agent PRNG (mulberry32) — reproducible wander. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function targetPos(t: TargetLike): Vec3 {
  if (typeof t === 'function') return t();
  if (t instanceof Agent3d) return t.pos;
  return t;
}

// ── The spatial hash (counting-sort uniform grid, flat typed arrays) ────────
// Mirrors the GPU sort-by-cell layout so the kernel ports to compute unchanged.
// Inherits the physics.ts lesson: brute force wins under ~1k candidates, so
// small flocks skip it (see Agents3d.step).

const HASH_P1 = 73856093, HASH_P2 = 19349663, HASH_P3 = 83492791;

export class SpatialHash3 {
  private cellSize: number;
  private tableSize: number;
  private mask: number;
  private counts: Int32Array;
  private starts: Int32Array;
  private items: Int32Array;
  private cellOf: Int32Array;
  private seenBuckets = new Int32Array(27);
  /** drop the Y dimension for surface-bound swarms (ground crowds). */
  flat = false;

  constructor(cellSize: number, capacity: number, tablePow = 12) {
    this.cellSize = Math.max(1e-3, cellSize);
    this.tableSize = 1 << tablePow;
    this.mask = this.tableSize - 1;
    this.counts = new Int32Array(this.tableSize + 1);
    this.starts = new Int32Array(this.tableSize + 1);
    this.items = new Int32Array(Math.max(1, capacity));
    this.cellOf = new Int32Array(Math.max(1, capacity));
  }

  private key(x: number, y: number, z: number): number {
    const inv = 1 / this.cellSize;
    const ix = Math.floor(x * inv) | 0;
    const iy = this.flat ? 0 : Math.floor(y * inv) | 0;
    const iz = Math.floor(z * inv) | 0;
    return ((Math.imul(ix, HASH_P1) ^ Math.imul(iy, HASH_P2) ^ Math.imul(iz, HASH_P3)) >>> 0) & this.mask;
  }

  /** Rebuild from the live agent positions (indices 0..n-1). */
  build(agents: Agent3d[]): void {
    const n = agents.length;
    if (this.items.length < n) { this.items = new Int32Array(n); this.cellOf = new Int32Array(n); }
    this.counts.fill(0);
    for (let i = 0; i < n; i++) {
      const p = agents[i]!.pos;
      const c = this.key(p.x, p.y, p.z);
      this.cellOf[i] = c;
      this.counts[c]++;
    }
    // prefix sum → bucket starts
    let acc = 0;
    for (let c = 0; c <= this.tableSize; c++) { this.starts[c] = acc; acc += this.counts[c]!; }
    // scatter (reuse counts as a running cursor)
    const cursor = this.counts;
    for (let c = 0; c < this.tableSize; c++) cursor[c] = this.starts[c]!;
    for (let i = 0; i < n; i++) { const c = this.cellOf[i]!; this.items[cursor[c]!++] = i; }
  }

  /** Nearest up-to-k neighbours of agent `self` within `radius`, written into
   * `outIdx` (indices) / `outD2` (squared distances); returns the count. */
  query(agents: Agent3d[], self: number, radius: number, k: number, outIdx: Int32Array, outD2: Float32Array): number {
    const p = agents[self]!.pos;
    const r2 = radius * radius;
    const inv = 1 / this.cellSize;
    const cx = Math.floor(p.x * inv) | 0;
    const cy = this.flat ? 0 : Math.floor(p.y * inv) | 0;
    const cz = Math.floor(p.z * inv) | 0;
    let count = 0;
    const ylo = this.flat ? 0 : -1, yhi = this.flat ? 0 : 1;
    // Two DIFFERENT cells can hash to the SAME bucket (collision); scanning a
    // bucket twice would double-count neighbours, so track the buckets seen.
    const seen = this.seenBuckets;
    let seenN = 0;
    for (let dz = -1; dz <= 1; dz++) {
      for (let dy = ylo; dy <= yhi; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const c = ((Math.imul(cx + dx, HASH_P1) ^ Math.imul(cy + dy, HASH_P2) ^ Math.imul(cz + dz, HASH_P3)) >>> 0) & this.mask;
          let dup = false;
          for (let q = 0; q < seenN; q++) if (seen[q] === c) { dup = true; break; }
          if (dup) continue;
          seen[seenN++] = c;
          const s = this.starts[c]!, e = this.starts[c + 1]!;
          for (let ii = s; ii < e; ii++) {
            const j = this.items[ii]!;
            if (j === self) continue;
            const q = agents[j]!.pos;
            const d2 = (q.x - p.x) ** 2 + (q.y - p.y) ** 2 + (q.z - p.z) ** 2;
            if (d2 > r2) continue;
            count = insertNearest(outIdx, outD2, count, k, j, d2);
          }
        }
      }
    }
    return Math.min(count, k);
  }
}

/** Brute-force nearest-k (small flocks skip the hash — the physics.ts lesson). */
export function neighborsBrute(agents: Agent3d[], self: number, radius: number, k: number, outIdx: Int32Array, outD2: Float32Array): number {
  const p = agents[self]!.pos;
  const r2 = radius * radius;
  let count = 0;
  for (let j = 0; j < agents.length; j++) {
    if (j === self) continue;
    const q = agents[j]!.pos;
    const d2 = (q.x - p.x) ** 2 + (q.y - p.y) ** 2 + (q.z - p.z) ** 2;
    if (d2 > r2) continue;
    count = insertNearest(outIdx, outD2, count, k, j, d2);
  }
  return Math.min(count, k);
}

/** Partial insertion sort keeping the k smallest d2 — no allocation. */
function insertNearest(outIdx: Int32Array, outD2: Float32Array, count: number, k: number, j: number, d2: number): number {
  if (count < k) {
    let i = count;
    while (i > 0 && outD2[i - 1]! > d2) { outD2[i] = outD2[i - 1]!; outIdx[i] = outIdx[i - 1]!; i--; }
    outD2[i] = d2; outIdx[i] = j;
    return count + 1;
  }
  if (d2 >= outD2[k - 1]!) return count;      // not closer than the current worst
  let i = k - 1;
  while (i > 0 && outD2[i - 1]! > d2) { outD2[i] = outD2[i - 1]!; outIdx[i] = outIdx[i - 1]!; i--; }
  outD2[i] = d2; outIdx[i] = j;
  return count;
}

// ── Fields: attractors, repulsors, obstacles ────────────────────────────────

export interface FieldOptions {
  pos?: Vec3;
  follow?: { x: number; y: number; z: number };   // a live handle/agent/camera
  radius: number;
  strength: number;
  falloff?: 'linear' | 'invsq';
  mode?: 'attract' | 'repel';
}
export class Field3d {
  pos: Vec3;
  follow: { x: number; y: number; z: number } | null;
  radius: number; strength: number;
  falloff: 'linear' | 'invsq';
  mode: 'attract' | 'repel';
  dead = false;
  constructor(o: FieldOptions) {
    this.pos = o.pos ? { ...o.pos } : { x: 0, y: 0, z: 0 };
    this.follow = o.follow ?? null;
    this.radius = o.radius; this.strength = o.strength;
    this.falloff = o.falloff ?? 'invsq';
    this.mode = o.mode ?? 'attract';
  }
  at(): Vec3 { return this.follow ?? this.pos; }
  kill(): void { this.dead = true; }
}

export interface ObstacleOptions {
  sphere?: { center: Vec3; radius: number };
  box?: { min: Vec3; max: Vec3 };
}
export class Obstacle3d {
  sphere: { center: Vec3; radius: number } | null;
  box: { min: Vec3; max: Vec3 } | null;
  dead = false;
  constructor(o: ObstacleOptions) {
    this.sphere = o.sphere ?? null;
    this.box = o.box ?? null;
  }
  kill(): void { this.dead = true; }
}

// ── The agent ───────────────────────────────────────────────────────────────

export interface AgentConfig {
  pos?: Vec3;
  vel?: Vec3;
  maxSpeed?: number;
  maxForce?: number;
  mass?: number;
  behaviors?: BehaviorSpec[];
  handle?: { x: number; y: number; z: number; yaw?: number; pitch?: number; roll?: number } | null;
  seed?: number;
  /** Steering solved every Nth fixed step (LOD); velocity integrates always. */
  tickEvery?: number;
  /** Radians/sec the heading damps toward velocity (never snaps). */
  turnRate?: number;
  /** Max pitch (radians) — clamp for flyers/swimmers. */
  maxPitch?: number;
  /** Bank into turns: roll ∝ lateral steering (0 = none). */
  bank?: number;
  /** GROUND agents: glue the body to a surface. Steering owns XZ; after each
   * step the Y is SNAPPED to `at(x,z) + offset` (walkers, monsters, herds —
   * `at` can return terrain OR a ramp/plank/platform top). `slope: true` also
   * pitches the body to the surface gradient so it climbs ramps convincingly. */
  ground?: { at: (x: number, z: number) => number; offset?: number; slope?: boolean } | null;
}

let AGENT_ID = 1;

export class Agent3d {
  readonly id: number;
  pos: Vec3;
  prev: Vec3;
  vel: Vec3;
  maxSpeed: number;
  maxForce: number;
  mass: number;
  behaviors: BehaviorSpec[];
  handle: { x: number; y: number; z: number; yaw?: number; pitch?: number; roll?: number } | null;
  tickEvery: number;
  turnRate: number;
  maxPitch: number;
  bank: number;
  ground: { at: (x: number, z: number) => number; offset: number; slope: boolean } | null;
  yaw = 0; pitch = 0; roll = 0;
  /** panic timer (s) — a repulsor spike scatters a shoal (speed x panicMult). */
  panic = 0;
  /** wander target on the projected sphere (persisted for a smooth walk). */
  wx = 1; wy = 0; wz = 0;
  /** follow-behaviour progress along its path (world distance). */
  followD = 0;
  /** avoid-behaviour hysteresis: the committed dodge side (±1) + its hold timer,
   * so the agent arcs around an obstacle on ONE side instead of jittering. */
  avoidSide = 0;
  avoidHold = 0;
  /** navigate-behaviour state: the current A* waypoint list + cursor + timers. */
  navPath: Vec3[] | null = null;
  navIdx = 0;
  navTimer = 0;
  navGoalX = 0; navGoalZ = 0;
  /** per-instance wiggle phase (fish tail / wing flap) — rides a spare slot. */
  phase = 0;
  rng: () => number;
  dead = false;
  /** last accumulated steering force (for gizmos). */
  force: Vec3 = { x: 0, y: 0, z: 0 };

  constructor(c: AgentConfig = {}) {
    this.id = AGENT_ID++;
    this.pos = c.pos ? { ...c.pos } : { x: 0, y: 0, z: 0 };
    this.prev = { ...this.pos };
    this.vel = c.vel ? { ...c.vel } : { x: 0, y: 0, z: 0 };
    this.maxSpeed = c.maxSpeed ?? 6;
    this.maxForce = c.maxForce ?? 20;
    this.mass = Math.max(1e-3, c.mass ?? 1);
    this.behaviors = (c.behaviors ?? []).slice().sort(
      (a, b) => (b.priority ?? PRIORITY[b.kind] ?? 1) - (a.priority ?? PRIORITY[a.kind] ?? 1),
    );
    this.handle = c.handle ?? null;
    this.tickEvery = Math.max(1, Math.floor(c.tickEvery ?? 1));
    this.turnRate = c.turnRate ?? 6;
    this.maxPitch = c.maxPitch ?? Math.PI / 2;
    this.bank = c.bank ?? 0;
    this.ground = c.ground ? { at: c.ground.at, offset: c.ground.offset ?? 0, slope: c.ground.slope ?? false } : null;
    this.rng = mulberry32((c.seed ?? this.id) >>> 0);
    this.phase = this.rng() * Math.PI * 2;
    const d = this.wander0();
    this.wx = d.x; this.wy = d.y; this.wz = d.z;
  }
  private wander0(): Vec3 {
    const a = this.rng() * Math.PI * 2;
    return { x: Math.cos(a), y: 0, z: Math.sin(a) };
  }
  get speed(): number { return vlen(this.vel.x, this.vel.y, this.vel.z); }
  kill(): void { this.dead = true; }
}

// ── The kernel: one fixed step (pure, dist-tested) ──────────────────────────

// Module scratch — the tick allocates nothing.
const S = { x: 0, y: 0, z: 0 };       // desired-force scratch
const ACC = { x: 0, y: 0, z: 0 };     // accumulator

/** Compute ONE behaviour's desired steering force into `out` (unweighted). */
function behaviorForce(a: Agent3d, b: BehaviorSpec, ctx: StepCtx, dt: number, out: Vec3): void {
  out.x = 0; out.y = 0; out.z = 0;
  switch (b.kind) {
    case 'seek': { seekInto(a, targetPos(b.target), out); break; }
    case 'flee': { fleeInto(a, targetPos(b.target), b.radius ?? Infinity, out); break; }
    case 'arrive': { arriveInto(a, targetPos(b.target), b.slowRadius ?? 6, b.tolerance ?? 0.3, out); break; }
    case 'pursue': {
      const t = b.target; const tp = t.pos; const tv = t.vel;
      const dist = vlen(tp.x - a.pos.x, tp.y - a.pos.y, tp.z - a.pos.z);
      const pred = Math.min(dist / Math.max(a.maxSpeed, 1e-3), b.maxPredict ?? 1);
      seekInto(a, { x: tp.x + tv.x * pred, y: tp.y + tv.y * pred, z: tp.z + tv.z * pred }, out);
      break;
    }
    case 'evade': {
      const t = b.target; const tp = t.pos; const tv = t.vel;
      const dist = vlen(tp.x - a.pos.x, tp.y - a.pos.y, tp.z - a.pos.z);
      if (dist > (b.radius ?? Infinity)) break;
      const pred = Math.min(dist / Math.max(a.maxSpeed, 1e-3), b.maxPredict ?? 1);
      fleeInto(a, { x: tp.x + tv.x * pred, y: tp.y + tv.y * pred, z: tp.z + tv.z * pred }, Infinity, out);
      break;
    }
    case 'wander': { wanderInto(a, b, out); break; }
    case 'flock': { flockInto(a, b, ctx, out); break; }
    case 'avoid': { avoidInto(a, b, ctx, dt, out); break; }
    case 'terrain': {
      const la = b.lookAhead ?? 1;
      const px = a.pos.x + a.vel.x * la, pz = a.pos.z + a.vel.z * la;
      const floor = b.groundAt(px, pz) + b.clearance;
      if (a.pos.y < floor) out.y += (floor - a.pos.y) * a.maxForce;
      break;
    }
    case 'ceiling': {
      const cap = typeof b.below === 'number' ? b.below : b.below(a.pos.x, a.pos.z);
      const m = b.margin ?? 0;
      if (a.pos.y > cap - m) out.y -= (a.pos.y - (cap - m)) * a.maxForce;
      break;
    }
    case 'contain': { containInto(a, b, out); break; }
    case 'leader': {
      const l = b.leader; const behind = b.behind ?? 2;
      const s = l.speed || 1; const bx = l.vel.x / s, bz = l.vel.z / s;
      arriveInto(a, { x: l.pos.x - bx * behind, y: l.pos.y, z: l.pos.z - bz * behind }, 3, 0.2, out);
      break;
    }
    case 'follow': { followInto(a, b, dt, out); break; }
    case 'edge': { edgeInto(a, b, out); break; }
    case 'navigate': { navigateInto(a, b, dt, out); break; }
    case 'flow': {
      const d = b.field.dirAt(a.pos.x, a.pos.z);
      const l = Math.hypot(d.x, d.z);
      if (l > 1e-4) { out.x += (d.x / l) * a.maxSpeed - a.vel.x; out.z += (d.z / l) * a.maxSpeed - a.vel.z; }
      break;
    }
    case 'custom': { b.fn(a, out, dt); break; }
  }
}

function seekInto(a: Agent3d, t: Vec3, out: Vec3): void {
  let dx = t.x - a.pos.x, dy = t.y - a.pos.y, dz = t.z - a.pos.z;
  const l = vlen(dx, dy, dz) || 1;
  dx = (dx / l) * a.maxSpeed; dy = (dy / l) * a.maxSpeed; dz = (dz / l) * a.maxSpeed;
  out.x += dx - a.vel.x; out.y += dy - a.vel.y; out.z += dz - a.vel.z;
}
function fleeInto(a: Agent3d, t: Vec3, radius: number, out: Vec3): void {
  let dx = a.pos.x - t.x, dy = a.pos.y - t.y, dz = a.pos.z - t.z;
  const l = vlen(dx, dy, dz);
  if (l > radius || l < 1e-5) return;
  dx = (dx / l) * a.maxSpeed; dy = (dy / l) * a.maxSpeed; dz = (dz / l) * a.maxSpeed;
  out.x += dx - a.vel.x; out.y += dy - a.vel.y; out.z += dz - a.vel.z;
}
function arriveInto(a: Agent3d, t: Vec3, slow: number, tol: number, out: Vec3): void {
  const dx = t.x - a.pos.x, dy = t.y - a.pos.y, dz = t.z - a.pos.z;
  const dist = vlen(dx, dy, dz);
  if (dist < tol) { out.x -= a.vel.x; out.y -= a.vel.y; out.z -= a.vel.z; return; }   // deadzone: brake (no jitter)
  const sp = a.maxSpeed * (dist < slow ? dist / slow : 1);
  const k = sp / dist;
  out.x += dx * k - a.vel.x; out.y += dy * k - a.vel.y; out.z += dz * k - a.vel.z;
}
function wanderInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'wander' }>, out: Vec3): void {
  const jitter = b.jitter ?? 0.6, radius = b.radius ?? 1.2, distance = b.distance ?? 2, vertical = b.vertical ?? 0;
  a.wx += (a.rng() * 2 - 1) * jitter;
  a.wy += (a.rng() * 2 - 1) * jitter * vertical;
  a.wz += (a.rng() * 2 - 1) * jitter;
  const l = vlen(a.wx, a.wy, a.wz) || 1;
  a.wx /= l; a.wy /= l; a.wz /= l;
  // Heading (fall back to +x when still) projects the wander sphere ahead.
  let hx = a.vel.x, hy = a.vel.y, hz = a.vel.z;
  const hl = vlen(hx, hy, hz);
  if (hl < 1e-4) { hx = 1; hy = 0; hz = 0; } else { hx /= hl; hy /= hl; hz /= hl; }
  const tx = a.pos.x + hx * distance + a.wx * radius;
  const ty = a.pos.y + hy * distance + a.wy * radius;
  const tz = a.pos.z + hz * distance + a.wz * radius;
  seekInto(a, { x: tx, y: ty, z: tz }, out);
}
function flockInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'flock' }>, ctx: StepCtx, out: Vec3): void {
  const n = ctx.nCount;
  if (n === 0) return;
  const sepW = b.separation ?? 1.5, aliW = b.alignment ?? 1, cohW = b.cohesion ?? 1;
  const sepDist = (b.radius ?? 6) * 0.5;             // separation is LOCAL only
  let sx = 0, sy = 0, sz = 0, ax = 0, ay = 0, az = 0, cx = 0, cy = 0, cz = 0;
  for (let i = 0; i < n; i++) {
    const o = ctx.agents[ctx.nIdx[i]!]!;
    const d = Math.sqrt(ctx.nD2[i]!) || 1e-4;
    if (d < sepDist) {
      // Proximity-weighted push (1 at contact → 0 at sepDist) so a distant
      // neighbour barely repels — else full-strength separation overpowers
      // cohesion and the flock BLOWS APART instead of grouping.
      const w = (sepDist - d) / sepDist;
      sx += ((a.pos.x - o.pos.x) / d) * w; sy += ((a.pos.y - o.pos.y) / d) * w; sz += ((a.pos.z - o.pos.z) / d) * w;
    }
    ax += o.vel.x; ay += o.vel.y; az += o.vel.z;                     // alignment
    cx += o.pos.x; cy += o.pos.y; cz += o.pos.z;                     // cohesion
  }
  // separation → steer toward the (proximity-weighted) away direction
  const sl = vlen(sx, sy, sz);
  if (sl > 1e-5) { out.x += ((sx / sl) * a.maxSpeed - a.vel.x) * sepW; out.y += ((sy / sl) * a.maxSpeed - a.vel.y) * sepW; out.z += ((sz / sl) * a.maxSpeed - a.vel.z) * sepW; }
  // alignment → match average heading
  const al = vlen(ax, ay, az);
  if (al > 1e-5) { out.x += ((ax / al) * a.maxSpeed - a.vel.x) * aliW; out.y += ((ay / al) * a.maxSpeed - a.vel.y) * aliW; out.z += ((az / al) * a.maxSpeed - a.vel.z) * aliW; }
  // cohesion → arrive at the flock centroid (arrive-damped, so it never pulses)
  cx /= n; cy /= n; cz /= n;
  const tmp = { x: 0, y: 0, z: 0 };
  arriveInto(a, { x: cx, y: cy, z: cz }, 5, 0.1, tmp);
  out.x += tmp.x * cohW; out.y += tmp.y * cohW; out.z += tmp.z * cohW;
}
function avoidInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'avoid' }>, ctx: StepCtx, dt: number, out: Vec3): void {
  const sp = a.speed;
  const feel = (b.lookAhead ?? 2) * (0.5 + 0.5 * sp / Math.max(a.maxSpeed, 1e-3));
  const margin = b.radius ?? 0.8;              // the agent's own girth
  let hx = a.vel.x, hz = a.vel.z;              // dodge in the HORIZONTAL plane
  const hl = Math.hypot(hx, hz);
  if (hl < 1e-4) { avoidCooldown(a, dt); return; }
  hx /= hl; hz /= hl;
  // Cast the heading RAY against every obstacle sphere; keep the NEAREST one
  // the ray actually threatens (closest approach < R+margin, ahead within feel).
  let bestT = feel + 1e9, hasThreat = false;
  let cx = 0, cz = 0, cR = 0;
  for (const ob of ctx.obstacles) {
    if (ob.dead || !ob.sphere) continue;
    const c = ob.sphere.center, R = ob.sphere.radius + margin;
    const tox = c.x - a.pos.x, toz = c.z - a.pos.z;
    const along = tox * hx + toz * hz;                     // projection onto heading (XZ)
    if (along < -R || along > feel + R) continue;          // behind, or too far ahead
    const perp = Math.abs(tox * hz - toz * hx);            // ray's closest approach to centre
    if (perp >= R) continue;                               // ray clears it
    const t = along - Math.sqrt(Math.max(R * R - perp * perp, 0));  // entry distance
    if (t < bestT) { bestT = t; hasThreat = true; cx = c.x; cz = c.z; cR = R; }
  }
  if (!hasThreat) { avoidCooldown(a, dt); return; }
  // COMMIT to a side and hold it (hysteresis): recomputing the dodge direction
  // every frame flip-flops → jitter; and steering radially BACK only brakes →
  // the agent stalls head-on with the goal behind. Instead we pick the near
  // side ONCE and steer TANGENTIALLY (arc around) + a little outward, so a
  // walker slides around a boulder in one smooth committed curve.
  const rx = hz, rz = -hx;                                 // "right" of the heading (horizontal)
  if (a.avoidHold <= 0 || a.avoidSide === 0) {
    const offRight = (a.pos.x - cx) * rx + (a.pos.z - cz) * rz;   // which side the agent already leans
    a.avoidSide = offRight >= 0 ? 1 : -1;                  // dead-on (0) → +1, a stable tiebreak
  }
  a.avoidHold = 0.5;                                       // keep this side ~0.5 s past the last threat
  const urgency = clamp(1 - bestT / Math.max(feel, 1e-3), 0.35, 1);
  const s = a.avoidSide;
  out.x += rx * s * a.maxForce * urgency;                  // tangential — turn to the committed side
  out.z += rz * s * a.maxForce * urgency;
  let ax = a.pos.x - cx, az = a.pos.z - cz;                // + a little outward to keep clearance
  const al = Math.hypot(ax, az) || 1;
  out.x += (ax / al) * a.maxForce * urgency * 0.5;
  out.z += (az / al) * a.maxForce * urgency * 0.5;
}
/** Decay the committed dodge side once the threat is gone (no jitter re-arm). */
function avoidCooldown(a: Agent3d, dt: number): void {
  a.avoidHold -= dt;
  if (a.avoidHold <= 0) a.avoidSide = 0;
}
function edgeInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'edge' }>, out: Vec3): void {
  const la = b.lookAhead ?? 2.5;
  let hx = a.vel.x, hz = a.vel.z;                           // XZ heading only (planar)
  const hl = Math.hypot(hx, hz);
  if (hl < 1e-4) { hx = 1; hz = 0; } else { hx /= hl; hz /= hl; }
  const rx = hz, rz = -hx;                                  // right of the heading
  const ahead = b.walkable(a.pos.x + hx * la, a.pos.z + hz * la);
  if (!ahead) {
    // Ledge dead ahead: brake and turn toward whichever side is still walkable.
    const rOk = b.walkable(a.pos.x + rx * la, a.pos.z + rz * la);
    const lOk = b.walkable(a.pos.x - rx * la, a.pos.z - rz * la);
    const side = rOk && !lOk ? 1 : lOk && !rOk ? -1 : (rOk ? 1 : -1);
    out.x += (rx * side - hx) * a.maxForce;
    out.z += (rz * side - hz) * a.maxForce;
  } else {
    // Steer gently inward if a side feeler is over the edge (hug the centre).
    if (!b.walkable(a.pos.x + rx * la, a.pos.z + rz * la)) { out.x -= rx * a.maxForce * 0.7; out.z -= rz * a.maxForce * 0.7; }
    if (!b.walkable(a.pos.x - rx * la, a.pos.z - rz * la)) { out.x += rx * a.maxForce * 0.7; out.z += rz * a.maxForce * 0.7; }
  }
}
function containInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'contain' }>, out: Vec3): void {
  const soft = b.soft ?? 2;
  if (b.box) {
    const { min, max } = b.box;
    if (a.pos.x < min.x + soft) out.x += a.maxForce * (1 - (a.pos.x - min.x) / soft);
    if (a.pos.x > max.x - soft) out.x -= a.maxForce * (1 - (max.x - a.pos.x) / soft);
    if (a.pos.y < min.y + soft) out.y += a.maxForce * (1 - (a.pos.y - min.y) / soft);
    if (a.pos.y > max.y - soft) out.y -= a.maxForce * (1 - (max.y - a.pos.y) / soft);
    if (a.pos.z < min.z + soft) out.z += a.maxForce * (1 - (a.pos.z - min.z) / soft);
    if (a.pos.z > max.z - soft) out.z -= a.maxForce * (1 - (max.z - a.pos.z) / soft);
  }
  if (b.sphere) {
    const c = b.sphere.center;
    const dx = a.pos.x - c.x, dy = a.pos.y - c.y, dz = a.pos.z - c.z;
    const d = vlen(dx, dy, dz);
    if (d > b.sphere.radius - soft) {
      const k = -a.maxForce * clamp((d - (b.sphere.radius - soft)) / soft, 0, 1) / (d || 1);
      out.x += dx * k; out.y += dy * k; out.z += dz * k;
    }
  }
}
function navigateInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'navigate' }>, dt: number, out: Vec3): void {
  const goal = targetPos(b.target);
  a.navTimer -= dt;
  const drifted = Math.hypot(goal.x - a.navGoalX, goal.z - a.navGoalZ) > (b.tolerance ?? 3);
  // Re-plan only on the timer or when the goal has moved (NEVER per tick).
  if (!a.navPath || a.navPath.length === 0 || a.navTimer <= 0 || drifted) {
    a.navPath = b.grid.path(a.pos, goal);
    a.navIdx = 0; a.navTimer = b.repathEvery ?? 0.6;
    a.navGoalX = goal.x; a.navGoalZ = goal.z;
  }
  const path = a.navPath;
  if (!path || path.length === 0) { seekInto(a, goal, out); return; }   // unreachable → head over, avoidance copes
  // Advance the cursor past any waypoint reached (XZ). A SMALL reach makes the
  // agent hug the (radius-eroded) path tightly through doorways instead of
  // cutting corners toward the walls — its "spatial awareness of its size" is
  // the navmesh clearance, honoured by staying ON the path.
  const reach = Math.max(a.maxSpeed * 0.2, 1);
  while (a.navIdx < path.length - 1) {
    const w = path[a.navIdx]!;
    if (Math.hypot(a.pos.x - w.x, a.pos.z - w.z) < reach) a.navIdx++; else break;
  }
  const w = path[Math.min(a.navIdx, path.length - 1)]!;
  // Arrive-slow at the FINAL waypoint (stops cleanly); arrive-slow at interior
  // corners too when moving fast, so a sharp turn doesn't overshoot into a wall.
  const last = a.navIdx >= path.length - 1;
  if (last && b.arrive) arriveInto(a, w, b.arrive, 1, out);
  else arriveInto(a, w, Math.max(a.maxSpeed * 0.5, 3), 0.1, out);
}
function followInto(a: Agent3d, b: Extract<BehaviorSpec, { kind: 'follow' }>, dt: number, out: Vec3): void {
  const path = b.path;
  const speed = b.speed ?? a.maxSpeed;
  a.followD += speed * dt;
  if (a.followD > path.length) { a.followD = b.loop ? a.followD % path.length : path.length; }
  const ahead = Math.min(a.followD + (b.lookAhead ?? 2), b.loop ? Infinity : path.length);
  const t = path.atDist(b.loop ? ahead % path.length : ahead);
  seekInto(a, { x: t.x, y: t.y, z: t.z }, out);
}

interface StepCtx {
  agents: Agent3d[];
  fields: Field3d[];
  obstacles: Obstacle3d[];
  nIdx: Int32Array;
  nD2: Float32Array;
  nCount: number;
}

/** Fields: attractors pull, repulsors push; a repulsor spike arms panic. */
function applyFields(a: Agent3d, ctx: StepCtx, out: Vec3): void {
  out.x = 0; out.y = 0; out.z = 0;                 // reset the shared scratch
  for (const f of ctx.fields) {
    if (f.dead) continue;
    const c = f.at();
    const dx = a.pos.x - c.x, dy = a.pos.y - c.y, dz = a.pos.z - c.z;
    const d = vlen(dx, dy, dz);
    if (d > f.radius || d < 1e-4) continue;
    const t = 1 - d / f.radius;
    const g = f.falloff === 'invsq' ? t * t : t;
    const mag = f.strength * g;
    const sign = f.mode === 'repel' ? 1 : -1;
    out.x += (dx / d) * mag * sign; out.y += (dy / d) * mag * sign; out.z += (dz / d) * mag * sign;
    if (f.mode === 'repel' && mag > f.strength * 0.5) a.panic = Math.max(a.panic, 2);
  }
}

/** Integrate one agent for a fixed step, then damp its body language. */
export function integrateAgent(a: Agent3d, ctx: StepCtx, dt: number, solveSteering: boolean): void {
  a.prev.x = a.pos.x; a.prev.y = a.pos.y; a.prev.z = a.pos.z;
  if (a.panic > 0) a.panic = Math.max(0, a.panic - dt);
  const panicK = a.panic > 0 ? 2.5 : 1;
  if (solveSteering) {
    ACC.x = 0; ACC.y = 0; ACC.z = 0;
    let remaining = a.maxForce;
    // Fields first (repulsion is avoidance-priority), then behaviours.
    applyFields(a, ctx, S);
    remaining = accumulate(ACC, S, remaining);
    for (const b of a.behaviors) {
      if (remaining <= 1e-4) break;
      const w = b.weight ?? 1;
      behaviorForce(a, b, ctx, dt, S);
      S.x *= w; S.y *= w; S.z *= w;
      remaining = accumulate(ACC, S, remaining);
    }
    a.force.x = ACC.x; a.force.y = ACC.y; a.force.z = ACC.z;
    a.vel.x += (ACC.x / a.mass) * dt;
    a.vel.y += (ACC.y / a.mass) * dt;
    a.vel.z += (ACC.z / a.mass) * dt;
  }
  // clamp to (panic-boosted) max speed
  const sp = vlen(a.vel.x, a.vel.y, a.vel.z);
  const maxS = a.maxSpeed * panicK;
  if (sp > maxS && sp > 1e-6) { const k = maxS / sp; a.vel.x *= k; a.vel.y *= k; a.vel.z *= k; }
  a.pos.x += a.vel.x * dt; a.pos.y += a.vel.y * dt; a.pos.z += a.vel.z * dt;
  // GROUND conformance: glue the body to its surface (terrain/ramp/plank) and
  // drop any vertical drift so steering stays a pure XZ problem.
  if (a.ground) {
    a.pos.y = a.ground.at(a.pos.x, a.pos.z) + a.ground.offset;
    a.vel.y = 0;
  }
  a.phase += sp * dt * 3;                          // swim/flap phase ∝ speed
}

/** Add `f` to `acc`, truncated so |added| ≤ remaining budget. Returns the new
 * remaining budget (Buckland's truncated running sum). */
function accumulate(acc: Vec3, f: Vec3, remaining: number): number {
  const mag = vlen(f.x, f.y, f.z);
  if (mag < 1e-6) return remaining;
  const use = Math.min(mag, remaining);
  const k = use / mag;
  acc.x += f.x * k; acc.y += f.y * k; acc.z += f.z * k;
  return remaining - use;
}

/** Damp the heading toward the velocity (never snap) and write the pose onto
 * the render handle, interpolated between the last two sim steps by `alpha`. */
export function writePose(a: Agent3d, alpha: number): void {
  const px = a.prev.x + (a.pos.x - a.prev.x) * alpha;
  const py = a.prev.y + (a.pos.y - a.prev.y) * alpha;
  const pz = a.prev.z + (a.pos.z - a.prev.z) * alpha;
  const sp = a.speed;
  const hsp = Math.hypot(a.vel.x, a.vel.z);
  if (sp > 0.05) {
    const tYaw = Math.atan2(-a.vel.x, a.vel.z);   // heading, right-hand-turn yaw
    let tPitch: number;
    if (a.ground) {
      // Pitch to the SURFACE gradient along the heading (nose up climbing a
      // ramp), not to velocity.y (which the ground snap has zeroed).
      if (a.ground.slope && hsp > 1e-3) {
        const hx = a.vel.x / hsp, hz = a.vel.z / hsp, s = 1.2;
        const dh = a.ground.at(a.pos.x + hx * s, a.pos.z + hz * s) - a.ground.at(a.pos.x - hx * s, a.pos.z - hz * s);
        tPitch = clamp(Math.atan2(dh, 2 * s), -a.maxPitch, a.maxPitch);
      } else tPitch = 0;
    } else {
      tPitch = clamp(Math.asin(clamp(a.vel.y / sp, -1, 1)), -a.maxPitch, a.maxPitch);
    }
    a.yaw = dampAngle(a.yaw, tYaw, a.turnRate * 0.05);
    a.pitch += (tPitch - a.pitch) * clamp(a.turnRate * 0.05, 0, 1);
    if (a.bank > 0) {
      // roll ∝ lateral steering force (lean into the turn)
      const lat = a.force.x * Math.cos(a.yaw) + a.force.z * Math.sin(a.yaw);   // lateral, right-hand-turn yaw
      a.roll += (clamp(-lat * 0.02 * a.bank, -1, 1) - a.roll) * clamp(a.turnRate * 0.05, 0, 1);
    }
  }
  const h = a.handle;
  if (h) {
    h.x = px; h.y = py; h.z = pz;
    if (h.yaw !== undefined) h.yaw = a.yaw;
    if (h.pitch !== undefined) h.pitch = a.pitch;
    if (h.roll !== undefined) h.roll = a.roll;
  }
}

/** Shortest-arc angle damp (handles the ±π wrap). */
export function dampAngle(cur: number, target: number, k: number): number {
  let d = target - cur;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return cur + d * clamp(k, 0, 1);
}

// ── Named presets — one-line marquee use cases (data; pinned by tests) ──────

export const AGENT_PRESETS: Record<string, () => AgentConfig> = {
  firefly: () => ({ maxSpeed: 3, maxForce: 12, turnRate: 5, maxPitch: 1.2, behaviors: [{ kind: 'wander', jitter: 0.9, vertical: 1 }] }),
  fish: () => ({ maxSpeed: 6, maxForce: 24, turnRate: 6, bank: 0.6, maxPitch: 0.8, behaviors: [{ kind: 'wander', jitter: 0.4, vertical: 0.4 }] }),
  shoal: () => ({ maxSpeed: 7, maxForce: 30, turnRate: 7, bank: 0.7, maxPitch: 0.7, behaviors: [{ kind: 'flock', separation: 1.6, alignment: 1, cohesion: 0.9, radius: 6, neighbors: 7 }, { kind: 'wander', jitter: 0.3, weight: 0.4 }] }),
  hunter: () => ({ maxSpeed: 9, maxForce: 40, turnRate: 8, bank: 0.4, behaviors: [{ kind: 'avoid' }] }),
  bird: () => ({ maxSpeed: 11, maxForce: 30, turnRate: 5, bank: 1, maxPitch: 0.5, behaviors: [{ kind: 'flock', separation: 1.4, alignment: 1.1, cohesion: 0.8, radius: 8, neighbors: 7 }, { kind: 'wander', jitter: 0.25, weight: 0.3 }] }),
  patrol: () => ({ maxSpeed: 4, maxForce: 16, turnRate: 4, behaviors: [] }),
};

// ── The system ───────────────────────────────────────────────────────────────

export interface AgentsOptions { fixedStep?: number; hashCell?: number }

export class Agents3d {
  readonly agents: Agent3d[] = [];
  readonly fields: Field3d[] = [];
  readonly obstacles: Obstacle3d[] = [];
  /** gizmos through game.debug (velocity/force/neighbours) when true. */
  debug = false;

  private fixedDt: number;
  private acc = 0;
  private hash: SpatialHash3;
  private hashCell: number;
  private nIdx = new Int32Array(64);
  private nD2 = new Float32Array(64);
  private alpha = 1;

  constructor(opts: AgentsOptions = {}) {
    this.fixedDt = opts.fixedStep ?? 1 / 60;
    this.hashCell = opts.hashCell ?? 8;
    this.hash = new SpatialHash3(this.hashCell, 256);
  }

  spawn(config: AgentConfig): Agent3d {
    const a = new Agent3d(config);
    this.agents.push(a);
    return a;
  }

  /** A flock of `n` agents sharing a config (or bind to existing handles). */
  flock(config: AgentConfig & { preset?: keyof typeof AGENT_PRESETS }, nOrHandles: number | Array<AgentConfig['handle']>): Agent3d[] {
    const base = config.preset ? AGENT_PRESETS[config.preset]!() : {};
    const merged: AgentConfig = { ...base, ...config, behaviors: config.behaviors ?? base.behaviors };
    const out: Agent3d[] = [];
    if (typeof nOrHandles === 'number') {
      for (let i = 0; i < nOrHandles; i++) out.push(this.spawn({ ...merged, seed: (config.seed ?? 1) + i }));
    } else {
      nOrHandles.forEach((h, i) => out.push(this.spawn({ ...merged, handle: h, seed: (config.seed ?? 1) + i })));
    }
    return out;
  }

  /** Bake a recast NAVMESH (Tier-3) from geometry — real level meshes or a
   * terrain heightfield. Async: lazily loads the vendored WASM core on first
   * call. The result drops into a `navigate` behaviour like a NavGrid:
   *   const nav = await world.agents().navmesh({ from: 'terrain', heightAt, size: 400 });
   *   agents.spawn({ behaviors: [{ kind: 'navigate', grid: nav, target }] }); */
  async navmesh(opts: NavMeshOptions): Promise<NavMesh3d> {
    const nm = await buildNavMesh(opts);
    this.navmeshes.push(nm);
    return nm;
  }
  readonly navmeshes: NavMesh3d[] = [];

  attractor(o: Omit<FieldOptions, 'mode'>): Field3d { const f = new Field3d({ ...o, mode: 'attract' }); this.fields.push(f); return f; }
  repulsor(o: Omit<FieldOptions, 'mode'>): Field3d { const f = new Field3d({ ...o, mode: 'repel' }); this.fields.push(f); return f; }
  obstacle(o: ObstacleOptions): Obstacle3d { const ob = new Obstacle3d(o); this.obstacles.push(ob); return ob; }

  /** Called each display frame by World3d; runs ≤3 fixed steps + interpolates. */
  tick(dt: number): void {
    this.reap();
    for (const nm of this.navmeshes) if (!nm.dead) nm.tick(dt);   // advance any recast crowds
    if (!this.agents.length) return;
    this.acc += Math.min(dt, 0.1);
    let steps = 0;
    let stepIdx = (this._stepIdx ?? 0);
    while (this.acc >= this.fixedDt && steps < 3) {
      this.step(this.fixedDt, stepIdx);
      this.acc -= this.fixedDt; steps++; stepIdx++;
    }
    this._stepIdx = stepIdx;
    this.alpha = clamp(this.acc / this.fixedDt, 0, 1);
    for (const a of this.agents) writePose(a, this.alpha);
  }
  private _stepIdx = 0;

  /** One fixed simulation step (public for dist tests). */
  step(dt: number, stepIdx = 0): void {
    const n = this.agents.length;
    const useHash = n > 40;                          // brute force wins under ~1k pairs
    if (this.nIdx.length < 32) { this.nIdx = new Int32Array(32); this.nD2 = new Float32Array(32); }
    if (useHash) this.hash.build(this.agents);
    const ctx: StepCtx = { agents: this.agents, fields: this.fields, obstacles: this.obstacles, nIdx: this.nIdx, nD2: this.nD2, nCount: 0 };
    for (let i = 0; i < n; i++) {
      const a = this.agents[i]!;
      const solve = (stepIdx % a.tickEvery) === 0;
      if (solve) {
        // neighbours for the flock behaviour (if any)
        const fb = a.behaviors.find((b) => b.kind === 'flock') as Extract<BehaviorSpec, { kind: 'flock' }> | undefined;
        if (fb) {
          const k = Math.min(fb.neighbors ?? 7, this.nIdx.length);
          const r = fb.radius ?? 6;
          ctx.nCount = useHash ? this.hash.query(this.agents, i, r, k, this.nIdx, this.nD2) : neighborsBrute(this.agents, i, r, k, this.nIdx, this.nD2);
        } else ctx.nCount = 0;
      }
      integrateAgent(a, ctx, dt, solve);
    }
  }

  private reap(): void {
    for (let i = this.agents.length - 1; i >= 0; i--) if (this.agents[i]!.dead) this.agents.splice(i, 1);
    for (let i = this.fields.length - 1; i >= 0; i--) if (this.fields[i]!.dead) this.fields.splice(i, 1);
    for (let i = this.obstacles.length - 1; i >= 0; i--) if (this.obstacles[i]!.dead) this.obstacles.splice(i, 1);
    for (let i = this.navmeshes.length - 1; i >= 0; i--) if (this.navmeshes[i]!.dead) this.navmeshes.splice(i, 1);
  }

  /** Drop every agent/field/obstacle/navmesh (render handles are yours to kill).
   * Lets a demo tear a scene down and rebuild another. */
  clear(): void {
    this.agents.length = 0;
    this.fields.length = 0;
    this.obstacles.length = 0;
    this.navmeshes.length = 0;
    this.acc = 0;
    this._stepIdx = 0;
  }

  get count(): number { return this.agents.length; }
}
