// OBJ + MTL parsing — Phase 3 stage 1 of docs/webgpu-engine-v2-parity-plan.md:
// real asset loading. This module is the PURE text layer: no DOM, no GPU, no
// fetch — it turns .obj/.mtl source into per-material triangle soups
// (stride 8: pos/normal/uv) and plain material records, so it runs headless
// and is dist-tested in Node. The loader/GPU layer (fetching files, resolving
// texture paths, building vertex buffers) lives elsewhere and consumes this.
//
// Coverage is what the real assets in examples/assets/obj/ actually use:
// v/vt/vn/f in all four face-vertex forms, n-gons, negative indices,
// usemtl/mtllib, and files with no normals at all (deer.obj) — for those we
// bake flat face normals so the mesh still lights.

export interface ObjMaterial {
  name: string;
  /** Kd diffuse 0..1 (default [0.7, 0.7, 0.7]). */
  color: [number, number, number];
  /** map_Kd path EXACTLY as written (may be broken/absolute — the loader
   * layer decides what to do with it). */
  map?: string;
  /** Ns shininess if present. */
  ns?: number;
  /** d / (1 - Tr) opacity if present (default 1). */
  opacity?: number;
  /** Ke emissive if present. */
  emissive?: [number, number, number];
}

export interface ObjGroup {
  /** usemtl name, or null before any usemtl. */
  material: string | null;
  /** Triangulated soup, stride 8: pos(3) normal(3) uv(2), CCW as authored. */
  verts: Float32Array;
}

export interface ObjData {
  groups: ObjGroup[];
  /** The mtllib filename as written (may not match reality), or null. */
  mtllib: string | null;
  bounds: { min: [number, number, number]; max: [number, number, number] };
}

/** Parse a .mtl file into materials by name. */
export function parseMtl(text: string): Record<string, ObjMaterial> {
  const materials: Record<string, ObjMaterial> = {};
  let current: ObjMaterial | null = null;

  for (const raw of text.split('\n')) {
    // Keys are commonly indented (gun.mtl) — trim both ends (kills \r too).
    const line = raw.trim();

    if (line === '' || line.startsWith('#')) { continue; }

    const parts = line.split(/\s+/);
    const key = parts[0];

    if (key === 'newmtl') {
      current = { name: parts.slice(1).join(' '), color: [0.7, 0.7, 0.7], opacity: 1 };
      materials[current.name] = current;
      continue;
    }

    if (!current) { continue; }

    switch (key) {
      case 'Kd':
        current.color = [Number(parts[1]), Number(parts[2]), Number(parts[3])];
        break;
      case 'map_Kd':
        // Rejoin: texture paths contain spaces.
        current.map = parts.slice(1).join(' ');
        break;
      case 'Ns':
        current.ns = Number(parts[1]);
        break;
      case 'd':
        current.opacity = Number(parts[1]);
        break;
      case 'Tr':
        current.opacity = 1 - Number(parts[1]);
        break;
      case 'Ke':
        current.emissive = [Number(parts[1]), Number(parts[2]), Number(parts[3])];
        break;
      // Everything else (Ka, Ks, illum, Ni, ...) is ignored.
    }
  }

  return materials;
}

/** Parse a .obj file into per-material triangle soups. */
export function parseObj(text: string): ObjData {
  const positions: number[] = [];  // flat xyz
  const uvs: number[] = [];        // flat uv (already v-flipped)
  const normals: number[] = [];    // flat xyz

  // Groups keyed by material name; repeated/consecutive usemtl of the same
  // name MERGE into one group, ordered by first appearance. The null key is
  // faces seen before any usemtl.
  const groupOrder: (string | null)[] = [];
  const groupVerts = new Map<string | null, number[]>();
  let currentVerts: number[] | null = null;
  let currentMaterial: string | null = null;

  let mtllib: string | null = null;

  const min: [number, number, number] = [Infinity, Infinity, Infinity];
  const max: [number, number, number] = [-Infinity, -Infinity, -Infinity];

  // Scratch for one face's resolved indices (position/uv/normal, 0-based or -1).
  const fp: number[] = [];
  const ft: number[] = [];
  const fn: number[] = [];

  for (const raw of text.split('\n')) {
    const line = raw.trim();

    if (line === '' || line.startsWith('#')) { continue; }

    const parts = line.split(/\s+/);
    const key = parts[0];

    if (key === 'v') {
      const x = Number(parts[1]);
      const y = Number(parts[2]);
      const z = Number(parts[3]);
      positions.push(x, y, z);
      if (x < min[0]) { min[0] = x; } if (x > max[0]) { max[0] = x; }
      if (y < min[1]) { min[1] = y; } if (y > max[1]) { max[1] = y; }
      if (z < min[2]) { min[2] = z; } if (z > max[2]) { max[2] = z; }
      continue;
    }

    if (key === 'vt') {
      // OBJ v runs bottom-up; our textures sample top-down — flip HERE so the
      // loader/GPU layer never thinks about it.
      uvs.push(Number(parts[1]), 1 - Number(parts[2]));
      continue;
    }

    if (key === 'vn') {
      normals.push(Number(parts[1]), Number(parts[2]), Number(parts[3]));
      continue;
    }

    if (key === 'usemtl') {
      currentMaterial = parts.slice(1).join(' ');
      currentVerts = null;
      continue;
    }

    if (key === 'mtllib') {
      mtllib = parts.slice(1).join(' ');
      continue;
    }

    if (key !== 'f') { continue; }   // g/o/s and anything exotic: ignored

    // Resolve this face's vertex references. 1-based; NEGATIVE indices count
    // back from the current end of the respective array (OBJ spec).
    const n = parts.length - 1;
    fp.length = 0; ft.length = 0; fn.length = 0;

    for (let i = 1; i <= n; i++) {
      const ref = parts[i].split('/');
      const vi = Number(ref[0]);
      fp.push(vi < 0 ? positions.length / 3 + vi : vi - 1);
      const ti = ref.length > 1 && ref[1] !== '' ? Number(ref[1]) : 0;
      ft.push(ti === 0 ? -1 : ti < 0 ? uvs.length / 2 + ti : ti - 1);
      const ni = ref.length > 2 && ref[2] !== '' ? Number(ref[2]) : 0;
      fn.push(ni === 0 ? -1 : ni < 0 ? normals.length / 3 + ni : ni - 1);
    }

    if (n < 3) { continue; }

    if (!currentVerts) {
      currentVerts = groupVerts.get(currentMaterial) ?? null;
      if (!currentVerts) {
        currentVerts = [];
        groupVerts.set(currentMaterial, currentVerts);
        groupOrder.push(currentMaterial);
      }
    }
    const out = currentVerts;

    // Fan-triangulate: (0, i, i+1) for each i — fine for the convex n-gons
    // real exporters emit.
    for (let i = 1; i < n - 1; i++) {
      const tri = [0, i, i + 1];

      // Flat face normal for any corner missing a vn: cross of the triangle's
      // edges, normalized; a degenerate triangle falls back to (0, 1, 0).
      let fx = 0, fy = 1, fz = 0;
      if (fn[tri[0]] < 0 || fn[tri[1]] < 0 || fn[tri[2]] < 0) {
        const a = fp[tri[0]] * 3, b = fp[tri[1]] * 3, c = fp[tri[2]] * 3;
        const e1x = positions[b] - positions[a];
        const e1y = positions[b + 1] - positions[a + 1];
        const e1z = positions[b + 2] - positions[a + 2];
        const e2x = positions[c] - positions[a];
        const e2y = positions[c + 1] - positions[a + 1];
        const e2z = positions[c + 2] - positions[a + 2];
        const cx = e1y * e2z - e1z * e2y;
        const cy = e1z * e2x - e1x * e2z;
        const cz = e1x * e2y - e1y * e2x;
        const len = Math.hypot(cx, cy, cz);
        if (len > 1e-12) { fx = cx / len; fy = cy / len; fz = cz / len; }
      }

      for (const k of tri) {
        const p = fp[k] * 3;
        out.push(positions[p], positions[p + 1], positions[p + 2]);
        const nn = fn[k];
        if (nn < 0) {
          out.push(fx, fy, fz);
        } else {
          const o = nn * 3;
          out.push(normals[o], normals[o + 1], normals[o + 2]);
        }
        const t = ft[k];
        if (t < 0) {
          out.push(0, 0);
        } else {
          out.push(uvs[t * 2], uvs[t * 2 + 1]);
        }
      }
    }
  }

  const groups: ObjGroup[] = [];
  for (const name of groupOrder) {
    const verts = groupVerts.get(name);
    if (verts && verts.length > 0) {
      groups.push({ material: name, verts: Float32Array.from(verts) });
    }
  }

  if (positions.length === 0) {
    min[0] = min[1] = min[2] = 0;
    max[0] = max[1] = max[2] = 0;
  }

  return { groups, mtllib, bounds: { min, max } };
}
