// Device-free model DATA loading + cache. A scene's `preload(load)` calls
// `load.glb(url)` / `load.obj(url)`, which route here: fetch + parse + unit-fit
// + decode textures — all WITHOUT a GPUDevice or World3d. The result is cached
// by url. `World3d.loadObj`/`loadGlb` then turn the cached data into a live GPU
// model on demand (and fall back to loading here on a cache miss, so ad-hoc use
// still works). This is the Phaser split: preload caches the asset, the world
// instantiates from it.

import { loadText, loadBinary, loadImage, markModelLoaded, registerCacheClearer } from './assets.js';
import { parseObj, parseMtl, type ObjData, type ObjMaterial } from './obj.js';
import { parseGlb, type GlbData } from './glb.js';
import { fitVerts } from './model3d.js';

/** Parsed, unit-fit, texture-decoded model data — everything needed to build a
 *  GPU model, with no device involved. Tagged by source format. */
export type ModelData =
  | { kind: 'obj'; data: ObjData; mats: Record<string, ObjMaterial>; imgs: Array<ImageBitmap | undefined> }
  | { kind: 'glb'; data: GlbData; fit: { scale: number; center: [number, number, number] }; bitmaps: Array<ImageBitmap | undefined> };

const cache = new Map<string, Promise<ModelData>>();

// Flush on Game.destroy(): close decoded bitmaps (frees them immediately rather
// than waiting for GC) and drop the cache. Registered once when this chunk loads.
registerCacheClearer(() => {
  for (const p of cache.values()) {
    void p.then((md) => {
      const bmps = md.kind === 'glb' ? md.bitmaps : md.imgs;
      for (const b of bmps) b?.close();
    }, () => {});
  }
  cache.clear();
});

/**
 * Load + parse a model and decode its textures — all device-free — caching the
 * result by `url`. Safe from `preload()` (no World3d needed). GLB vs OBJ is
 * chosen by extension. Re-requesting a loaded url is free.
 */
export function loadModelData(url: string): Promise<ModelData> {
  const hit = cache.get(url);
  if (hit) return hit;
  const p = (/\.obj$/i.test(url) ? loadObjData(url) : loadGlbData(url))
    .then((md) => { markModelLoaded(url); return md; });
  cache.set(url, p);
  return p;
}

async function loadGlbData(url: string): Promise<ModelData> {
  const data = parseGlb(await loadBinary(url));
  // Baked (static) primitives are fit in place; the scale/center is kept for
  // the skinned/animated build path (which fits authored verts on the fly).
  const fit = fitVerts(data.primitives.filter((pr) => pr.baked).map((pr) => pr.verts), data.bounds);
  const bitmaps = await Promise.all(data.images.map(async (im) => {
    if (!im.bytes.length || !im.mimeType.startsWith('image/')) return undefined;
    try {
      return await createImageBitmap(new Blob([im.bytes.slice()], { type: im.mimeType }));
    } catch {
      return undefined;
    }
  }));
  return { kind: 'glb', data, fit, bitmaps };
}

async function loadObjData(url: string): Promise<ModelData> {
  const data = parseObj(await loadText(url));
  const dir = url.slice(0, url.lastIndexOf('/') + 1);
  const base = url.slice(dir.length).replace(/\.obj$/i, '');
  // OBJs lie: try the declared mtllib, then <basename>.mtl beside the file.
  let mats: Record<string, ObjMaterial> = {};
  for (const cand of [data.mtllib, base + '.mtl']) {
    if (!cand) continue;
    try { mats = parseMtl(await loadText(dir + cand)); break; } catch { /* try the next candidate */ }
  }
  fitVerts(data.groups.map((g) => g.verts), data.bounds);
  // One diffuse bitmap per group (map_Kd resolves by BASENAME beside the obj;
  // a missing texture silently falls back to the material colour at build time).
  const imgs = await Promise.all(data.groups.map(async (g) => {
    const mat = g.material ? mats[g.material] : undefined;
    if (!mat?.map) return undefined;
    const file = mat.map.split(/[\\/]/).pop()!;
    try { return await createImageBitmap(await loadImage(dir + file)); } catch { return undefined; }
  }));
  return { kind: 'obj', data, mats, imgs };
}
