// 3D particles — the 2D pool's y-up twin, living on the World3d layer as
// `world.fx`. CPU-simulated, fully pooled, DOM/GPU-free (headlessly
// testable); the World3d renderer draws every live particle as ONE instanced
// draw of camera-facing quads — soft SDF discs, atlas frames, or SDF rings —
// premultiplied blend where `add` writes alpha 0 (pure additive), depth-
// tested against solids, never written (the translucent-group recipe).
//
// Scale note: the 3D world is MESH scale (a crate is ~1 unit), not the 2D
// world's hundreds of units — defaults here are ~1/10 of the 2D system's,
// and VfxDef bursts (2D-tuned data) are scaled by 0.1 on the way in, the
// same convention as world.trail() widths.
//
// Also owns 3D BURSTS: the same VfxDef.burst recipe layers as the 2D
// VfxSystem — particle emits ride this pool, expanding rings + flash discs
// render as camera-facing SDF quads through the same instanced draw.

import { eulerToQuat, quatRotate } from './transform3d.js';
import { resolveRamp, type RampName } from './particles.js';
import { rgba, type Rgba } from './color.js';
import type { VfxDef } from './vfx.js';

export interface Emit3dOptions {
  x: number;
  y: number;
  z: number;
  /** Particles in this burst (default 12). */
  count?: number;
  /** Initial speed ± speedVar, world units/s (default 3 ± 1.2). speedVar: 0 = a clean shell. */
  speed?: number;
  speedVar?: number;
  /** Emission cone axis (any length; default: none = every direction). */
  dir?: { x?: number; y?: number; z?: number };
  /** Cone full angle around `dir`, radians (default 2π = a full sphere). */
  spread?: number;
  /** Jitter the spawn point within this sphere radius. Default 0 = point. */
  spawnRadius?: number;
  /** Spawn along a 3D path (Path3d or any { at(t) → point }): each particle
   * starts at a random arc-length fraction; x/y/z become an OFFSET. */
  path?: { at(t: number): { x: number; y: number; z: number } };
  /** Spawn ON a mesh's surface: a SurfaceSampler over its unit geometry
   * (world.surface(mesh) builds one). Pair with `on` for the live
   * transform; x/y/z become an offset. Without an explicit `dir`,
   * particles launch along the surface NORMAL. */
  surface?: SurfaceSampler;
  /** The live handle whose transform places `surface` samples (a Mesh3d:
   * x/y/z, yaw/pitch/roll, w/h/d are read at emit time). */
  on?: { x: number; y: number; z: number; yaw: number; pitch: number; roll: number; w: number; h: number; d: number };
  /** Particles sample the CLUSTERED LIGHTS (world.light) + ambient — smoke
   * that picks up lantern colour. Additive particles usually want false. */
  lit?: boolean;
  /** Spawn uniformly inside a box of these extents (centred on x/y/z). */
  box?: { w?: number; h?: number; d?: number };
  /** Spawn on a horizontal (XZ) ring of this radius (warp fields, halos). */
  ring?: number;
  /** Lifetime seconds ± lifeVar (default 0.7 ± 0.3). */
  life?: number;
  lifeVar?: number;
  /** Quad half-size (disc radius), world units ± sizeVar (default 0.12 ± 0.05). */
  size?: number;
  sizeVar?: number;
  /** Size over life: true = shrink to nothing, false = constant, or the
   * FINAL size as a fraction of `size` — 0.5 = half, and >1 GROWS
   * (billowing smoke: 2.5 = swells to 2.5×). Default true. */
  shrink?: boolean | number;
  /** Fade alpha over life (default true). */
  fade?: boolean;
  /** DOWNWARD acceleration, units/s² (y-up: positive pulls toward the floor).
   * Negative = embers rising. Default 0. */
  gravity?: number;
  /** Velocity damping per second, 0..1 (default 0). */
  drag?: number;
  /** Smooth lateral (XZ) wander acceleration, units/s² — snow, dust motes. */
  sway?: number;
  /** Sway oscillation frequency, cycles/s (default 1.5). */
  swayFreq?: number;
  /** One colour… */
  color?: string;
  /** …or a palette picked per particle. */
  colors?: string[];
  /** A colour ramp walked over the particle's life — a RAMPS name ('fire',
   * 'smoke', …) or custom hex stops. Overrides color/colors. */
  ramp?: RampName | string[];
  /** Alpha multiplier for the whole emit (default 1). */
  alpha?: number;
  /** Per-particle brightness flicker 0..1 (fireflies, embers, magic dust). */
  twinkle?: number;
  /** Additive blend — glows/fire/sparks (default false = normal alpha). */
  add?: boolean;
  /** Untextured falloff: 1 (default) = a gaussian glow puff (the classic
   * radial particle texture, analytic), 0 = a crisp AA disc. Ignored with
   * `frame`. */
  soft?: number;
  /** Draw an atlas frame instead of the glow puff (star/flare/snowflake/
   * debris textures — `particleCanvas()` generates the classics at
   * runtime; `color`/`ramp` tint the texture). */
  frame?: number;
  /** Random spin up to ±spin rad/s (spins the camera-facing quad). */
  spin?: number;
}

interface P3 {
  x: number; y: number; z: number;
  vx: number; vy: number; vz: number;
  age: number; life: number; size: number;
  rot: number; spin: number;
  r: number; g: number; b: number; a: number;
  gravity: number; drag: number;
  sway: number; swayFreq: number; seed: number; twinkle: number;
  ramp: Rgba[] | null;
  fade: boolean; endSize: number; add: boolean; frame: number; soft: number; lit: boolean;
}

export interface Burst3dOptions {
  /** Cone axis for the recipe's directional emits (layers with a `spread`). */
  dir?: { x?: number; y?: number; z?: number };
  /** Size multiplier from the def's 2D-tuned numbers (default 0.1 — the
   * same 2D→3D convention as trail widths). */
  scale?: number;
  /** Rings lie FLAT in the world XZ plane (default true — a camera-facing
   * ring reads as a 2D effect pasted on the screen; a flat one reads as a
   * shockwave IN the world). false = camera-facing. */
  flat?: boolean;
}

interface LiveBurst3d {
  def: VfxDef;
  x: number; y: number; z: number;
  dir: { x: number; y: number; z: number } | null;
  scale: number;
  flat: boolean;
  age: number;
  fired: boolean[];
}

/** The per-instance quad the renderer packs. mode: 0 soft disc, 1 atlas
 * frame, 2 ring (p = stroke thickness as a fraction of the radius). */
/**
 * Area-weighted sampling over a stride-8 triangle soup — the MESH-SURFACE
 * emitter shape. Build once per geometry (the CDF is baked); sample() picks
 * a triangle proportionally to its area and a uniform barycentric point on
 * it, returning position AND face normal (particles can launch along it).
 * Pure — dist-tested.
 */
export class SurfaceSampler {
  private cdf: Float64Array;
  private verts: Float32Array;
  constructor(verts: Float32Array) {
    this.verts = verts;
    const tris = Math.floor(verts.length / 24);
    this.cdf = new Float64Array(tris);
    let acc = 0;
    for (let t = 0; t < tris; t++) {
      const o = t * 24;
      const ux = verts[o + 8] - verts[o], uy = verts[o + 9] - verts[o + 1], uz = verts[o + 10] - verts[o + 2];
      const vx = verts[o + 16] - verts[o], vy = verts[o + 17] - verts[o + 1], vz = verts[o + 18] - verts[o + 2];
      const cx = uy * vz - uz * vy, cy = uz * vx - ux * vz, cz = ux * vy - uy * vx;
      acc += Math.hypot(cx, cy, cz) * 0.5;
      this.cdf[t] = acc;
    }
  }
  /** r1..r3 are uniform randoms 0..1 (pass your seeded rng's outputs). */
  sample(r1: number, r2: number, r3: number): { x: number; y: number; z: number; nx: number; ny: number; nz: number } {
    const total = this.cdf[this.cdf.length - 1] || 1;
    const target = r1 * total;
    let lo = 0, hi = this.cdf.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.cdf[mid] < target) lo = mid + 1; else hi = mid;
    }
    const o = lo * 24, v = this.verts;
    // Uniform barycentric via sqrt.
    const su = Math.sqrt(r2);
    const b0 = 1 - su, b1 = su * (1 - r3), b2 = su * r3;
    const px = v[o] * b0 + v[o + 8] * b1 + v[o + 16] * b2;
    const py = v[o + 1] * b0 + v[o + 9] * b1 + v[o + 17] * b2;
    const pz = v[o + 2] * b0 + v[o + 10] * b1 + v[o + 18] * b2;
    const ux = v[o + 8] - v[o], uy = v[o + 9] - v[o + 1], uz = v[o + 10] - v[o + 2];
    const wx = v[o + 16] - v[o], wy = v[o + 17] - v[o + 1], wz = v[o + 18] - v[o + 2];
    let nx = uy * wz - uz * wy, ny = uz * wx - ux * wz, nz = ux * wy - uy * wx;
    const l = Math.hypot(nx, ny, nz) || 1;
    return { x: px, y: py, z: pz, nx: nx / l, ny: ny / l, nz: nz / l };
  }
}

export type Fx3dWriter = (
  x: number, y: number, z: number, size: number, rot: number,
  mode: number, r: number, g: number, b: number, a: number,
  add: boolean, frame: number, p: number, lit?: boolean,
) => void;

export class Particles3d {
  private pool: P3[] = [];
  private alive = 0;
  private clock = 0;
  private bursts: LiveBurst3d[] = [];

  /** Pass a seeded rng (e.g. mulberry32) for deterministic headless tests. */
  constructor(private rng: () => number = Math.random) {}

  /** Live particle count (bursts' rings/flashes not included). */
  get count(): number {
    return this.alive;
  }

  /** Spawn a burst of particles. Call once for an explosion, every frame for a stream. */
  emit(opts: Emit3dOptions): void {
    const rng = this.rng;
    const count = opts.count ?? 12;
    const speed = opts.speed ?? 3;
    const speedVar = opts.speedVar ?? speed * 0.4;
    const spread = opts.spread ?? Math.PI * 2;
    const spawnR = opts.spawnRadius ?? 0;
    const life = opts.life ?? 0.7;
    const lifeVar = opts.lifeVar ?? 0.3;
    const size = opts.size ?? 0.12;
    const sizeVar = opts.sizeVar ?? 0.05;
    const alpha = opts.alpha ?? 1;
    const ramp = opts.ramp ? resolveRamp(opts.ramp) : null;
    const palette = opts.colors ?? [opts.color ?? '#ffffff'];
    const endSize = typeof opts.shrink === 'number'
      ? Math.max(0, opts.shrink)              // >1 = grows (smoke billows)
      : (opts.shrink ?? true) ? 0 : 1;

    // Cone basis around dir (only when a direction narrows the sphere).
    const d = opts.dir;
    let ax = 0, ay = 1, az = 0;
    let bx = 1, by = 0, bz = 0, cx = 0, cy = 0, cz = 1;
    const directional = !!d && spread < Math.PI * 2 - 1e-6;
    if (directional) {
      const dl = Math.hypot(d!.x ?? 0, d!.y ?? 0, d!.z ?? 0) || 1;
      ax = (d!.x ?? 0) / dl; ay = (d!.y ?? 0) / dl; az = (d!.z ?? 0) / dl;
      // Perpendicular pair: cross with whichever axis is least aligned with a.
      const ux = Math.abs(ax) < 0.9 ? 1 : 0;
      const uy = ux ? 0 : 1;
      bx = ay * 0 - az * uy; by = az * ux - ax * 0; bz = ax * uy - ay * ux;
      const bl = Math.hypot(bx, by, bz) || 1;
      bx /= bl; by /= bl; bz /= bl;
      cx = ay * bz - az * by; cy = az * bx - ax * bz; cz = ax * by - ay * bx;
    }

    for (let i = 0; i < count; i++) {
      const p = this.alive < this.pool.length ? this.pool[this.alive] : (this.pool.push(blank3()), this.pool[this.alive]);
      this.alive++;
      // Direction: uniform over the sphere, or uniform over the cone's solid angle.
      let nx: number, ny: number, nz: number;
      if (directional) {
        const cosT = 1 - rng() * (1 - Math.cos(spread / 2));
        const sinT = Math.sqrt(Math.max(0, 1 - cosT * cosT));
        const phi = rng() * Math.PI * 2;
        const pb = Math.cos(phi) * sinT, pc = Math.sin(phi) * sinT;
        nx = ax * cosT + bx * pb + cx * pc;
        ny = ay * cosT + by * pb + cy * pc;
        nz = az * cosT + bz * pb + cz * pc;
      } else {
        // Uniform sphere direction (Marsaglia via z + angle).
        const zz = rng() * 2 - 1;
        const phi = rng() * Math.PI * 2;
        const s = Math.sqrt(Math.max(0, 1 - zz * zz));
        nx = Math.cos(phi) * s; ny = zz; nz = Math.sin(phi) * s;
      }
      const v = Math.max(0, speed + (rng() - 0.5) * 2 * speedVar);
      p.x = opts.x; p.y = opts.y; p.z = opts.z;
      // PATH emitter shape (Phase 5): spawn along a spline — x/y/z become
      // an offset. Structural type: any {at(t)} works, Path3d is the one.
      if (opts.path) {
        const pp = opts.path.at(rng());
        p.x += pp.x; p.y += pp.y; p.z += pp.z;
      }
      // MESH-SURFACE emitter shape: sample the unit geometry, scale by the
      // live handle's dims, rotate by its euler, translate to it. Without
      // an explicit dir the particle launches along the surface normal.
      if (opts.surface) {
        const sp = opts.surface.sample(rng(), rng(), rng());
        const on = opts.on;
        if (on) {
          const q = eulerToQuat(on.yaw, on.pitch, on.roll);
          const rp = quatRotate(q, sp.x * on.w, sp.y * on.h, sp.z * on.d);
          p.x += on.x + rp[0]; p.y += on.y + rp[1]; p.z += on.z + rp[2];
          if (!d) {
            const rn = quatRotate(q, sp.nx / on.w, sp.ny / on.h, sp.nz / on.d);
            const nl = Math.hypot(rn[0], rn[1], rn[2]) || 1;
            nx = rn[0] / nl; ny = rn[1] / nl; nz = rn[2] / nl;
          }
        } else {
          p.x += sp.x; p.y += sp.y; p.z += sp.z;
          if (!d) { nx = sp.nx; ny = sp.ny; nz = sp.nz; }
        }
      }
      if (opts.ring) {
        const ra = rng() * Math.PI * 2;
        p.x += Math.cos(ra) * opts.ring;
        p.z += Math.sin(ra) * opts.ring;
      }
      if (opts.box) {
        p.x += (rng() - 0.5) * (opts.box.w ?? 0);
        p.y += (rng() - 0.5) * (opts.box.h ?? 0);
        p.z += (rng() - 0.5) * (opts.box.d ?? 0);
      }
      if (spawnR > 0) {
        // Uniform in a sphere: direction × cbrt-radius.
        const zz = rng() * 2 - 1;
        const phi = rng() * Math.PI * 2;
        const s = Math.sqrt(Math.max(0, 1 - zz * zz));
        const rr = Math.cbrt(rng()) * spawnR;
        p.x += Math.cos(phi) * s * rr;
        p.y += zz * rr;
        p.z += Math.sin(phi) * s * rr;
      }
      p.vx = nx * v; p.vy = ny * v; p.vz = nz * v;
      p.age = 0;
      p.life = Math.max(0.05, life + (rng() - 0.5) * 2 * lifeVar);
      p.size = Math.max(0.005, size + (rng() - 0.5) * 2 * sizeVar);
      p.rot = 0;
      p.spin = (rng() - 0.5) * 2 * (opts.spin ?? 0);
      const first = ramp ? ramp[0] : rgba(palette[(rng() * palette.length) | 0]);
      p.r = first[0]; p.g = first[1]; p.b = first[2]; p.a = first[3] * alpha;
      p.ramp = ramp;
      p.gravity = opts.gravity ?? 0;
      p.drag = opts.drag ?? 0;
      p.sway = opts.sway ?? 0;
      p.swayFreq = opts.swayFreq ?? 1.5;
      p.seed = rng() * Math.PI * 2;
      p.twinkle = opts.twinkle ?? 0;
      p.fade = opts.fade ?? true;
      p.endSize = endSize;
      p.add = opts.add ?? false;
      p.frame = opts.frame ?? -1;
      p.soft = opts.soft ?? 1;
      p.lit = opts.lit ?? false;
    }
  }

  /**
   * Trigger a one-shot VfxDef.burst recipe at a point — the same defs as the
   * 2D `scene.vfx.burst()` ('impact', 'shockwave', …): particle layers ride
   * this pool, rings + flashes render as camera-facing quads. The def's
   * 2D-tuned sizes/speeds are scaled by `opts.scale` (default 0.1).
   */
  burst(def: VfxDef, x: number, y: number, z: number, opts: Burst3dOptions = {}): void {
    if (!def.burst?.length) return;
    const d = opts.dir;
    this.bursts.push({
      def, x, y, z,
      dir: d ? { x: d.x ?? 0, y: d.y ?? 0, z: d.z ?? 0 } : null,
      scale: opts.scale ?? 0.1,
      flat: opts.flat ?? true,
      age: 0,
      fired: def.burst.map(() => false),
    });
  }

  /** Age + integrate particles, run burst recipes (world.tick calls this). */
  /**
   * A CONTINUOUS emitter — the ONLY correct way to run a steady effect
   * (fire, smoke, drips, auras). `rate` is particles per SECOND, wall
   * clock: the engine owns the accumulator, so the alive count is
   * rate × life at ANY refresh rate — per-frame emit() loops double on a
   * 120 Hz display (never do that; emit() is for one-shot BURSTS).
   * Every option is live: mutate handle.rate, handle.x/y/z, handle.on…
   * kill() stops it (existing particles age out naturally).
   */
  stream(opts: Emit3dOptions & { rate: number }): Emit3dOptions & { rate: number; dead: boolean; kill(): void } {
    const h = Object.assign({}, opts, {
      dead: false,
      kill(): void { this.dead = true; },
    });
    this.streams.push({ h, acc: 0 });
    return h;
  }

  private streams: Array<{ h: Emit3dOptions & { rate: number; dead: boolean }; acc: number }> = [];

  update(dt: number): void {
    // Tick the streams first: wall-clock accumulation, floor emits.
    for (let i = this.streams.length - 1; i >= 0; i--) {
      const st = this.streams[i];
      if (st.h.dead) { this.streams.splice(i, 1); continue; }
      st.acc += st.h.rate * dt;
      const n = Math.floor(st.acc);
      st.acc -= n;
      if (n > 0) this.emit({ ...st.h, count: n });
    }
    this.updateSim(dt);
  }

  private updateSim(dt: number): void {
    this.clock += dt;
    for (let i = this.alive - 1; i >= 0; i--) {
      const p = this.pool[i];
      p.age += dt;
      if (p.age >= p.life) {
        this.alive--;
        this.pool[i] = this.pool[this.alive];
        this.pool[this.alive] = p; // keep it pooled
        continue;
      }
      const damp = p.drag > 0 ? Math.max(0, 1 - p.drag * dt) : 1;
      p.vx *= damp;
      p.vz *= damp;
      p.vy = p.vy * damp - p.gravity * dt;      // y-up: gravity pulls DOWN
      if (p.sway) {
        const w = this.clock * p.swayFreq + p.seed;
        p.vx += Math.cos(w) * p.sway * dt;
        p.vz += Math.sin(w * 1.3) * p.sway * dt;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.z += p.vz * dt;
      p.rot += p.spin * dt;
    }
    // Bursts: fire emit layers at their delay; drop when every layer is spent.
    for (let i = this.bursts.length - 1; i >= 0; i--) {
      const b = this.bursts[i];
      b.age += dt;
      let done = true;
      b.def.burst!.forEach((layer, li) => {
        const delay = layer.delay ?? 0;
        if (!b.fired[li] && b.age >= delay) {
          b.fired[li] = true;
          if (layer.emit) {
            const e = layer.emit;
            const s = b.scale;
            this.emit({
              x: b.x, y: b.y, z: b.z,
              count: e.count,
              speed: (e.speed ?? 90) * s,
              speedVar: (e.speedVar ?? 40) * s,
              dir: b.dir ?? undefined,
              spread: e.spread,
              spawnRadius: e.spawnRadius != null ? e.spawnRadius * s : undefined,
              life: e.life, lifeVar: e.lifeVar,
              size: (e.size ?? 4) * s,
              sizeVar: (e.sizeVar ?? 2) * s,
              shrink: e.shrink, fade: e.fade,
              gravity: e.gravity != null ? e.gravity * s : undefined,
              drag: e.drag,
              sway: e.sway != null ? e.sway * s : undefined,
              swayFreq: e.swayFreq,
              color: e.color, colors: e.colors, ramp: e.ramp,
              alpha: e.alpha, twinkle: e.twinkle,
              add: e.add, frame: e.frame, spin: e.spin, soft: e.soft,
            });
          }
        }
        const t = layer.ring?.time ?? layer.flash?.time ?? 0;
        if (b.age < delay + t) done = false;
        if (!b.fired[li]) done = false;
      });
      if (done) this.bursts.splice(i, 1);
    }
  }

  /** Push every live particle + burst ring/flash quad to the writer.
   * Returns the instance count. (The renderer owns the buffer format.) */
  pack(write: Fx3dWriter): number {
    let n = 0;
    for (let i = 0; i < this.alive; i++) {
      const p = this.pool[i];
      const t = p.age / p.life;
      let alpha = p.fade ? p.a * (1 - t) : p.a;
      if (p.twinkle > 0) {
        alpha *= 1 - p.twinkle * (0.5 + 0.5 * Math.sin(this.clock * 11 + p.seed * 7));
      }
      const size = p.size * (1 - (1 - p.endSize) * t);
      if (alpha <= 0.004 || size <= 0.002) continue;
      let r = p.r, g = p.g, b = p.b;
      if (p.ramp) {
        const ci = t * (p.ramp.length - 1);
        const i0 = Math.min(p.ramp.length - 1, ci | 0);
        const i1 = Math.min(p.ramp.length - 1, i0 + 1);
        const f = ci - i0;
        const c0 = p.ramp[i0], c1 = p.ramp[i1];
        r = c0[0] + (c1[0] - c0[0]) * f;
        g = c0[1] + (c1[1] - c0[1]) * f;
        b = c0[2] + (c1[2] - c0[2]) * f;
      }
      write(p.x, p.y, p.z, size, p.rot, p.frame >= 0 ? 1 : 0, r, g, b, alpha, p.add, p.frame, p.soft, p.lit);
      n++;
    }
    for (const b of this.bursts) {
      b.def.burst!.forEach((layer, li) => {
        const delay = layer.delay ?? 0;
        const local = b.age - delay;
        if (local < 0 || !b.fired[li]) return;
        if (layer.ring) {
          const rr = layer.ring;
          const k = Math.min(1, local / rr.time);
          if (k < 1) {
            const from = (rr.from ?? 6) * b.scale;
            const radius = from + ((rr.to * b.scale) - from) * k;
            const c = rgba(rr.color ?? '#ffffff');
            const thick = Math.min(1, Math.max(0.02, ((rr.width ?? 3) * b.scale * (1 - k * 0.6)) / Math.max(0.001, radius)));
            write(b.x, b.y, b.z, radius, 0, b.flat ? 3 : 2, c[0], c[1], c[2], (1 - k) * (rr.add ? 1 : 0.8) * c[3], !!rr.add, -1, thick);
            n++;
          }
        }
        if (layer.flash) {
          const f = layer.flash;
          const k = Math.min(1, local / f.time);
          if (k < 1) {
            const c = rgba(f.color ?? '#ffffff');
            write(b.x, b.y, b.z, f.radius * b.scale * (0.6 + 0.4 * k), 0, 0, c[0], c[1], c[2], (1 - k) * 0.9 * c[3], true, -1, 1);
            n++;
          }
        }
      });
    }
    return n;
  }

  /** Kill everything (world teardown / scene change). */
  clear(): void {
    this.alive = 0;
    this.bursts = [];
  }
}

function blank3(): P3 {
  return {
    x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, age: 0, life: 1, size: 0.1, rot: 0, spin: 0,
    r: 1, g: 1, b: 1, a: 1, gravity: 0, drag: 0,
    sway: 0, swayFreq: 1.5, seed: 0, twinkle: 0, ramp: null,
    fade: true, endSize: 0, add: false, frame: -1, soft: 1, lit: false,
  };
}
