// VOXEL EDITOR — the reusable "point at a block and change it" logic every
// build/mine game repeats: a per-frame raycast, the Minecraft target OUTLINE
// and placement GHOST, held-button cadence, optional per-block hardness
// (multi-hit mining), and an anti-embed guard. It carries NO effects of its
// own — no particles, no dropped items. Instead it EMITS events
// (`onHit`/`onBreak`/`onPlace`, also returned from `update`) so the game spawns
// whatever debris, drops, sounds or score it likes. Pair it with the
// [minecraft-controls] rig for the input, or drive it from any camera.
//
//   const edit = world.voxelEditor(vox, { reach: 12, onBreak: e => shatter(e) });
//   edit.block = BLOCK.stone;                      // what a place drops
//   edit.update(dt, { origin: eye, dir: mc.forward(), mining: mc.mining, placing: mc.placing });
//
// It owns the visuals (a `world.lines` outline + a `world.box` ghost); the game
// owns the consequences.

import { BLOCK } from './voxel3d.js';
import type { VoxelHit } from './voxel3d.js';

/** A placed/broken block. `id` is the block placed, or the one that was there. */
export interface VoxelEditEvent { x: number; y: number; z: number; id: number; }
/** A single mining hit — `progress` is 0..1 toward the block breaking. */
export interface VoxelHitEvent extends VoxelEditEvent { progress: number; }

/** What the editor changed this frame (also delivered to the callbacks). */
export interface VoxelEditResult {
  /** The committed (debounced) target block, or null when nothing's in reach. */
  target: VoxelHit | null;
  /** The empty cell a place would fill (target + face normal), or null. */
  placeCell: { x: number; y: number; z: number } | null;
  /** True when placing here is refused by the `blocked` guard. */
  blocked: boolean;
  hit: VoxelHitEvent | null;
  broke: VoxelEditEvent | null;
  placed: VoxelEditEvent | null;
}

export interface VoxelEditorOptions {
  /** How far the ray reaches, in blocks (default 8 ≈ Minecraft creative). */
  reach?: number;
  /** Block id a place drops (also settable live as `editor.block`). Default stone. */
  block?: number;
  /** Hits needed to break a block, by id — return 1 for instant/creative
   *  (the default). Higher = survival mining that takes several hits. */
  hardness?: (id: number) => number;
  /** Seconds between mining hits while LEFT is held (default 0.15). */
  breakRate?: number;
  /** Seconds between placements while RIGHT is held (default 0.2). */
  placeRate?: number;
  /** Draw the black wireframe outline on the aimed block (default true). */
  outline?: boolean;
  /** Draw the translucent placement ghost (default true). Tint via `ghostColor`. */
  ghost?: boolean;
  /** Ghost tint (also settable live as `editor.ghostColor`). Default white. */
  ghostColor?: string;
  /** Refuse to place into these cells (e.g. the player's body) — the ghost
   *  turns red and no block is placed. Default: nothing blocked. */
  blocked?: (x: number, y: number, z: number) => boolean;
  /** Frames a new target must hold before it commits — de-twitches the outline
   *  at block seams (default 3; 0 = off, instant). */
  debounce?: number;
  onHit?: (e: VoxelHitEvent) => void;
  onBreak?: (e: VoxelEditEvent) => void;
  onPlace?: (e: VoxelEditEvent) => void;
}

/** Per-frame ray + button state fed to `update`. */
export interface VoxelEditInput {
  origin: { x: number; y: number; z: number };
  dir: { x: number; y: number; z: number };
  /** LEFT held — mine/break the aimed block. */
  mining?: boolean;
  /** RIGHT held — place `editor.block` on the aimed face. */
  placing?: boolean;
}

// The 12 edges of a unit cube (±0.5) as polylines for the outline shape.
function cubeOutline(): Array<Array<[number, number, number]>> {
  const c: [number, number, number][] = [
    [-0.5, -0.5, -0.5], [0.5, -0.5, -0.5], [0.5, -0.5, 0.5], [-0.5, -0.5, 0.5],
    [-0.5, 0.5, -0.5], [0.5, 0.5, -0.5], [0.5, 0.5, 0.5], [-0.5, 0.5, 0.5],
  ];
  const e = (a: number, b: number): [[number, number, number], [number, number, number]] => [c[a], c[b]];
  return [e(0, 1), e(1, 2), e(2, 3), e(3, 0), e(4, 5), e(5, 6), e(6, 7), e(7, 4), e(0, 4), e(1, 5), e(2, 6), e(3, 7)];
}

// The bits of the voxel handle + world the editor needs (structural, so it's
// decoupled from the GPU classes and testable headless). `Voxels3d` and
// `World3d` satisfy these.
interface EditVox {
  get(x: number, y: number, z: number): number;
  set(x: number, y: number, z: number, id: number): void;
  raycast(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, maxDist?: number): VoxelHit | null;
}
interface OutlineHandle { x: number; y: number; z: number; alpha: number; scale: number; }
interface GhostHandle { x: number; y: number; z: number; color: string; alpha: number; }
interface EditWorld {
  lines(polylines: Array<Array<[number, number, number]>>, opts: { color?: string; width?: number; alpha?: number }): OutlineHandle;
  box(cfg: { x: number; y: number; z: number; w: number; h: number; d: number; color: string; alpha: number; blob?: boolean }): GhostHandle;
}

const BLOCKED_TINT = '#c0392b';

/**
 * Targets and edits a voxel world for the player. Construct with
 * `world.voxelEditor(vox, opts)`; call `update(dt, input)` each frame with the
 * camera ray + button state. It positions the outline/ghost, applies breaks
 * (respecting hardness) and places (respecting the anti-embed guard), and fires
 * `onHit`/`onBreak`/`onPlace` — the game turns those into effects.
 */
export class VoxelEditor {
  /** Block id a place drops. Set from the hotbar each frame if you like. */
  block: number;
  /** Ghost tint (the selected block's colour, usually). */
  ghostColor: string;
  /** Ray reach in blocks — live-mutable. */
  reach: number;

  private vox: EditVox;
  private o: Required<Omit<VoxelEditorOptions, 'block' | 'ghostColor' | 'reach' | 'hardness' | 'blocked' | 'onHit' | 'onBreak' | 'onPlace'>>;
  private hardness: (id: number) => number;
  private blockedFn: (x: number, y: number, z: number) => boolean;
  private cbHit?: (e: VoxelHitEvent) => void;
  private cbBreak?: (e: VoxelEditEvent) => void;
  private cbPlace?: (e: VoxelEditEvent) => void;

  private outline: OutlineHandle | null = null;
  private ghost: GhostHandle | null = null;

  // Debounce.
  private committed: VoxelHit | null = null;
  private pendKey = 'none';
  private pendN = 0;
  // Cadence + mining progress.
  private breakCd = 0;
  private placeCd = 0;
  private mineKey = 'none';
  private mineHits = 0;

  constructor(world: EditWorld, vox: EditVox, opts: VoxelEditorOptions = {}) {
    this.vox = vox;
    this.block = opts.block ?? BLOCK.stone;
    this.ghostColor = opts.ghostColor ?? '#ffffff';
    this.reach = opts.reach ?? 8;
    this.hardness = opts.hardness ?? (() => 1);
    this.blockedFn = opts.blocked ?? (() => false);
    this.cbHit = opts.onHit; this.cbBreak = opts.onBreak; this.cbPlace = opts.onPlace;
    this.o = {
      breakRate: opts.breakRate ?? 0.15,
      placeRate: opts.placeRate ?? 0.2,
      outline: opts.outline ?? true,
      ghost: opts.ghost ?? true,
      debounce: opts.debounce ?? 3,
    };
    if (this.o.outline) { this.outline = world.lines(cubeOutline(), { color: '#0a0a0a', width: 2.5, alpha: 0 }); this.outline.scale = 1.01; }
    if (this.o.ghost) { this.ghost = world.box({ x: 0, y: -1e4, z: 0, w: 0.92, h: 0.92, d: 0.92, color: '#ffffff', alpha: 0, blob: false }); }
  }

  private key(h: VoxelHit | null): string {
    return h ? `${h.x},${h.y},${h.z}|${h.nx},${h.ny},${h.nz}` : 'none';
  }

  /** Raycast + de-twitch: commit a new target only after it holds `debounce`
   *  frames, so the outline doesn't flip-flop on block seams. */
  private acquire(input: VoxelEditInput): VoxelHit | null {
    const o = input.origin, d = input.dir;
    const raw = this.vox.raycast(o.x, o.y, o.z, d.x, d.y, d.z, this.reach);
    if (this.o.debounce <= 0) { this.committed = raw; return raw; }
    if (this.key(raw) === this.key(this.committed)) { this.pendN = 0; return this.committed; }
    if (this.key(raw) === this.pendKey) this.pendN++; else { this.pendKey = this.key(raw); this.pendN = 1; }
    if (this.pendN >= this.o.debounce) { this.committed = raw; this.pendN = 0; }
    return this.committed;
  }

  /** One frame: aim, draw outline/ghost, apply held break/place, emit events. */
  update(dt: number, input: VoxelEditInput): VoxelEditResult {
    const hit = this.acquire(input);
    const res: VoxelEditResult = { target: hit, placeCell: null, blocked: false, hit: null, broke: null, placed: null };

    // Placement cell + anti-embed check.
    let px = 0, py = 0, pz = 0;
    if (hit) {
      px = hit.x + hit.nx; py = hit.y + hit.ny; pz = hit.z + hit.nz;
      res.placeCell = { x: px, y: py, z: pz };
      res.blocked = this.blockedFn(px, py, pz);
    }

    // Visuals.
    if (this.outline) { if (hit) { this.outline.x = hit.x + 0.5; this.outline.y = hit.y + 0.5; this.outline.z = hit.z + 0.5; this.outline.alpha = 1; } else this.outline.alpha = 0; }
    if (this.ghost) {
      if (hit) { this.ghost.x = px + 0.5; this.ghost.y = py + 0.5; this.ghost.z = pz + 0.5; this.ghost.color = res.blocked ? BLOCKED_TINT : this.ghostColor; this.ghost.alpha = res.blocked ? 0.3 : 0.4; }
      else this.ghost.alpha = 0;
    }

    // Mining: accumulate hits on the aimed block; break when hardness is met.
    // The cadence timer (breakCd) PERSISTS across target changes — critical:
    // breaking a block reveals the one behind it, so if we reset the timer on
    // every target change a held button would break one block PER FRAME. Only
    // the per-block progress (mineHits) resets on a new target or a release.
    this.breakCd -= dt;
    if (hit && input.mining) {
      if (this.mineKey !== this.key(hit)) { this.mineKey = this.key(hit); this.mineHits = 0; }
      if (this.breakCd <= 0) {
        const id = this.vox.get(hit.x, hit.y, hit.z);
        const need = Math.max(1, this.hardness(id));
        this.mineHits++;
        this.breakCd = this.o.breakRate;
        const hEv: VoxelHitEvent = { x: hit.x, y: hit.y, z: hit.z, id, progress: Math.min(1, this.mineHits / need) };
        res.hit = hEv; this.cbHit?.(hEv);
        if (this.mineHits >= need) {
          this.vox.set(hit.x, hit.y, hit.z, BLOCK.air);
          const bEv: VoxelEditEvent = { x: hit.x, y: hit.y, z: hit.z, id };
          res.broke = bEv; this.cbBreak?.(bEv);
          this.mineKey = 'none'; this.mineHits = 0;
        }
      }
    } else { this.mineKey = 'none'; this.mineHits = 0; }

    // Placing: drop `block` on the aimed face, gated + never into a blocked cell.
    this.placeCd -= dt;
    if (hit && input.placing && !res.blocked && this.placeCd <= 0) {
      this.vox.set(px, py, pz, this.block);
      this.placeCd = this.o.placeRate;
      const pEv: VoxelEditEvent = { x: px, y: py, z: pz, id: this.block };
      res.placed = pEv; this.cbPlace?.(pEv);
    }

    return res;
  }
}
