// MODEL HANDLES (parity-plan Phase 3) — the loader-facing layer over the
// bucket renderer. A loaded model is N geometry buckets (one per material /
// primitive) whose Mesh3d instances share ONE logical transform: Model3d
// proxies x/y/z/yaw/pitch/roll/w/h/d/alpha to every part, so game code
// treats a multi-material OBJ or a GLB exactly like a single world.box().
// (True hierarchies — attachment points, per-part animation — are Phase 3
// stage 4; this is the flat stage-1/2 contract.)
//
// Loaded vertices are AUTO-FIT to the engine's unit contract (the same rule
// as lathe/tube/shape geometry): uniformly scaled and centred so the model's
// largest extent spans exactly 1 — w/h/d then size it in world units like
// every primitive. fitVerts is pure and dist-tested.

import type { Mesh3d, Group3d } from './world3d.js';
import type { GlbRig } from './glb.js';
import { AnimMixer, jointPalette, decomposeTRS, mat4MulTo } from './anim3d.js';

export interface ModelConfig {
  x?: number; y?: number; z?: number;
  /** World size along each axis (default 1 across the largest extent —
   * models are unit-fit like every primitive). */
  w?: number; h?: number; d?: number;
  yaw?: number; pitch?: number; roll?: number;
  alpha?: number;
  /** Tint override for EVERY part (default: the model's own materials). */
  color?: string;
  /** PBR overrides applied to every part (default: material values for
   * GLB; matte dielectric for OBJ). */
  metallic?: number;
  rough?: number;
}

/** Uniformly scale + centre stride-8 vertex groups so the largest extent
 * spans 1 (positions only — normals are direction vectors). Mutates the
 * arrays; returns the applied transform. Pure — dist-tested. */
export function fitVerts(
  groups: Float32Array[],
  bounds: { min: [number, number, number]; max: [number, number, number] },
): { scale: number; center: [number, number, number] } {
  const ex = bounds.max[0] - bounds.min[0];
  const ey = bounds.max[1] - bounds.min[1];
  const ez = bounds.max[2] - bounds.min[2];
  const extent = Math.max(ex, ey, ez) || 1;
  const scale = 1 / extent;
  const center: [number, number, number] = [
    (bounds.min[0] + bounds.max[0]) / 2,
    (bounds.min[1] + bounds.max[1]) / 2,
    (bounds.min[2] + bounds.max[2]) / 2,
  ];
  for (const g of groups) {
    for (let i = 0; i < g.length; i += 8) {
      g[i] = (g[i] - center[0]) * scale;
      g[i + 1] = (g[i + 1] - center[1]) * scale;
      g[i + 2] = (g[i + 2] - center[2]) * scale;
    }
  }
  return { scale, center };
}

/** 0..1 rgb (+optional alpha) → the '#rrggbb' hex the engine speaks. */
export function rgbHex(r: number, g: number, b: number): string {
  const c = (v: number): string => Math.round(Math.min(1, Math.max(0, v)) * 255).toString(16).padStart(2, '0');
  return `#${c(r)}${c(g)}${c(b)}`;
}

/**
 * A loaded model: one live handle over every material part. Mutate
 * x/y/z/yaw/pitch/roll/w/h/d/alpha exactly like a Mesh3d — every part
 * follows. Per-part access stays open through `parts` (tint one material,
 * hide another).
 */
export class Model3d {
  constructor(readonly parts: Mesh3d[]) {}

  get x(): number { return this.parts[0]?.x ?? 0; }
  set x(v: number) { for (const p of this.parts) p.x = v; }
  get y(): number { return this.parts[0]?.y ?? 0; }
  set y(v: number) { for (const p of this.parts) p.y = v; }
  get z(): number { return this.parts[0]?.z ?? 0; }
  set z(v: number) { for (const p of this.parts) p.z = v; }
  get yaw(): number { return this.parts[0]?.yaw ?? 0; }
  set yaw(v: number) { for (const p of this.parts) p.yaw = v; }
  get pitch(): number { return this.parts[0]?.pitch ?? 0; }
  set pitch(v: number) { for (const p of this.parts) p.pitch = v; }
  get roll(): number { return this.parts[0]?.roll ?? 0; }
  set roll(v: number) { for (const p of this.parts) p.roll = v; }
  get w(): number { return this.parts[0]?.w ?? 1; }
  set w(v: number) { for (const p of this.parts) p.w = v; }
  get h(): number { return this.parts[0]?.h ?? 1; }
  set h(v: number) { for (const p of this.parts) p.h = v; }
  get d(): number { return this.parts[0]?.d ?? 1; }
  set d(v: number) { for (const p of this.parts) p.d = v; }
  get alpha(): number { return this.parts[0]?.alpha ?? 1; }
  set alpha(v: number) { for (const p of this.parts) p.alpha = v; }

  /** Uniform scale sugar: w = h = d = v. */
  set size(v: number) { for (const p of this.parts) { p.w = v; p.h = v; p.d = v; } }

  /** Opt this whole model in/out of picking (see Mesh3d.inputEnabled) — fans
   * out to every part, so world.pick() returns any part of an enabled model. */
  get inputEnabled(): boolean { return this.parts[0]?.inputEnabled ?? false; }
  set inputEnabled(v: boolean) { for (const p of this.parts) p.inputEnabled = v; }

  /** Parent every part to a Group3d/Mesh3d (the whole model rides the
   * node; x/y/z become local to it). */
  get parent(): unknown { return this.parts[0]?.parent ?? null; }
  set parent(v: unknown) { for (const p of this.parts) p.parent = v as never; }

  kill(): void {
    for (const p of this.parts) p.kill();
  }
}

// ---------------------------------------------------------------------------
// ANIMATED models (Phase 3 stage 3): a rig-driven Model3d. Every part rides
// a root Group3d (stage-4 parenting) so the model transform never fights the
// mixer's per-node poses. Skinning is CPU-SIDE v1 (the plan's sanctioned
// first step — palettes on the CPU; vertex-shader skinning is the recorded
// upgrade): each frame the mixer poses the rig, skinned primitives deform
// their vertices on the CPU and re-upload their (per-instance) vertex
// buffer, and node-animated rigid primitives decompose their node's world
// matrix onto their mesh handle. Correctness lives in the pure, dist-tested
// anim3d maths; this class is just plumbing.

/** @internal One skinned primitive's VS-skinning state: the fit-conjugated
 * joint palette, retained per instance — the vertex shader consumes it from
 * the world's palette storage buffer (world3d copies + uploads per frame). */
export interface SkinnedPart {
  mesh: Mesh3d;
  skin: number;
  /** This instance's palette (jointCount × 16 floats, FIT space). */
  palette: Float32Array;
}

/** @internal A rigid primitive driven by an animated node. */
export interface NodePart {
  mesh: Mesh3d;
  node: number;
}

export class AnimatedModel3d extends Model3d {
  /** Clip names (play() takes a name or index). */
  readonly anims: string[];
  readonly mixer: AnimMixer;
  /** The transform every part hangs off — drive the model through the
   * Model3d accessors as usual. */
  readonly root: Group3d;

  private skinned: SkinnedPart[];
  private nodeParts: NodePart[];

  private fitM: Float32Array;
  private fitInv: Float32Array;
  private scratchA = new Float32Array(16);
  private scratchB = new Float32Array(16);
  private rig: GlbRig;

  /**
   * @internal Built by the loader — reach a model as `await world.model(url)`,
   * never construct one. Internal so the shipped `.d.ts` carries no reference
   * to the stripped `SkinnedPart`/`NodePart` (a dangling type would break the
   * game project's typecheck).
   */
  constructor(
    parts: Mesh3d[], rig: GlbRig, root: Group3d,
    skinned: SkinnedPart[], nodeParts: NodePart[],
    fit: { scale: number; center: [number, number, number] },
  ) {
    super(parts);
    this.rig = rig;
    this.root = root;
    this.mixer = new AnimMixer(rig);
    this.anims = rig.anims.map((a) => a.name);
    this.skinned = skinned;
    this.nodeParts = nodeParts;

    // Rig matrices live in AUTHORED model space; the buckets hold unit-FIT
    // verts — conjugate every rig matrix by the fit: M' = F · M · F⁻¹.
    const s = fit.scale, c = fit.center;
    this.fitM = Float32Array.from([s, 0, 0, 0, 0, s, 0, 0, 0, 0, s, 0, -c[0] * s, -c[1] * s, -c[2] * s, 1]);
    this.fitInv = Float32Array.from([1 / s, 0, 0, 0, 0, 1 / s, 0, 0, 0, 0, 1 / s, 0, c[0], c[1], c[2], 1]);
    if (this.anims.length) this.mixer.play(0);
    this.update(0);
  }

  // The model transform drives the ROOT GROUP — part poses belong to the
  // mixer (the plain Model3d accessors would stomp them every set).
  override get x(): number { return this.root.x; }
  override set x(v: number) { this.root.x = v; }
  override get y(): number { return this.root.y; }
  override set y(v: number) { this.root.y = v; }
  override get z(): number { return this.root.z; }
  override set z(v: number) { this.root.z = v; }
  override get yaw(): number { return this.root.yaw; }
  override set yaw(v: number) { this.root.yaw = v; }
  override get pitch(): number { return this.root.pitch; }
  override set pitch(v: number) { this.root.pitch = v; }
  override get roll(): number { return this.root.roll; }
  override set roll(v: number) { this.root.roll = v; }
  /** Animated models scale UNIFORMLY through the root (per-axis w/h/d
   * belongs to the mixer's node scales). */
  override set size(v: number) { this.root.scale = v; }
  override get w(): number { return this.root.scale; }
  override set w(v: number) { this.root.scale = v; }
  override get h(): number { return this.root.scale; }
  override set h(v: number) { this.root.scale = v; }
  override get d(): number { return this.root.scale; }
  override set d(v: number) { this.root.scale = v; }
  override get parent(): unknown { return this.root.parent; }
  override set parent(v: unknown) { this.root.parent = v as never; }

  /** Play a clip by name or index; crossfades from the current one. */
  play(clip: string | number, opts?: { loop?: boolean; fade?: number }): void {
    this.mixer.play(clip, opts);
  }

  /** @internal Copy every skinned part's palette into the world's pool at
   * its mesh's allocated base (world3d calls this each prepare). */
  writePalettes(pool: Float32Array): void {
    for (const sp of this.skinned) {
      pool.set(sp.palette, sp.mesh.paletteBase * 16);
    }
  }

  /** Advance the rig (the world ticks this every frame). */
  update(dt: number): void {
    this.mixer.update(dt);
    const worlds = this.mixer.worlds;
    // Rigid node-driven parts: node world → fit space → mesh TRS (local to
    // the root group).
    for (const np of this.nodeParts) {
      mat4MulTo(this.fitM, worlds.subarray(np.node * 16, np.node * 16 + 16) as Float32Array, this.scratchA);
      mat4MulTo(this.scratchA, this.fitInv, this.scratchB);
      const d = decomposeTRS(this.scratchB);
      np.mesh.x = d.t[0]; np.mesh.y = d.t[1]; np.mesh.z = d.t[2];
      np.mesh.yaw = d.e[0]; np.mesh.pitch = d.e[1]; np.mesh.roll = d.e[2];
      np.mesh.w = d.s[0]; np.mesh.h = d.s[1]; np.mesh.d = d.s[2];
    }
    // Skinned parts: the fit-conjugated palette is RETAINED per part — the
    // VERTEX SHADER skins from it (world3d uploads all palettes each frame).
    for (const sp of this.skinned) {
      const skin = this.rig.skins[sp.skin];
      jointPalette(skin, worlds, sp.palette);
      const nj = skin.joints.length;
      for (let j = 0; j < nj; j++) {
        const off = j * 16;
        mat4MulTo(this.fitM, sp.palette.subarray(off, off + 16) as Float32Array, this.scratchA);
        mat4MulTo(this.scratchA, this.fitInv, this.scratchB);
        sp.palette.set(this.scratchB, off);
      }
    }
  }
}

/** CPU-skin a stride-8 soup: pos by the weighted palette matrices, normals
 * by their rotation parts (renormalised). Pure — dist-tested. */
export function cpuSkin(
  base: Float32Array, joints: Uint16Array, weights: Float32Array,
  palette: Float32Array, out: Float32Array,
): void {
  const n = base.length / 8;
  for (let v = 0; v < n; v++) {
    const o = v * 8;
    const jo = v * 4;
    const px = base[o], py = base[o + 1], pz = base[o + 2];
    const nx = base[o + 3], ny = base[o + 4], nz = base[o + 5];
    let sx = 0, sy = 0, sz = 0, snx = 0, sny = 0, snz = 0;
    for (let k = 0; k < 4; k++) {
      const w = weights[jo + k];
      if (w === 0) continue;
      const m = joints[jo + k] * 16;
      sx += w * (palette[m] * px + palette[m + 4] * py + palette[m + 8] * pz + palette[m + 12]);
      sy += w * (palette[m + 1] * px + palette[m + 5] * py + palette[m + 9] * pz + palette[m + 13]);
      sz += w * (palette[m + 2] * px + palette[m + 6] * py + palette[m + 10] * pz + palette[m + 14]);
      snx += w * (palette[m] * nx + palette[m + 4] * ny + palette[m + 8] * nz);
      sny += w * (palette[m + 1] * nx + palette[m + 5] * ny + palette[m + 9] * nz);
      snz += w * (palette[m + 2] * nx + palette[m + 6] * ny + palette[m + 10] * nz);
    }
    const nl = Math.hypot(snx, sny, snz) || 1;
    out[o] = sx; out[o + 1] = sy; out[o + 2] = sz;
    out[o + 3] = snx / nl; out[o + 4] = sny / nl; out[o + 5] = snz / nl;
    out[o + 6] = base[o + 6]; out[o + 7] = base[o + 7];
  }
}
