// VOXELS — a Minecraft-style block world as a lazy 3D-core satellite layer
// (like terrain/grass/water). `const vox = world.voxels({ ... })` builds a
// chunked block volume with a procedural block "texture pack", exposed-face
// meshing + baked ambient occlusion, and a DDA raycast for hitting/placing
// blocks. It reuses the world's shared frame uniforms (struct U at group 0) so
// its lighting, day/night and fog match the rest of the world for free.
//
// PERFORMANCE is the point. The world is split into CHUNKS (default 16³); each
// chunk is one vertex buffer of ONLY its exposed faces (interior faces cost
// nothing) and ONE draw call. Editing a block re-meshes just its chunk (+ any
// neighbour chunk it borders). 2D games never load a byte of this — it lives
// in the world3d-core chunk.
//
// DOCTRINE (matching terrain3d.ts):
//   - MECHANICS BEFORE ASSETS: zero image files. Every block texture is a pure
//     16×16 pixel generator (`Uint8Array` RGBA, no canvas) → uploaded into a
//     `texture_2d_array` (one tile per layer: mipmaps never bleed across tiles).
//   - CPU MODEL IS THE CONTRACT: `getBlock`/`raycast` read the SAME grid the
//     mesher rasterises, so a block you pick is exactly the block you see.
//   - Everything except the GPU class is PURE (no GPU, no DOM) and dist-tested.
//
// The GPU plumbing (`Voxels3d`) takes a `device` + the world's `format`,
// `sampleCount` and shared `uniforms` buffer; `world.voxels()` wires it up.

import { BITS, shaderModule } from './gpu.js';
import { fbm2, noisePerm, mulberry32 } from './noise.js';

// ── The block library ───────────────────────────────────────────────────────
// A "texture pack" of 16×16 tiles, generated procedurally. TILES is the atlas
// LAYER order (each tile = one array-texture layer); BLOCKS maps a block id to
// its per-face tiles + flags. Block id 0 is always AIR.

/** One face's tile picked by axis. */
export interface BlockDef {
  name: string;
  /** Tile layer index for the +Y face. */
  top: number;
  /** Tile layer index for the -Y face. */
  bottom: number;
  /** Tile layer index for the four side faces (±X, ±Z). */
  side: number;
  /** Fully hides faces behind it (default true). Leaves/glass/water = false. */
  opaque?: boolean;
  /** Blocks movement / is pickable by the raycast (default true). Water = false. */
  solid?: boolean;
  /** Alpha-tested in the shader (leaves, glass) — kept in the opaque pass. */
  cutout?: boolean;
}

// Tile layer names, in upload order. Index === array-texture layer.
export const TILES = [
  'grassTop', 'grassSide', 'dirt', 'stone', 'cobble', 'sand',
  'logTop', 'logSide', 'planks', 'leaves', 'water', 'snowTop',
  'snowSide', 'glass', 'brick', 'coalOre', 'goldOre', 'gravel', 'bedrock',
] as const;

const T = (name: (typeof TILES)[number]): number => TILES.indexOf(name);

/** The block table. `BLOCKS[id]` — id 0 (air) is intentionally a hole. */
export const BLOCKS: (BlockDef | null)[] = [
  null, // 0 = air
  { name: 'grass', top: T('grassTop'), bottom: T('dirt'), side: T('grassSide') },   // 1
  { name: 'dirt', top: T('dirt'), bottom: T('dirt'), side: T('dirt') },             // 2
  { name: 'stone', top: T('stone'), bottom: T('stone'), side: T('stone') },         // 3
  { name: 'cobble', top: T('cobble'), bottom: T('cobble'), side: T('cobble') },     // 4
  { name: 'sand', top: T('sand'), bottom: T('sand'), side: T('sand') },             // 5
  { name: 'log', top: T('logTop'), bottom: T('logTop'), side: T('logSide') },       // 6
  { name: 'planks', top: T('planks'), bottom: T('planks'), side: T('planks') },     // 7
  { name: 'leaves', top: T('leaves'), bottom: T('leaves'), side: T('leaves'), opaque: false, cutout: true }, // 8
  { name: 'water', top: T('water'), bottom: T('water'), side: T('water'), opaque: false, solid: false },     // 9
  { name: 'snow', top: T('snowTop'), bottom: T('dirt'), side: T('snowSide') },      // 10
  { name: 'glass', top: T('glass'), bottom: T('glass'), side: T('glass'), opaque: false, cutout: true },     // 11
  { name: 'brick', top: T('brick'), bottom: T('brick'), side: T('brick') },         // 12
  { name: 'coalOre', top: T('coalOre'), bottom: T('coalOre'), side: T('coalOre') }, // 13
  { name: 'goldOre', top: T('goldOre'), bottom: T('goldOre'), side: T('goldOre') }, // 14
  { name: 'gravel', top: T('gravel'), bottom: T('gravel'), side: T('gravel') },     // 15
  { name: 'bedrock', top: T('bedrock'), bottom: T('bedrock'), side: T('bedrock') }, // 16
];

/** Named ids so callers read `BLOCK.grass` not a magic number. */
export const BLOCK = {
  air: 0, grass: 1, dirt: 2, stone: 3, cobble: 4, sand: 5, log: 6, planks: 7,
  leaves: 8, water: 9, snow: 10, glass: 11, brick: 12, coalOre: 13, goldOre: 14,
  gravel: 15, bedrock: 16,
} as const;

const isOpaque = (id: number): boolean => id > 0 && (BLOCKS[id]?.opaque !== false);
const isSolid = (id: number): boolean => id > 0 && (BLOCKS[id]?.solid !== false);

// ── Procedural block textures (pure — no canvas) ────────────────────────────
// Each generator writes a `res*res*4` RGBA `Uint8Array`. Deterministic by a
// per-tile seed so every machine bakes the same pack. Kept deliberately chunky
// and characterful (the Minecraft look is low-res + high-contrast flecks).

/** Deterministic integer hash → [0, 1). */
function h2(x: number, y: number, seed: number): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 1274126177);
  h = Math.imul(h ^ (h >>> 13), 1103515245);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const clamp255 = (v: number): number => (v < 0 ? 0 : v > 255 ? 255 : v | 0);

/** Small painter over an RGBA byte buffer. */
class Tile {
  px: Uint8Array;
  constructor(readonly res: number) { this.px = new Uint8Array(res * res * 4); }
  set(x: number, y: number, r: number, g: number, b: number, a = 255): void {
    if (x < 0 || y < 0 || x >= this.res || y >= this.res) return;
    const i = (y * this.res + x) * 4;
    this.px[i] = clamp255(r); this.px[i + 1] = clamp255(g); this.px[i + 2] = clamp255(b); this.px[i + 3] = clamp255(a);
  }
  fill(r: number, g: number, b: number, a = 255): void {
    for (let y = 0; y < this.res; y++) for (let x = 0; x < this.res; x++) this.set(x, y, r, g, b, a);
  }
  /** Per-texel brightness jitter around a base colour (the flecked stone/dirt look). */
  grain(r: number, g: number, b: number, amp: number, seed: number): void {
    for (let y = 0; y < this.res; y++) for (let x = 0; x < this.res; x++) {
      const j = (h2(x, y, seed) - 0.5) * 2 * amp;
      this.set(x, y, r + j, g + j, b + j);
    }
  }
}

type TileGen = (res: number, seed: number) => Uint8Array;

const GENERATORS: Record<(typeof TILES)[number], TileGen> = {
  grassTop: (res, seed) => {
    const t = new Tile(res); t.grain(84, 140, 58, 22, seed);
    for (let i = 0; i < res * res * 0.18; i++) t.set((h2(i, 1, seed) * res) | 0, (h2(i, 2, seed) * res) | 0, 106, 168, 74);
    for (let i = 0; i < res * res * 0.08; i++) t.set((h2(i, 3, seed) * res) | 0, (h2(i, 4, seed) * res) | 0, 62, 108, 44);
    return t.px;
  },
  grassSide: (res, seed) => {
    const t = new Tile(res); t.grain(122, 92, 60, 16, seed);          // dirt body
    const lip = Math.max(2, (res * 0.28) | 0);
    for (let y = 0; y < lip; y++) for (let x = 0; x < res; x++) {
      const j = (h2(x, y, seed + 9) - 0.5) * 30;
      t.set(x, y, 84 + j, 140 + j, 58 + j);                            // green cap
    }
    for (let x = 0; x < res; x++) { const drip = lip + ((h2(x, 0, seed + 3) * 3) | 0); t.set(x, drip, 90, 148, 62); } // ragged edge
    return t.px;
  },
  dirt: (res, seed) => { const t = new Tile(res); t.grain(124, 90, 58, 20, seed);
    for (let i = 0; i < res * res * 0.06; i++) t.set((h2(i, 5, seed) * res) | 0, (h2(i, 6, seed) * res) | 0, 92, 66, 42); return t.px; },
  stone: (res, seed) => { const t = new Tile(res); t.grain(128, 128, 132, 14, seed);
    for (let i = 0; i < res * res * 0.05; i++) t.set((h2(i, 7, seed) * res) | 0, (h2(i, 8, seed) * res) | 0, 100, 100, 104); return t.px; },
  cobble: (res, seed) => {
    const t = new Tile(res); t.grain(120, 120, 124, 10, seed); const c = 4, cs = res / c;
    for (let cy = 0; cy < c; cy++) for (let cx = 0; cx < c; cx++) {
      const ox = (cx + (h2(cx, cy, seed) - 0.5) * 0.3) * cs, oy = (cy + (h2(cy, cx, seed + 1) - 0.5) * 0.3) * cs;
      const shade = 96 + h2(cx, cy, seed + 2) * 44;
      for (let y = 1; y < cs - 1; y++) for (let x = 1; x < cs - 1; x++) t.set((ox + x) | 0, (oy + y) | 0, shade, shade, shade + 4);
    }
    return t.px;
  },
  sand: (res, seed) => { const t = new Tile(res); t.grain(214, 198, 148, 10, seed);
    for (let i = 0; i < res * res * 0.05; i++) t.set((h2(i, 9, seed) * res) | 0, (h2(i, 10, seed) * res) | 0, 198, 178, 128); return t.px; },
  logTop: (res, seed) => {
    const t = new Tile(res); t.fill(150, 112, 66); const c = res / 2 - 0.5;
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) {
      const r = Math.hypot(x - c, y - c), ring = Math.sin(r * 2.1) * 0.5 + 0.5;
      const v = 120 + ring * 44 + (h2(x, y, seed) - 0.5) * 12;
      t.set(x, y, v, v * 0.76, v * 0.46);
    }
    return t.px;
  },
  logSide: (res, seed) => {
    const t = new Tile(res);
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) {
      const bark = Math.sin(x * 1.7 + h2(x, 0, seed) * 2) * 0.5 + 0.5;
      const v = 96 + bark * 40 + (h2(x, y, seed + 1) - 0.5) * 16;
      t.set(x, y, v, v * 0.72, v * 0.42);
    }
    return t.px;
  },
  planks: (res, seed) => {
    const t = new Tile(res); t.grain(168, 130, 78, 12, seed); const rows = 4, rh = res / rows;
    for (let r = 0; r <= rows; r++) for (let x = 0; x < res; x++) t.set(x, Math.min(res - 1, (r * rh) | 0), 96, 70, 40); // seams
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) if (h2(x, y, seed + 2) > 0.86) t.set(x, y, 140, 104, 60); // grain
    return t.px;
  },
  leaves: (res, seed) => {
    const t = new Tile(res);
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) {
      const n = h2(x, y, seed);
      if (n > 0.82) { t.set(x, y, 0, 0, 0, 0); continue; }             // cutout holes
      const v = n * 60; t.set(x, y, 46 + v, 96 + v, 40 + v);
    }
    return t.px;
  },
  water: (res, seed) => {
    // LOW-CONTRAST, non-directional mottle. A high-contrast or directional
    // pattern here aliases into scanline moiré on the flat sea at grazing
    // angles — keep the amplitude tiny so mips resolve it to near-flat blue.
    const t = new Tile(res);
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) {
      const n = (h2(x, y, seed) + h2(x, y, seed + 41)) * 0.5 - 0.5;
      t.set(x, y, 48 + n * 8, 104 + n * 8, 176 + n * 10, 235);
    }
    return t.px;
  },
  snowTop: (res, seed) => { const t = new Tile(res); t.grain(238, 244, 252, 8, seed);
    for (let i = 0; i < res * res * 0.04; i++) t.set((h2(i, 11, seed) * res) | 0, (h2(i, 12, seed) * res) | 0, 214, 226, 244); return t.px; },
  snowSide: (res, seed) => {
    const t = new Tile(res); t.grain(122, 92, 60, 16, seed); const lip = Math.max(3, (res * 0.36) | 0);
    for (let y = 0; y < lip; y++) for (let x = 0; x < res; x++) { const j = (h2(x, y, seed + 7) - 0.5) * 16; t.set(x, y, 236 + j, 242 + j, 250 + j); }
    return t.px;
  },
  glass: (res, seed) => {
    const t = new Tile(res); t.fill(180, 210, 226, 26);
    for (let x = 0; x < res; x++) { t.set(x, 0, 206, 228, 240, 210); t.set(x, res - 1, 206, 228, 240, 210); t.set(0, x, 206, 228, 240, 210); t.set(res - 1, x, 206, 228, 240, 210); }
    for (let i = 0; i < res * 0.5; i++) t.set((h2(i, 13, seed) * res) | 0, (h2(i, 14, seed) * res) | 0, 240, 250, 255, 150); // glints
    return t.px;
  },
  brick: (res, seed) => {
    const t = new Tile(res); t.grain(162, 74, 58, 10, seed); const rows = 4, rh = res / rows;
    for (let ry = 0; ry < rows; ry++) {
      const off = (ry % 2) * (res / 2);
      for (let x = 0; x < res; x++) t.set(x, (ry * rh) | 0, 196, 190, 178);                      // mortar row
      for (let y = (ry * rh) | 0; y < (ry + 1) * rh; y++) {                                       // mortar cols (offset rows)
        t.set(off % res, y, 196, 190, 178);
        t.set((off + res / 2) % res, y, 196, 190, 178);
      }
    }
    return t.px;
  },
  coalOre: (res, seed) => {
    const t = new Tile(res); t.grain(128, 128, 132, 14, seed);
    for (let i = 0; i < 5; i++) { const bx = (h2(i, 20, seed) * res) | 0, by = (h2(i, 21, seed) * res) | 0;
      for (let y = -1; y <= 1; y++) for (let x = -1; x <= 1; x++) if (Math.abs(x) + Math.abs(y) < 2) t.set(bx + x, by + y, 30, 30, 34); }
    return t.px;
  },
  goldOre: (res, seed) => {
    const t = new Tile(res); t.grain(128, 128, 132, 14, seed);
    for (let i = 0; i < 5; i++) { const bx = (h2(i, 22, seed) * res) | 0, by = (h2(i, 23, seed) * res) | 0;
      for (let y = -1; y <= 1; y++) for (let x = -1; x <= 1; x++) if (Math.abs(x) + Math.abs(y) < 2) t.set(bx + x, by + y, 234, 190, 74); }
    return t.px;
  },
  gravel: (res, seed) => {
    const t = new Tile(res);
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) { const n = h2(x, y, seed); const v = 96 + n * 64; t.set(x, y, v, v * 0.94, v * 0.86); }
    return t.px;
  },
  bedrock: (res, seed) => {
    const t = new Tile(res);
    for (let y = 0; y < res; y++) for (let x = 0; x < res; x++) { const n = h2(x, y, seed); const v = n > 0.5 ? 40 + n * 40 : 24 + n * 20; t.set(x, y, v, v, v + 2); }
    return t.px;
  },
};

/** Bake the whole pack: `count` layers of `res*res` RGBA, contiguous. Pure. */
export function bakeTiles(res = 16, seed = 1): { data: Uint8Array; layers: number; res: number } {
  const layers = TILES.length;
  const out = new Uint8Array(res * res * 4 * layers);
  for (let l = 0; l < layers; l++) out.set(GENERATORS[TILES[l]](res, seed + l * 131), l * res * res * 4);
  return { data: out, layers, res };
}

/** Box-filter downsample one RGBA layer by 2× (for mip generation). Pure. */
export function halveRGBA(px: Uint8Array, w: number, h: number): { px: Uint8Array; w: number; h: number } {
  const nw = Math.max(1, w >> 1), nh = Math.max(1, h >> 1), out = new Uint8Array(nw * nh * 4);
  for (let y = 0; y < nh; y++) for (let x = 0; x < nw; x++) {
    for (let c = 0; c < 4; c++) {
      const x0 = x * 2, y0 = y * 2, x1 = Math.min(w - 1, x0 + 1), y1 = Math.min(h - 1, y0 + 1);
      out[(y * nw + x) * 4 + c] = (px[(y0 * w + x0) * 4 + c] + px[(y0 * w + x1) * 4 + c] + px[(y1 * w + x0) * 4 + c] + px[(y1 * w + x1) * 4 + c]) >> 2;
    }
  }
  return { px: out, w: nw, h: nh };
}

// ── The block volume (pure CPU model — the contract) ────────────────────────

export interface VoxelWorldOptions {
  /** World size in blocks (X wide, Y tall, Z deep). Default 128×48×128. */
  sizeX?: number; sizeY?: number; sizeZ?: number;
  /** Chunk edge in blocks (default 16). Bigger = fewer draws, costlier edits. */
  chunk?: number;
}

/** A bounded grid of block ids, split into fixed-size chunks. Pure/testable. */
export class VoxelWorld {
  readonly sx: number; readonly sy: number; readonly sz: number;
  readonly ch: number;
  readonly cx: number; readonly cy: number; readonly cz: number;   // chunk counts
  private chunks: (Uint16Array | null)[];
  /** Chunk indices needing a remesh. */
  readonly dirty = new Set<number>();

  constructor(opts: VoxelWorldOptions = {}) {
    this.sx = opts.sizeX ?? 128; this.sy = opts.sizeY ?? 48; this.sz = opts.sizeZ ?? 128;
    this.ch = opts.chunk ?? 16;
    this.cx = Math.ceil(this.sx / this.ch); this.cy = Math.ceil(this.sy / this.ch); this.cz = Math.ceil(this.sz / this.ch);
    this.chunks = new Array(this.cx * this.cy * this.cz).fill(null);
  }

  inBounds(x: number, y: number, z: number): boolean {
    return x >= 0 && y >= 0 && z >= 0 && x < this.sx && y < this.sy && z < this.sz;
  }

  private chunkIndex(cx: number, cy: number, cz: number): number {
    return (cy * this.cz + cz) * this.cx + cx;
  }

  /** Block id at a cell, or 0 (air) outside the world. */
  get(x: number, y: number, z: number): number {
    if (!this.inBounds(x, y, z)) return 0;
    const ch = this.ch;
    const c = this.chunks[this.chunkIndex((x / ch) | 0, (y / ch) | 0, (z / ch) | 0)];
    if (!c) return 0;
    const lx = x % ch, ly = y % ch, lz = z % ch;
    return c[(ly * ch + lz) * ch + lx];
  }

  /** Set a cell. Marks the owning chunk (and a bordering neighbour) dirty. */
  set(x: number, y: number, z: number, id: number): void {
    if (!this.inBounds(x, y, z)) return;
    const ch = this.ch, cxi = (x / ch) | 0, cyi = (y / ch) | 0, czi = (z / ch) | 0;
    const idx = this.chunkIndex(cxi, cyi, czi);
    let c = this.chunks[idx];
    if (!c) { if (id === 0) return; c = this.chunks[idx] = new Uint16Array(ch * ch * ch); }
    const lx = x % ch, ly = y % ch, lz = z % ch;
    if (c[(ly * ch + lz) * ch + lx] === id) return;
    c[(ly * ch + lz) * ch + lx] = id;
    this.dirty.add(idx);
    // A face on a chunk boundary belongs to (and un-hides a face in) the
    // neighbour too, so remesh it as well.
    if (lx === 0 && cxi > 0) this.dirty.add(this.chunkIndex(cxi - 1, cyi, czi));
    if (lx === ch - 1 && cxi < this.cx - 1) this.dirty.add(this.chunkIndex(cxi + 1, cyi, czi));
    if (ly === 0 && cyi > 0) this.dirty.add(this.chunkIndex(cxi, cyi - 1, czi));
    if (ly === ch - 1 && cyi < this.cy - 1) this.dirty.add(this.chunkIndex(cxi, cyi + 1, czi));
    if (lz === 0 && czi > 0) this.dirty.add(this.chunkIndex(cxi, cyi, czi - 1));
    if (lz === ch - 1 && czi < this.cz - 1) this.dirty.add(this.chunkIndex(cxi, cyi, czi + 1));
  }

  /** Highest solid block at column (x, z), or -1 if the column is empty. */
  columnTop(x: number, z: number): number {
    for (let y = this.sy - 1; y >= 0; y--) if (this.get(x, y, z) !== 0) return y;
    return -1;
  }

  /** Mark every non-empty chunk dirty (after a bulk generate, or device loss). */
  markAllDirty(): void { for (let i = 0; i < this.chunks.length; i++) if (this.chunks[i]) this.dirty.add(i); }

  /** Empty the world back to all-air. Marks every previously-filled chunk dirty
   * so its geometry clears on the next remesh (used by reseed). */
  clear(): void {
    for (let i = 0; i < this.chunks.length; i++) if (this.chunks[i]) { this.dirty.add(i); this.chunks[i] = null; }
  }

  /** Chunk grid coords from a linear chunk index (for the mesher). */
  chunkCoords(idx: number): [number, number, number] {
    const cx = idx % this.cx, r = (idx / this.cx) | 0;
    return [cx, (r / this.cz) | 0, r % this.cz];
  }
  get chunkCount(): number { return this.chunks.length; }
  hasChunk(idx: number): boolean { return !!this.chunks[idx]; }
}

// ── Exposed-face mesher + baked AO ──────────────────────────────────────────
// One float32 vertex = pos(3) + uv(2) + layer(1) + face(1) + ao(1) = 8 floats.

export const VOX_FLOATS = 8;

/** Ambient-occlusion brightness by occluder count (0 = darkest corner).
 * Deliberately gentle — the block look wants a hint of crease, not deep
 * shadow (Minecraft absorbs very little light per face). */
export const AO_LEVELS = [0.62, 0.75, 0.88, 1.0];

// 6 faces. For each: normal, and the two unit tangent axes (u, v) chosen so
// u×v === normal — so winding corner order (0,0)(1,0)(1,1)(0,1) is front-facing
// (CCW) for back-face culling. `off` is the face's base corner within the cell.
// `uv` gives the texture coord for each of the 4 corners IN QUAD ORDER
// [c00, c10, c11, c01] — oriented so the texture's TOP (v=0) sits at the block's
// TOP on side faces (grass cap up, tree bark vertical), not rotated sideways.
interface Face { n: [number, number, number]; u: [number, number, number]; v: [number, number, number]; off: [number, number, number]; uv: [number, number][]; }
export const FACES: Face[] = [
  { n: [1, 0, 0], u: [0, 1, 0], v: [0, 0, 1], off: [1, 0, 0], uv: [[0, 1], [0, 0], [1, 0], [1, 1]] },   // +X
  { n: [-1, 0, 0], u: [0, 0, 1], v: [0, 1, 0], off: [0, 0, 0], uv: [[0, 1], [1, 1], [1, 0], [0, 0]] },  // -X
  { n: [0, 1, 0], u: [0, 0, 1], v: [1, 0, 0], off: [0, 1, 0], uv: [[0, 0], [1, 0], [1, 1], [0, 1]] },   // +Y (top)
  { n: [0, -1, 0], u: [1, 0, 0], v: [0, 0, 1], off: [0, 0, 0], uv: [[0, 0], [1, 0], [1, 1], [0, 1]] },  // -Y (bottom)
  { n: [0, 0, 1], u: [1, 0, 0], v: [0, 1, 0], off: [0, 0, 1], uv: [[0, 1], [1, 1], [1, 0], [0, 0]] },   // +Z
  { n: [0, 0, -1], u: [0, 1, 0], v: [1, 0, 0], off: [0, 0, 0], uv: [[0, 1], [0, 0], [1, 0], [1, 1]] },  // -Z
];

/** Standard 3-sample corner AO: 0 (both sides closed) … 3 (all open). */
export function vertexAO(side1: boolean, side2: boolean, corner: boolean): number {
  if (side1 && side2) return 0;
  return 3 - ((side1 ? 1 : 0) + (side2 ? 1 : 0) + (corner ? 1 : 0));
}

/** Pick the per-face tile layer for a block + face index (0..5, order = FACES). */
export function faceTile(def: BlockDef, face: number): number {
  return face === 2 ? def.top : face === 3 ? def.bottom : def.side;
}

/**
 * Mesh one chunk into an interleaved Float32Array (VOX_FLOATS per vertex).
 * Only faces exposed to air / a non-opaque different block are emitted.
 * `get` is the WORLD accessor (crosses chunk borders for correct culling+AO).
 */
export function meshChunk(get: (x: number, y: number, z: number) => number, x0: number, y0: number, z0: number, ch: number): Float32Array {
  const out: number[] = [];
  for (let ly = 0; ly < ch; ly++) for (let lz = 0; lz < ch; lz++) for (let lx = 0; lx < ch; lx++) {
    const wx = x0 + lx, wy = y0 + ly, wz = z0 + lz;
    const id = get(wx, wy, wz);
    if (id === 0) continue;
    const def = BLOCKS[id]!;
    for (let f = 0; f < 6; f++) {
      const F = FACES[f], n = F.n;
      const nb = get(wx + n[0], wy + n[1], wz + n[2]);
      // Draw the face unless the neighbour hides it: opaque, OR the same
      // (non-opaque) block (so water/glass don't draw internal seams).
      if (isOpaque(nb) || (nb === id && !def.opaque)) continue;
      const layer = faceTile(def, f);
      // The empty cell this face looks into — AO occluders sit around it.
      const px = wx + n[0], py = wy + n[1], pz = wz + n[2];
      const u = F.u, v = F.v;
      // 4 corners (i, j) ∈ {0,1}²; each samples 2 sides + 1 diagonal occluder.
      const corner = (i: number, j: number): { pos: [number, number, number]; ao: number } => {
        const pos: [number, number, number] = [
          wx + F.off[0] + i * u[0] + j * v[0],
          wy + F.off[1] + i * u[1] + j * v[1],
          wz + F.off[2] + i * u[2] + j * v[2],
        ];
        const du = i === 1 ? 1 : -1, dv = j === 1 ? 1 : -1;
        const s1 = isOpaque(get(px + du * u[0], py + du * u[1], pz + du * u[2]));
        const s2 = isOpaque(get(px + dv * v[0], py + dv * v[1], pz + dv * v[2]));
        const cc = isOpaque(get(px + du * u[0] + dv * v[0], py + du * u[1] + dv * v[1], pz + du * u[2] + dv * v[2]));
        return { pos, ao: vertexAO(s1, s2, cc) };
      };
      const c00 = corner(0, 0), c10 = corner(1, 0), c11 = corner(1, 1), c01 = corner(0, 1);
      const uv = F.uv;                         // per-face, oriented (texture-top = block-top on sides)
      const quad = [c00, c10, c11, c01];
      // Flip the split so the shared edge runs between the two BRIGHT corners
      // (kills the classic AO "anisotropy" seam on flat ground).
      const order = (c00.ao + c11.ao > c10.ao + c01.ao)
        ? [1, 2, 3, 1, 3, 0]
        : [0, 1, 2, 0, 2, 3];
      for (const k of order) {
        const c = quad[k];
        out.push(c.pos[0], c.pos[1], c.pos[2], uv[k][0], uv[k][1], layer, f, AO_LEVELS[c.ao]);
      }
    }
  }
  return new Float32Array(out);
}

// ── DDA raycast (Amanatides & Woo) ──────────────────────────────────────────

export interface VoxelHit {
  /** The solid cell hit. */
  x: number; y: number; z: number;
  /** Face normal of entry (points back toward the ray origin). */
  nx: number; ny: number; nz: number;
  /** Ray distance to the hit. */
  dist: number;
}

/**
 * March a ray through the grid; return the first SOLID block hit (or null).
 * `place` = hit cell + face normal is the empty cell to build into.
 */
export function raycastVoxel(
  get: (x: number, y: number, z: number) => number,
  ox: number, oy: number, oz: number,
  dx: number, dy: number, dz: number,
  maxDist = 64,
): VoxelHit | null {
  const len = Math.hypot(dx, dy, dz) || 1; dx /= len; dy /= len; dz /= len;
  let x = Math.floor(ox), y = Math.floor(oy), z = Math.floor(oz);
  const stepX = Math.sign(dx), stepY = Math.sign(dy), stepZ = Math.sign(dz);
  const tDX = dx !== 0 ? Math.abs(1 / dx) : Infinity;
  const tDY = dy !== 0 ? Math.abs(1 / dy) : Infinity;
  const tDZ = dz !== 0 ? Math.abs(1 / dz) : Infinity;
  const boundary = (i: number, step: number): number => step > 0 ? Math.floor(i) + 1 - i : i - Math.floor(i);
  let tMX = dx !== 0 ? boundary(ox, stepX) * tDX : Infinity;
  let tMY = dy !== 0 ? boundary(oy, stepY) * tDY : Infinity;
  let tMZ = dz !== 0 ? boundary(oz, stepZ) * tDZ : Infinity;
  let nx = 0, ny = 0, nz = 0, t = 0;
  if (isSolid(get(x, y, z))) return { x, y, z, nx: 0, ny: 0, nz: 0, dist: 0 };
  while (t <= maxDist) {
    if (tMX < tMY && tMX < tMZ) { x += stepX; t = tMX; tMX += tDX; nx = -stepX; ny = 0; nz = 0; }
    else if (tMY < tMZ) { y += stepY; t = tMY; tMY += tDY; nx = 0; ny = -stepY; nz = 0; }
    else { z += stepZ; t = tMZ; tMZ += tDZ; nx = 0; ny = 0; nz = -stepZ; }
    if (isSolid(get(x, y, z))) return { x, y, z, nx, ny, nz, dist: t };
  }
  return null;
}

// ── Terrain generation (pure — the reusable "landscapes") ───────────────────

export type VoxelTerrainType = 'island' | 'flat' | 'plains' | 'hills' | 'mountains';

export interface VoxelTerrainOptions {
  /** Landform (default 'island'). All types fill SOLID down to bedrock, so you
   * can dig right through them. 'island' + 'plains' add a sea; the rest are dry. */
  type?: VoxelTerrainType;
  seed?: number;
  /** Water fill height. Defaults per type ('island'/'plains' have one; -1 = dry). */
  seaLevel?: number;
  /** Scatter trees on grass (default true). */
  trees?: boolean;
  /** Tree density multiplier (default 1). */
  treeDensity?: number;
}

const smooth01 = (e0: number, e1: number, x: number): number => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

/**
 * Fill a VoxelWorld with a landscape. Pure + deterministic by seed — the same
 * (type, seed) is the same world on every machine. Every type is SOLID from the
 * surface down to bedrock (dig-through), coloured grass/sand/snow by height,
 * with an ore-flecked stone core. Reseed by calling `clear()` then this again.
 */
export function voxelTerrain(world: VoxelWorld, opts: VoxelTerrainOptions = {}): void {
  const type = opts.type ?? 'island';
  const seed = opts.seed ?? 1;
  const perm = noisePerm(seed);
  const sx = world.sx, sy = world.sy, sz = world.sz;
  const sea = opts.seaLevel ?? (type === 'island' ? Math.floor(sy * 0.36) : type === 'plains' ? Math.floor(sy * 0.30) : -1);
  const base = Math.floor(sy * (type === 'flat' ? 0.5 : type === 'mountains' ? 0.28 : 0.4));
  const cx = sx / 2, cz = sz / 2, maxR = Math.min(sx, sz) * 0.5;

  const heightAt = (x: number, z: number): number => {
    if (type === 'flat') return base;
    let h: number;
    if (type === 'mountains') {
      let sum = 0, amp = 1, norm = 0, fx = x * 0.02, fz = z * 0.02;
      for (let o = 0; o < 5; o++) { sum += (1 - Math.abs(fbm2(fx, fz, perm, { octaves: 1 }))) * amp; norm += amp; amp *= 0.5; fx *= 2.1; fz *= 2.1; }
      h = base + (sum / norm) * (sy * 0.55);
    } else if (type === 'hills') {
      h = base + fbm2(x * 0.03, z * 0.03, perm, { octaves: 5 }) * (sy * 0.30);
    } else {
      const amp = type === 'plains' ? sy * 0.12 : sy * 0.30;
      h = base + fbm2(x * 0.02, z * 0.02, perm, { octaves: 5 }) * amp;
      if (type === 'island') {
        const r = Math.hypot(x - cx, z - cz) / maxR;
        const fall = 1 - smooth01(0.55, 0.98, r);       // sink under the sea at the rim
        h = (sea - 4) + (h - (sea - 4)) * fall;
      }
    }
    return Math.max(1, Math.min(sy - 1, Math.floor(h)));
  };

  for (let z = 0; z < sz; z++) for (let x = 0; x < sx; x++) {
    const h = heightAt(x, z);
    const top = Math.max(h, sea);
    for (let y = 0; y <= top; y++) {
      let id = 0;
      if (y > h) { id = (sea >= 0 && y <= sea) ? BLOCK.water : 0; }
      else if (y === 0) id = BLOCK.bedrock;
      else if (y === h) {
        if (sea >= 0 && h <= sea + 1) id = BLOCK.sand;
        else if (h > sy * 0.62) id = BLOCK.snow;
        else id = BLOCK.grass;
      } else if (y > h - 4) id = (sea >= 0 && h <= sea + 1) ? BLOCK.sand : BLOCK.dirt;
      else {
        const n = mulberry32((x * 92821 + y * 689 + z * 7 + seed * 13) >>> 0)();
        id = n > 0.985 ? BLOCK.goldOre : n > 0.95 ? BLOCK.coalOre : BLOCK.stone;
      }
      if (id) world.set(x, y, z, id);
    }
  }
  if (opts.trees ?? true) scatterTrees(world, seed, opts.treeDensity ?? 1);
}

function scatterTrees(world: VoxelWorld, seed: number, density: number): void {
  const rnd = mulberry32((seed * 7 + 101) >>> 0);
  const sx = world.sx, sz = world.sz;
  const count = Math.floor(sx * sz * 0.006 * density);
  for (let i = 0; i < count; i++) {
    const x = 2 + ((rnd() * (sx - 4)) | 0), z = 2 + ((rnd() * (sz - 4)) | 0);
    const top = world.columnTop(x, z);
    if (top < 0 || world.get(x, top, z) !== BLOCK.grass) continue;
    const trunk = 4 + ((rnd() * 3) | 0);
    for (let t = 1; t <= trunk; t++) world.set(x, top + t, z, BLOCK.log);
    const cy = top + trunk;
    for (let dy = -1; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) {
      const r = Math.abs(dx) + Math.abs(dy) + Math.abs(dz);
      if (r > 3 || (dx === 0 && dz === 0 && dy < 2)) continue;
      if (rnd() < 0.82 && world.get(x + dx, cy + dy, z + dz) === 0) world.set(x + dx, cy + dy, z + dz, BLOCK.leaves);
    }
  }
}

// ── Character controller: AABB physics vs the voxel grid ────────────────────
// The same body drives the PLAYER (input) and MOBS (AI). Positions are in BLOCK
// units (multiply by blockSize for rendering, like the raycast). Pure + tested.

export interface VoxelBodyOptions {
  /** Footprint width in blocks (default 0.6). */
  width?: number;
  /** Height in blocks (default 1.8). */
  height?: number;
  /** Auto-climb ledges up to this tall without jumping (default 1.05 — walks
   * single-block terraces smoothly; set ~0.6 for jump-required full blocks). */
  stepHeight?: number;
  /** Downward acceleration, blocks/s² (default 28). */
  gravity?: number;
  /** Jump launch speed, blocks/s (default 8.4 ≈ clears ~1.25 blocks). */
  jumpSpeed?: number;
  /** Terminal fall speed, blocks/s (default 40). */
  maxFall?: number;
}

const EPS = 1e-4;

/**
 * An axis-aligned body that walks the voxel world: gravity, jumping, per-axis
 * swept collision resolve against solid blocks, and auto step-up over 1-block
 * ledges. Feed it a wished horizontal velocity + a jump flag each `step`; it
 * resolves the move and reports `onGround` / `blocked`.
 */
export class VoxelBody {
  x: number; y: number; z: number;               // feet centre (x,z centred; y = bottom)
  vy = 0;
  onGround = false;
  /** True when a wall stopped horizontal motion last step (AI: turn/jump). */
  blocked = false;
  readonly hw: number; readonly height: number;
  private stepH: number; private grav: number; private jump: number; private maxFall: number;

  constructor(private world: VoxelWorld, spawn: { x: number; y: number; z: number }, opts: VoxelBodyOptions = {}) {
    this.x = spawn.x; this.y = spawn.y; this.z = spawn.z;
    this.hw = (opts.width ?? 0.6) / 2;
    this.height = opts.height ?? 1.8;
    this.stepH = opts.stepHeight ?? 1.05;
    this.grav = opts.gravity ?? 28;
    this.jump = opts.jumpSpeed ?? 8.4;
    this.maxFall = opts.maxFall ?? 40;
  }

  /** Any solid block overlapping the AABB at the current position? */
  private collides(): boolean {
    const x0 = Math.floor(this.x - this.hw), x1 = Math.floor(this.x + this.hw - EPS);
    const y0 = Math.floor(this.y + EPS), y1 = Math.floor(this.y + this.height - EPS);
    const z0 = Math.floor(this.z - this.hw), z1 = Math.floor(this.z + this.hw - EPS);
    for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) for (let x = x0; x <= x1; x++) {
      if (isSolid(this.world.get(x, y, z))) return true;
    }
    return false;
  }

  /**
   * Advance one tick. `wishX`/`wishZ` are desired horizontal velocity
   * (blocks/s); `jump` launches if standing. Substepped so fast motion can't
   * tunnel through a 1-block wall.
   */
  step(dt: number, wishX: number, wishZ: number, jump: boolean): void {
    this.vy = Math.max(-this.maxFall, this.vy - this.grav * dt);
    if (jump && this.onGround) { this.vy = this.jump; this.onGround = false; }
    this.blocked = false;
    let dx = wishX * dt, dz = wishZ * dt, dy = this.vy * dt;
    const n = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)) / 0.4));
    dx /= n; dy /= n; dz /= n;
    const groundedBefore = this.onGround;
    this.onGround = false;
    for (let s = 0; s < n; s++) {
      this.moveY(dy);
      this.moveHoriz('x', dx, groundedBefore || this.onGround);
      this.moveHoriz('z', dz, groundedBefore || this.onGround);
    }
  }

  private moveY(dy: number): void {
    if (dy === 0) return;
    this.y += dy;
    if (!this.collides()) return;
    if (dy > 0) { this.y = Math.floor(this.y + this.height) - this.height - EPS; }   // head → ceiling
    else { this.y = Math.floor(this.y) + 1 + EPS; this.onGround = true; }            // feet → floor
    this.vy = 0;
  }

  private moveHoriz(axis: 'x' | 'z', d: number, grounded: boolean): void {
    if (d === 0) return;
    this[axis] += d;
    if (!this.collides()) return;
    // Try to auto step-up a low ledge (only while grounded).
    if (grounded && this.stepH > 0) {
      const savedY = this.y;
      this.y += this.stepH;
      if (!this.collides()) return;              // stepped over — keep the raise; gravity settles it
      this.y = savedY;
    }
    // Blocked: clamp flush against the block face.
    if (d > 0) this[axis] = Math.floor(this[axis] + this.hw) - this.hw - EPS;
    else this[axis] = Math.floor(this[axis] - this.hw) + 1 + this.hw + EPS;
    this.blocked = true;
  }
}

// ── AI: steering that drives a VoxelBody (animals, creepers) ─────────────────

export type VoxelAgentMode = 'wander' | 'seek' | 'flee' | 'idle';

export interface VoxelAgentOptions extends VoxelBodyOptions {
  mode?: VoxelAgentMode;
  /** Move speed, blocks/s (default 3). */
  speed?: number;
  /** Seed for wander randomness (default derived from spawn). */
  seed?: number;
}

/**
 * A mob: a VoxelBody plus a tiny brain. `wander` roams and randomly re-heads;
 * `seek`/`flee` chase or avoid a target; all of them AUTO-JUMP when a wall
 * blocks them (so they climb terraces like a Minecraft mob). Drive it with
 * `update(dt, target?)`.
 */
export class VoxelAgent {
  readonly body: VoxelBody;
  mode: VoxelAgentMode;
  speed: number;
  /** Current heading in radians (wander) — also where a mesh should face. */
  heading: number;
  private rnd: () => number;
  private reHead = 0;

  constructor(world: VoxelWorld, spawn: { x: number; y: number; z: number }, opts: VoxelAgentOptions = {}) {
    this.body = new VoxelBody(world, spawn, opts);
    this.mode = opts.mode ?? 'wander';
    this.speed = opts.speed ?? 3;
    this.rnd = mulberry32((opts.seed ?? Math.floor((spawn.x * 131 + spawn.z * 977 + 7))) >>> 0);
    this.heading = this.rnd() * Math.PI * 2;
  }

  /** One AI tick. `target` is required for seek/flee (a point to chase/avoid). */
  update(dt: number, target?: { x: number; z: number }): void {
    let wx = 0, wz = 0;
    // Right-hand-turn yaw: heading is a valid engine yaw (mobs render body.yaw = heading).
    if (this.mode === 'seek' && target) this.heading = Math.atan2(this.body.x - target.x, target.z - this.body.z);
    else if (this.mode === 'flee' && target) this.heading = Math.atan2(target.x - this.body.x, this.body.z - target.z);
    else if (this.mode === 'wander') {
      this.reHead -= dt;
      if (this.reHead <= 0) { this.heading += (this.rnd() - 0.5) * 2.2; this.reHead = 1.4 + this.rnd() * 2.4; }
    }
    if (this.mode !== 'idle') { wx = -Math.sin(this.heading) * this.speed; wz = Math.cos(this.heading) * this.speed; }   // forward (right-hand-turn yaw)
    // Auto-jump when a wall stopped us last tick (climb terraces / hop fences).
    const jump = this.body.blocked && this.body.onGround;
    if (this.mode === 'wander' && this.body.blocked) this.heading += (this.rnd() - 0.5) * 1.5;   // and turn a bit
    this.body.step(dt, wx, wz, jump);
  }
}

// ── The GPU layer ───────────────────────────────────────────────────────────

const DEPTH_FORMAT: GPUTextureFormat = 'depth24plus';

// Shared frame uniform (struct U) — declared verbatim to match world3d's group0
// buffer layout so lighting/day-night/fog come free. We use a subset.
const VOXEL_WGSL = /* wgsl */ `
struct U {
  viewProj: mat4x4f, camPos: vec4f, fogColor: vec4f, params: vec4f,
  lightDir: vec4f, right: vec4f, up: vec4f, ambSky: vec4f, ambGround: vec4f,
  sunCol: vec4f, uwC: vec4f, uwC2: vec4f,
}
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var atlas: texture_2d_array<f32>;
@group(0) @binding(2) var samp: sampler;

// Fixed per-face brightness — the Minecraft trick. Every face reads at a
// consistent, readable level set by its AXIS (top brightest, bottom darkest,
// sides between), NOT by dot(normal, sun) which plunges shadowed sides to
// black. The world's sun colour + day/night still tint everything.
//                         +X    -X    +Y    -Y    +Z    -Z
const FACE = array<f32, 6>(0.82, 0.82, 1.0, 0.58, 0.92, 0.92);

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) world: vec3f,
  @location(1) uv: vec2f,
  @location(2) @interpolate(flat) layer: u32,
  @location(3) @interpolate(flat) face: u32,
  @location(4) ao: f32,
}

@vertex
fn vs(@location(0) p: vec3f, @location(1) uv: vec2f,
      @location(2) layer: f32, @location(3) face: f32, @location(4) ao: f32) -> VSOut {
  var o: VSOut;
  o.pos = u.viewProj * vec4f(p, 1.0);
  o.world = p; o.uv = uv; o.layer = u32(layer + 0.5); o.face = u32(face + 0.5); o.ao = ao;
  return o;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let tex = textureSample(atlas, samp, in.uv, in.layer);
  if (tex.a < 0.5) { discard; }                       // alpha cutout (leaves/glass)
  // ONE flat daylight tone (warm sun by day, cool sky by night; dims with the
  // sun's intensity) applied to EVERY face — the per-face factor + AO do the
  // shaping. No dot(normal, sun), so no face ever goes dark.
  let day = clamp(u.sunCol.w, 0.0, 1.0);
  let tone = mix(u.ambSky.rgb * 0.55, u.sunCol.rgb, day) + u.ambGround.rgb * (u.fogColor.a * 0.22);
  var rgb = tex.rgb * tone * FACE[in.face] * in.ao;
  if (u.params.z > 0.5) {
    let f = smoothstep(u.params.x, u.params.y, distance(u.camPos.xyz, in.world));
    rgb = mix(rgb, u.fogColor.rgb, f);
  }
  return vec4f(rgb, 1.0);
}
`;

export interface VoxelOptions extends VoxelWorldOptions {
  /** Block-texture resolution in texels (default 16 — classic). */
  tileRes?: number;
  /** Texture-pack seed (default 1). */
  seed?: number;
  /** World-units per block (default 1). */
  blockSize?: number;
  /** Generate + smooth-filter mipmaps (default true — kills distant shimmer). */
  mipmaps?: boolean;
  /** Draw chunks past this distance from the camera are skipped (default: fog far, else 512). */
  cullDist?: number;
}

interface ChunkBuf { vbuf: GPUBuffer | null; count: number; }

/** The renderable voxel world. `world.voxels()` builds it; edit via set/get,
 * pick blocks with `raycast`, and it draws itself inside the world's pass. */
export class Voxels3d {
  readonly world: VoxelWorld;
  readonly blockSize: number;
  private bufs: ChunkBuf[];
  private atlasTex!: GPUTexture;
  private sampler!: GPUSampler;
  private pipeline!: GPURenderPipeline;
  private bind!: GPUBindGroup;
  private layout!: GPUBindGroupLayout;
  private readonly tileRes: number; private readonly seed: number; private readonly mip: boolean;
  private cullDist: number;

  constructor(
    private device: GPUDevice,
    private format: GPUTextureFormat,
    private sampleCount: number,
    private uniforms: GPUBuffer,
    private camera: { x: number; y: number; z: number },
    opts: VoxelOptions = {},
  ) {
    this.world = new VoxelWorld(opts);
    this.blockSize = opts.blockSize ?? 1;
    this.tileRes = opts.tileRes ?? 16;
    this.seed = opts.seed ?? 1;
    this.mip = opts.mipmaps ?? true;
    this.cullDist = opts.cullDist ?? 512;
    this.bufs = Array.from({ length: this.world.chunkCount }, () => ({ vbuf: null, count: 0 }));
    this.buildGpu();
  }

  /** Device-loss recovery: adopt the fresh device + world uniforms, drop the
   * dead vertex buffers, and rebuild every GPU object from the CPU model. */
  rebuild(device: GPUDevice, uniforms: GPUBuffer): void {
    this.device = device; this.uniforms = uniforms;
    this.bufs = Array.from({ length: this.world.chunkCount }, () => ({ vbuf: null, count: 0 }));
    this.buildGpu();
  }

  /** (Re)build all GPU resources — also the device-loss recovery entry point. */
  buildGpu(): void {
    const d = this.device;
    this.uploadAtlas();
    this.sampler = d.createSampler({
      magFilter: 'nearest',                                  // crisp block texels
      minFilter: this.mip ? 'linear' : 'nearest',
      mipmapFilter: 'linear',
      addressModeU: 'repeat', addressModeV: 'repeat',
    });
    this.layout = d.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'float', viewDimension: '2d-array' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, sampler: { type: 'filtering' } },
      ],
    });
    const mod = shaderModule(d, VOXEL_WGSL, 'Voxels3d');
    this.pipeline = d.createRenderPipeline({
      layout: d.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: {
        module: mod, entryPoint: 'vs',
        buffers: [{
          arrayStride: VOX_FLOATS * 4,
          attributes: [
            { shaderLocation: 0, offset: 0, format: 'float32x3' },   // pos
            { shaderLocation: 1, offset: 12, format: 'float32x2' },  // uv
            { shaderLocation: 2, offset: 20, format: 'float32' },    // layer
            { shaderLocation: 3, offset: 24, format: 'float32' },    // face
            { shaderLocation: 4, offset: 28, format: 'float32' },    // ao
          ],
        }],
      },
      fragment: { module: mod, entryPoint: 'fs', targets: [{ format: this.format }] },
      primitive: { topology: 'triangle-list', cullMode: 'back', frontFace: 'ccw' },
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: true, depthCompare: 'less-equal' },
      multisample: { count: this.sampleCount },
    });
    this.bind = d.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: this.atlasTex.createView({ dimension: '2d-array' }) },
        { binding: 2, resource: this.sampler },
      ],
    });
    this.world.markAllDirty();
  }

  private uploadAtlas(): void {
    const d = this.device, res = this.tileRes;
    const { data, layers } = bakeTiles(res, this.seed);
    const mipCount = this.mip ? 1 + Math.floor(Math.log2(res)) : 1;
    this.atlasTex = d.createTexture({
      size: { width: res, height: res, depthOrArrayLayers: layers },
      format: 'rgba8unorm-srgb',
      mipLevelCount: mipCount,
      // NB: 0x2 is the TEXTURE COPY_DST bit — BITS.COPY_DST (0x8) is the BUFFER
      // value, which as a texture flag means STORAGE_BINDING (invalid on srgb).
      usage: BITS.TEXTURE_BINDING | 0x2,
    });
    for (let l = 0; l < layers; l++) {
      let px = data.subarray(l * res * res * 4, (l + 1) * res * res * 4) as Uint8Array;
      let w = res, h = res;
      for (let m = 0; m < mipCount; m++) {
        d.queue.writeTexture(
          { texture: this.atlasTex, mipLevel: m, origin: { x: 0, y: 0, z: l } },
          px, { bytesPerRow: w * 4, rowsPerImage: h }, { width: w, height: h, depthOrArrayLayers: 1 });
        if (m + 1 < mipCount) { const n = halveRGBA(px, w, h); px = n.px; w = n.w; h = n.h; }
      }
    }
  }

  // ── Editing / queries (delegate to the CPU model) ──
  get(x: number, y: number, z: number): number { return this.world.get(x, y, z); }
  set(x: number, y: number, z: number, id: number): void { this.world.set(x, y, z, id); }
  /** Author the world in bulk: `(x,y,z) => blockId`. Marks everything dirty. */
  generate(fn: (x: number, y: number, z: number) => number): void {
    const w = this.world;
    for (let y = 0; y < w.sy; y++) for (let z = 0; z < w.sz; z++) for (let x = 0; x < w.sx; x++) {
      const id = fn(x, y, z); if (id) w.set(x, y, z, id);
    }
  }

  /** Build (or REBUILD) a landscape: clears the world then fills it with the
   * chosen land type. Call again with a new `seed` for a reseed button. */
  landscape(opts: VoxelTerrainOptions = {}): void {
    this.world.clear();
    voxelTerrain(this.world, opts);
  }

  /** World-space Y (feet) to drop a body/mob at column (x, z) — just above the
   * highest solid block. Returns `blockSize`-scaled units. */
  spawnY(x: number, z: number): number {
    return (this.world.columnTop((x / this.blockSize) | 0, (z / this.blockSize) | 0) + 1) * this.blockSize;
  }

  /**
   * Raycast from a world-space origin/direction, returning the block hit (in
   * BLOCK coordinates) and the entry face normal — for breaking (`hit`) and
   * placing (`hit + normal`). Coordinates are divided by blockSize internally.
   */
  raycast(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, maxDist = 64): VoxelHit | null {
    const b = this.blockSize;
    return raycastVoxel((x, y, z) => this.world.get(x, y, z), ox / b, oy / b, oz / b, dx, dy, dz, maxDist / b);
  }

  /** Re-mesh dirty chunks + upload their vertex buffers. Call once per frame
   * (world.prepare does this). Budget-capped so a big edit burst can't stall. */
  remeshDirty(budget = 8): void {
    if (!this.world.dirty.size) return;
    const b = this.blockSize, ch = this.world.ch;
    let done = 0;
    for (const idx of this.world.dirty) {
      const [cx, cy, cz] = this.world.chunkCoords(idx);
      const verts = meshChunk((x, y, z) => this.world.get(x, y, z), cx * ch, cy * ch, cz * ch, ch);
      const buf = this.bufs[idx];
      if (verts.length === 0) { buf.vbuf?.destroy(); buf.vbuf = null; buf.count = 0; }
      else {
        // Scale block-space positions into world units in place.
        if (b !== 1) for (let i = 0; i < verts.length; i += VOX_FLOATS) { verts[i] *= b; verts[i + 1] *= b; verts[i + 2] *= b; }
        if (!buf.vbuf || buf.vbuf.size < verts.byteLength) {
          buf.vbuf?.destroy();
          buf.vbuf = this.device.createBuffer({ size: verts.byteLength, usage: BITS.VERTEX | BITS.COPY_DST });
        }
        this.device.queue.writeBuffer(buf.vbuf, 0, verts);
        buf.count = verts.length / VOX_FLOATS;
      }
      this.world.dirty.delete(idx);
      if (++done >= budget) break;
    }
  }

  /** Draw every non-empty, in-range chunk. Called from world.renderOpaque. */
  render(pass: GPURenderPassEncoder): void {
    let set = false;
    const b = this.blockSize, ch = this.world.ch, half = (ch * b) * 0.5, cull2 = this.cullDist * this.cullDist;
    for (let idx = 0; idx < this.bufs.length; idx++) {
      const buf = this.bufs[idx];
      if (!buf.vbuf || !buf.count) continue;
      const [cx, cy, cz] = this.world.chunkCoords(idx);
      const dx = (cx * ch * b + half) - this.camera.x, dy = (cy * ch * b + half) - this.camera.y, dz = (cz * ch * b + half) - this.camera.z;
      if (dx * dx + dy * dy + dz * dz > cull2) continue;
      if (!set) { pass.setPipeline(this.pipeline); pass.setBindGroup(0, this.bind); set = true; }
      pass.setVertexBuffer(0, buf.vbuf);
      pass.draw(buf.count);
    }
  }

  /** Live stats for a HUD/debug panel: chunks currently drawn (non-empty) and
   * the total uploaded vertex count. */
  get stats(): { chunks: number; verts: number } {
    let chunks = 0, verts = 0;
    for (const b of this.bufs) if (b.count) { chunks++; verts += b.count; }
    return { chunks, verts };
  }

  destroy(): void {
    for (const b of this.bufs) b.vbuf?.destroy();
    this.bufs = [];
    this.atlasTex?.destroy();
  }
}
