// SKY — E2 of the RICH ENVIRONMENTS kit: the dome over the terrain.
// A fullscreen pass at FAR depth (drawn after the solids — only empty
// pixels shade) that computes the sky PROCEDURALLY per pixel: gradient +
// sun disc/glow + two scrolling FBM cloud layers + stars and a moon at
// night. One `sky.time` dial (0..24 h) drives EVERYTHING — the sky
// colours, the sun's direction/colour/intensity, the hemisphere ambient,
// the fog colour and the env re-bake — so day/night is a single number.
//
// Storm is a DIAL, not a mode: `sky.storm` 0→1 raises coverage/density
// and darkens both the clouds and the sun.
//
// The pure core (skyState) is dist-tested: sun geometry and palette
// interpolation have no visual check for correctness — noon overhead,
// midnight below the horizon, sunset warm, midnight starry.
import { BITS, shaderModule } from './gpu.js';
import { rgba } from './color.js';
import { DEPTH_FORMAT } from './batch.js';

// ── The day: palette keyframes over 24 hours ────────────────────────────────

export interface SkyState {
  /** Unit vector TOWARD the sun (below the horizon at night). */
  sunPos: [number, number, number];
  /** The direction light TRAVELS (what world.setSun wants): -sunPos. */
  sunDir: [number, number, number];
  sunColor: [number, number, number];
  /** Direct-sun intensity multiplier (1 = full noon, ~0 at night). */
  sunI: number;
  zenith: [number, number, number];
  horizon: [number, number, number];
  glow: [number, number, number];
  ambient: number;
  ambSky: [number, number, number];
  ambGround: [number, number, number];
  fog: [number, number, number];
  /** Star-field opacity (0 by day). */
  stars: number;
  /** Moon-disc opacity. */
  moon: number;
}

interface Key {
  t: number;
  zenith: string; horizon: string; glow: string;
  sun: string; sunI: number;
  ambient: number; ambSky: string; ambGround: string;
  fog: string; stars: number; moon: number;
}

// Hand-tuned stops. Colours are linear-ish hex; interpolation is linear in
// rgb — good enough at these saturations.
// The palette CLOCK must agree with the sun GEOMETRY (el = 0 at exactly
// 6:00 and 18:00): golden hour keys sit just BEFORE 18:00, dusk just after
// — a "sunset" palette while the sun is 20° under the horizon lights the
// world from below and the land goes black (shipped once; caught on the
// 18.6 screenshot).
const KEYS: Key[] = [
  { t: 0.0, zenith: '#05070f', horizon: '#0c1220', glow: '#101a2e', sun: '#a8c0e8', sunI: 0.14, ambient: 0.17, ambSky: '#28344e', ambGround: '#12151d', fog: '#0a0f1a', stars: 1.0, moon: 1.0 },
  { t: 4.6, zenith: '#070b18', horizon: '#181a30', glow: '#2a2440', sun: '#c0a8d8', sunI: 0.13, ambient: 0.17, ambSky: '#2a3450', ambGround: '#141720', fog: '#121422', stars: 0.85, moon: 0.85 },
  { t: 6.0, zenith: '#20365e', horizon: '#b06a4a', glow: '#ff9a58', sun: '#ff9660', sunI: 0.45, ambient: 0.24, ambSky: '#6a6a88', ambGround: '#3a3230', fog: '#7a6a68', stars: 0.15, moon: 0.2 },
  { t: 7.5, zenith: '#38659e', horizon: '#d8b088', glow: '#ffd9a0', sun: '#ffd9b0', sunI: 0.85, ambient: 0.34, ambSky: '#a8b8d8', ambGround: '#7a705e', fog: '#b0b4c0', stars: 0, moon: 0 },
  { t: 11.0, zenith: '#2f66b8', horizon: '#a9c9e8', glow: '#e8f2f8', sun: '#fff8ec', sunI: 1.05, ambient: 0.44, ambSky: '#cfe0f5', ambGround: '#8c8672', fog: '#9ab4cc', stars: 0, moon: 0 },
  { t: 15.0, zenith: '#3468b4', horizon: '#aac6e0', glow: '#e8eef2', sun: '#fff4dc', sunI: 1.0, ambient: 0.42, ambSky: '#c8dcf0', ambGround: '#8a8470', fog: '#9cb2c8', stars: 0, moon: 0 },
  { t: 17.0, zenith: '#3a5a94', horizon: '#dda86e', glow: '#ffc678', sun: '#ffd090', sunI: 0.8, ambient: 0.36, ambSky: '#b0a8b8', ambGround: '#6e6252', fog: '#af9c94', stars: 0, moon: 0 },
  { t: 18.0, zenith: '#22315e', horizon: '#d06a3e', glow: '#ff8a4a', sun: '#ff7e42', sunI: 0.4, ambient: 0.27, ambSky: '#726a8c', ambGround: '#3c3230', fog: '#6e5a5c', stars: 0.05, moon: 0.1 },
  { t: 19.3, zenith: '#0e1636', horizon: '#4a3050', glow: '#8a4a5a', sun: '#d090b0', sunI: 0.12, ambient: 0.2, ambSky: '#3a4260', ambGround: '#1a1a26', fog: '#242038', stars: 0.55, moon: 0.55 },
  { t: 21.0, zenith: '#060912', horizon: '#0e1424', glow: '#142036', sun: '#aac2e8', sunI: 0.14, ambient: 0.17, ambSky: '#28344e', ambGround: '#12151d', fog: '#0c1120', stars: 1.0, moon: 1.0 },
];

const tri = (hex: string): [number, number, number] => {
  const c = rgba(hex);
  return [c[0], c[1], c[2]];
};
const lerp3 = (a: [number, number, number], b: [number, number, number], t: number): [number, number, number] =>
  [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

/** The pure day/night core: 0..24 h → palette + sun geometry. Wraps. */
export function skyState(time: number): SkyState {
  const t = ((time % 24) + 24) % 24;
  // Bracketing keyframes (KEYS wraps 22.5 → 24+0.0).
  let i = KEYS.length - 1;
  for (let k = 0; k < KEYS.length; k++) { if (KEYS[k].t <= t) i = k; }
  const a = KEYS[i];
  const b = KEYS[(i + 1) % KEYS.length];
  const span = (b.t - a.t + 24) % 24 || 24;
  const f = ((t - a.t + 24) % 24) / span;

  // Sun geometry: rises +x at 6:00, sets -x at 18:00, arcs with a southward
  // lean so noon shadows aren't degenerate. Keeps sweeping below the
  // horizon at night (the moon rides the antipode).
  const dayT = (t - 6) / 12;
  const el = Math.sin(dayT * Math.PI) * (65 * Math.PI / 180);
  const az = dayT * Math.PI;
  const ce = Math.cos(el);
  let sx = Math.cos(az) * ce, sy = Math.sin(el), sz = -0.45 * ce;
  const sl = Math.hypot(sx, sy, sz) || 1;
  sx /= sl; sy /= sl; sz /= sl;
  // DEEP NIGHT: the world light comes DOWN from the MOON (the antipode),
  // not up from the buried sun. Hard switch once the sun is well under
  // (direct intensity is ~0.1 there — the flip is imperceptible).
  const night = sy < -0.12;

  return {
    sunPos: [sx, sy, sz],
    sunDir: night ? [sx, sy, sz] : [-sx, -sy, -sz],
    sunColor: lerp3(tri(a.sun), tri(b.sun), f),
    sunI: a.sunI + (b.sunI - a.sunI) * f,
    zenith: lerp3(tri(a.zenith), tri(b.zenith), f),
    horizon: lerp3(tri(a.horizon), tri(b.horizon), f),
    glow: lerp3(tri(a.glow), tri(b.glow), f),
    ambient: a.ambient + (b.ambient - a.ambient) * f,
    ambSky: lerp3(tri(a.ambSky), tri(b.ambSky), f),
    ambGround: lerp3(tri(a.ambGround), tri(b.ambGround), f),
    fog: lerp3(tri(a.fog), tri(b.fog), f),
    stars: a.stars + (b.stars - a.stars) * f,
    moon: a.moon + (b.moon - a.moon) * f,
  };
}

// ── The public handle ───────────────────────────────────────────────────────

export interface SkyOptions {
  /** Hour of day 0..24 (default 11 — late morning). */
  time?: number;
  /** Auto-advance: seconds of real time per full day (0 = paused). */
  cycle?: number;
  clouds?: boolean;
  /** Cloud sky-fraction 0..1 (default 0.45). */
  coverage?: number;
  /** Cloud opacity 0..1 (default 0.65). */
  density?: number;
  /** Cloud drift direction + rate (world-ish units; default gentle west). */
  wind?: { x: number; z: number };
  /** Cloud drift speed multiplier (default 1). Clouds always drift on their
   * own wall-clock — this dial scales how fast, independent of `cycle`. */
  cloudSpeed?: number;
  /** Storm dial 0..1: coverage + density up, clouds and sun darken. */
  storm?: number;
  stars?: boolean;
  /** Sky drives sun/ambient/fog/env from `time` (default true — set false
   * to keep manual setSun/setAmbient control and use the dome visuals only). */
  drive?: boolean;
  /** LENS FLARE on the sun (default true — it is depth-occluded and fades
   * with night/storm/off-screen, so it never misbehaves). */
  flare?: boolean;
}

/** Returned by world.sky(): every field is live. */
export class Sky3d {
  time: number;
  cycleSecondsPerDay: number;
  clouds: boolean;
  coverage: number;
  density: number;
  wind: { x: number; z: number };
  cloudSpeed: number;
  storm: number;
  stars: boolean;
  drive: boolean;
  flare: boolean;
  /** @internal env re-bake throttle: sun elevation at the last bake. */
  lastBakeY = 99;

  constructor(o: SkyOptions = {}) {
    this.time = o.time ?? 11;
    this.cycleSecondsPerDay = o.cycle ?? 0;
    this.clouds = o.clouds ?? true;
    this.coverage = o.coverage ?? 0.45;
    this.density = o.density ?? 0.65;
    this.wind = o.wind ?? { x: 1, z: 0.35 };
    this.cloudSpeed = o.cloudSpeed ?? 1;
    this.storm = o.storm ?? 0;
    this.stars = o.stars ?? true;
    this.drive = o.drive ?? true;
    this.flare = o.flare ?? true;
  }

  /** Auto-advance the clock: one full day per `seconds` (0 stops). */
  cycle(seconds: number): void { this.cycleSecondsPerDay = seconds; }

  /** @internal Star-frame angle (radians): accumulated from time DELTAS so
   * it never jumps at the midnight wrap, and geared down — a 1:1 sidereal
   * rate reads frantic under a 90-second day (Rich: "the stars move SO
   * fast"). 0.12 of a revolution per day keeps the wheel visible but calm. */
  starAngle = 0;
  private lastTime: number | null = null;

  /** Advance + resolve the current state (the world calls this). */
  tick(dt: number): SkyState {
    if (this.cycleSecondsPerDay > 0) {
      this.time = (this.time + (24 / this.cycleSecondsPerDay) * dt) % 24;
    }
    if (this.lastTime == null) this.lastTime = this.time;
    const dh = ((this.time - this.lastTime + 36) % 24) - 12;   // shortest signed wrap
    this.starAngle += (dh / 24) * Math.PI * 2 * 0.12;
    this.lastTime = this.time;
    return skyState(this.time);
  }
}

// ── Constellations ──────────────────────────────────────────────────────────
// Recognisable patterns among the random field: authored as 2D degree
// offsets on a tangent plane at (azimuth, elevation), baked to unit dirs at
// module load and emitted into the shader as constants. They ride the same
// slowly-wheeling star frame as the field.

const CONSTELLATIONS: Array<{ az: number; el: number; stars: Array<[number, number, number?]> }> = [
  // The Plough / Big Dipper — bowl + bent handle.
  { az: 40, el: 48, stars: [[0, 0], [4, 1.5], [8, 2], [12, 1], [16, 3], [15.5, 7], [11, 6.2]] },
  // Orion — shoulders, the belt of three, feet (Betelgeuse + Rigel brighter).
  { az: 185, el: 38, stars: [[2.4, 5.6, 1.3], [-2.6, 5.2], [-1, 0.7], [0, 0], [1, -0.7], [-2.2, -5.4, 1.3], [2, -5]] },
  // Cassiopeia — the W.
  { az: 300, el: 55, stars: [[-6, 0], [-3, 2.6], [0, 0.4], [3, 3], [6, 1]] },
  // The Southern Cross.
  { az: 120, el: 28, stars: [[0, 3, 1.15], [0, -3], [-2.4, 0], [2.6, 0.6]] },
];

/** Constellation stars as unit directions + brightness (pure; tested). */
export function constellationDirs(): Array<{ x: number; y: number; z: number; b: number }> {
  const D = Math.PI / 180;
  const out: Array<{ x: number; y: number; z: number; b: number }> = [];
  for (const c of CONSTELLATIONS) {
    const az = c.az * D, el = c.el * D;
    const C = [Math.cos(el) * Math.sin(az), Math.sin(el), Math.cos(el) * Math.cos(az)];
    // Tangent basis: e1 east-ish (horizontal), e2 toward the zenith.
    let e1 = [C[2], 0, -C[0]];
    const l1 = Math.hypot(e1[0], e1[1], e1[2]) || 1;
    e1 = [e1[0] / l1, e1[1] / l1, e1[2] / l1];
    const e2 = [
      C[1] * e1[2] - C[2] * e1[1],
      C[2] * e1[0] - C[0] * e1[2],
      C[0] * e1[1] - C[1] * e1[0],
    ];
    for (const [dx, dy, b = 1] of c.stars) {
      const x = dx * D, y = dy * D;
      const v = [C[0] + e1[0] * x + e2[0] * y, C[1] + e1[1] * x + e2[1] * y, C[2] + e1[2] * x + e2[2] * y];
      const vl = Math.hypot(v[0], v[1], v[2]) || 1;
      out.push({ x: v[0] / vl, y: v[1] / vl, z: v[2] / vl, b });
    }
  }
  return out;
}

const CSTARS = constellationDirs();
const CSTARS_WGSL = `const CSTARS = array<vec4f, ${CSTARS.length}>(${CSTARS.map((s) =>
  `vec4f(${s.x.toFixed(6)}, ${s.y.toFixed(6)}, ${s.z.toFixed(6)}, ${s.b})`).join(', ')});`;

// ── The GPU layer ───────────────────────────────────────────────────────────

const SKY_WGSL = /* wgsl */ `
${CSTARS_WGSL}
struct SU {
  fwd: vec4f,        // camera forward + tanHalfX
  right: vec4f,      // camera right + tanHalfY
  up: vec4f,         // camera up + time (seconds)
  sunPos: vec4f,     // toward the sun + direct intensity
  sunCol: vec4f,     // sun rgb + moon alpha
  zenith: vec4f,     // rgb + star alpha
  horizon: vec4f,    // rgb + coverage cutoff
  glow: vec4f,       // rgb + cloud density
  cloudLit: vec4f,   // rgb + cloud uv scale
  cloudShade: vec4f, // rgb + wind speed
  wind: vec4f,       // dir x, z, cloudsOn, unused
  fog: vec4f,        // rgb + star-frame hour angle
}
@group(0) @binding(0) var<uniform> su: SU;

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) ndc: vec2f,
}

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  // One triangle covering the screen, at MAXIMUM depth: with less-equal it
  // shades exactly the pixels no solid wrote.
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var out: VSOut;
  out.pos = vec4f(p[vi], 1.0, 1.0);
  out.ndc = p[vi];
  return out;
}

fn h21(p: vec2f) -> f32 { return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453); }
fn h31(p: vec3f) -> f32 { return fract(sin(dot(p, vec3f(127.1, 311.7, 74.7))) * 43758.5453); }

fn vnoise(p: vec2f) -> f32 {
  let i = floor(p); let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = h21(i); let b = h21(i + vec2f(1.0, 0.0));
  let c = h21(i + vec2f(0.0, 1.0)); let d = h21(i + vec2f(1.0, 1.0));
  return a + (b - a) * u.x + (c - a) * u.y + (a - b - c + d) * u.x * u.y;
}

// Rotated-octave fbm: the rotation between octaves kills the axis-aligned
// streaking plain lacunarity produces — billows, not plaid.
fn fbm(p0: vec2f) -> f32 {
  var p = p0;
  var s = 0.0; var amp = 0.5; var norm = 0.0;
  let rot = mat2x2f(0.8, 0.6, -0.6, 0.8);
  for (var o = 0; o < 5; o = o + 1) {
    s += vnoise(p) * amp;
    norm += amp;
    amp *= 0.55;
    p = rot * p * 2.05 + vec2f(17.3, 9.1);
  }
  return s / norm;
}

// One cloud plane: returns (opacity, litness). uv from the ray-plane hit.
// The BILLOW recipe: warped base mass, ERODED by high-frequency detail at
// the edges (edges thin -> detail eats them first = puffy silhouettes),
// litness from the sun-displaced resample (silver lining).
fn cloudLayer(ray: vec3f, scale: f32, windT: vec2f, cutoff: f32, sunXZ: vec2f) -> vec3f {
  let uv = ray.xz / (ray.y + 0.10) * scale + windT;
  let warp = fbm(uv * 1.9 + vec2f(31.7, 11.3)) - 0.5;
  let wuv = uv + vec2f(warp * 0.9);
  // CONTRAST: normalised fbm has a tight sigma around 0.5 — stretch it so
  // the field actually crosses the coverage cutoff into solid masses.
  let n = (fbm(wuv) - 0.5) * 1.9 + 0.5;
  let detail = fbm(wuv * 3.3 + windT * 0.4) - 0.5;
  let dens = n + detail * 0.3;
  let c = smoothstep(cutoff, cutoff + 0.24, dens);
  // Interior body: alpha keeps rising past the edge so cores read solid.
  let body = smoothstep(cutoff, cutoff + 0.55, dens);
  let n2 = fbm(wuv + sunXZ * 0.16);
  let lit = clamp(0.55 + (n - n2) * 4.0, 0.0, 1.3);
  return vec3f(c, lit, body);
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let ray = normalize(su.fwd.xyz + su.right.xyz * (in.ndc.x * su.fwd.w) + su.up.xyz * (in.ndc.y * su.right.w));
  let h = ray.y;
  let time = su.up.w;

  // ── Gradient: horizon → zenith, with a sun-weighted glow band ───────────
  var col = mix(su.horizon.rgb, su.zenith.rgb, pow(clamp(h, 0.0, 1.0), 0.55));
  let flatSun = normalize(vec3f(su.sunPos.x, 0.0, su.sunPos.z) + vec3f(1e-5));
  let flatRay = normalize(vec3f(ray.x, 0.0, ray.z) + vec3f(1e-5));
  let sunSide = dot(flatSun, flatRay) * 0.5 + 0.5;
  col += su.glow.rgb * exp(-abs(h) * 8.0) * (0.3 + 0.7 * sunSide);
  // Below the horizon: settle to the fog/haze floor.
  col = mix(col, su.fog.rgb * 0.75, smoothstep(0.0, -0.22, h));

  // ── Clouds are computed FIRST (composited last): everything celestial —
  // stars, sun disc, moon — attenuates by the cloud opacity in front of it,
  // so nothing ever reads as floating in front of the deck.
  var alpha0 = 0.0; var alpha1 = 0.0;
  var cc0 = vec3f(0.0); var cc1 = vec3f(0.0);
  if (su.wind.z > 0.5 && h > 0.006) {
    let cutoff = su.horizon.w;
    let density = su.glow.w;
    let scale = su.cloudLit.w;
    let wt = su.wind.xy * (time * su.cloudShade.w);
    let sunXZ = su.sunPos.xz;
    // Fade only at the very last sliver of horizon (uv blows up there) —
    // clouds are SUPPOSED to stack low against the horizon.
    let fade = smoothstep(0.006, 0.045, h);
    // High layer: thin, fast, fine — a veil, never solid.
    let c1 = cloudLayer(ray, scale * 2.6, wt * 1.6 + vec2f(53.0), cutoff + 0.16, sunXZ);
    cc1 = mix(su.cloudShade.rgb, su.cloudLit.rgb, c1.y);
    alpha1 = min(c1.x * density * 0.4, 0.55) * fade;
    // Main layer: chunky billows with solid bright cores.
    let c0 = cloudLayer(ray, scale, wt, cutoff, sunXZ);
    let litCore = clamp(c0.y + c0.z * 0.35, 0.0, 1.35);
    cc0 = mix(su.cloudShade.rgb, su.cloudLit.rgb, litCore);
    alpha0 = min(c0.x * (0.55 + 0.45 * c0.z) * density, 0.96) * fade;
  }
  let clear = 1.0 - min(alpha0 + alpha1, 1.0);

  // ── Stars (night only, above the horizon, BEHIND the clouds) ────────────
  // Stars are DIM POINT sources: even thin cloud kills them completely —
  // a linear fade left them glowing through the veil layer and reading as
  // in-front. The steep curve snuffs them the moment any deck arrives.
  let starVis = smoothstep(0.55, 0.95, clear);
  if (su.zenith.w > 0.001 && h > 0.0 && starVis > 0.01) {
    // The whole star frame WHEELS slowly about a tilted pole (fog.w — the
    // geared angle from Sky3d.tick) — constellations rise and set.
    let ax = normalize(vec3f(0.16, 1.0, 0.09));
    let ca = cos(su.fog.w); let sa = sin(su.fog.w);
    let sray = ray * ca + cross(ax, ray) * sa + ax * dot(ax, ray) * (1.0 - ca);
    let horizFade = smoothstep(0.0, 0.12, h) * su.zenith.w * starVis;
    let sp = sray * 340.0;
    let cell = floor(sp);
    let rz = h31(cell + vec3f(0.5));
    if (rz > 0.93) {
      let jitter = vec3f(h31(cell + vec3f(11.0)), h31(cell + vec3f(23.0)), h31(cell + vec3f(37.0)));
      let d = length(fract(sp) - 0.5 - (jitter - 0.5) * 0.5);
      // Twinkle gets its OWN hash (rz spans only 0.93..1 — phases derived
      // from it fade every star in unison). And it's SUBTLE: stars mostly
      // hold steady; roughly a fifth GLINT sharply now and then.
      let twr = h31(cell + vec3f(71.3));
      let tw = 0.92 + 0.08 * sin(time * (0.4 + twr * 1.4) + twr * 44.0);
      let glint = step(0.8, twr) * pow(max(sin(time * (0.5 + twr * 0.9) + twr * 91.0), 0.0), 28.0) * 0.9;
      col += vec3f(smoothstep(0.28, 0.0, d)) * (rz - 0.93) * 12.0 * (tw + glint) * horizFade;
    }
    // Constellations: a touch brighter and steadier than the field — NAMED
    // stars, not moons (the first cut drew 1°-wide discs; Rich's screenshot).
    for (var i = 0; i < ${CSTARS.length}; i = i + 1) {
      let cs = CSTARS[i];
      let dd = dot(sray, cs.xyz);
      col += vec3f(0.92, 0.95, 1.0) * (smoothstep(0.9999985, 0.9999995, dd) * 1.25 + pow(max(dd, 0.0), 300000.0) * 0.22) * cs.w * horizFade;
    }
  }

  // ── The sun: hard disc + tight glow + wide haze (disc dims behind cloud) ─
  let sd = dot(ray, su.sunPos.xyz);
  let sunI = su.sunPos.w;
  let sunClear = 0.12 + 0.88 * clear;
  col += su.sunCol.rgb * smoothstep(0.99955, 0.99985, sd) * (1.6 + sunI * 2.2) * sunClear;
  col += su.sunCol.rgb * pow(max(sd, 0.0), 220.0) * 0.55 * sunI * sunClear;
  col += su.sunCol.rgb * pow(max(sd, 0.0), 7.0) * 0.14 * (0.25 + sunI);

  // ── The moon: the antipode, cool, mostly night ──────────────────────────
  let moonA = su.sunCol.w;
  if (moonA > 0.001) {
    let md = dot(ray, -su.sunPos.xyz);
    let moonCol = vec3f(0.86, 0.9, 0.98);
    col += moonCol * smoothstep(0.99975, 0.99991, md) * 1.4 * moonA * sunClear;
    col += moonCol * pow(max(md, 0.0), 300.0) * 0.3 * moonA;
  }

  // ── Composite the decks over everything ──────────────────────────────────
  col = mix(col, cc1, alpha1);
  col = mix(col, cc0, alpha0);

  return vec4f(col, 1.0);
}
`;

/** GPU plumbing for the sky pass — owned by World3d, drawn at the end of
 * the opaque pass. */
export class Sky3dLayer {
  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private buf!: GPUBuffer;
  private bind!: GPUBindGroup;
  readonly data = new Float32Array(48);

  constructor(device: GPUDevice, private format: GPUTextureFormat, private sampleCount: number) {
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.buf = device.createBuffer({ size: this.data.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST });
    const module = shaderModule(device, SKY_WGSL, 'sky3d');
    const layout = device.createBindGroupLayout({
      entries: [{ binding: 0, visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT, buffer: { type: 'uniform' } }],
    });
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [layout] }),
      vertex: { module, entryPoint: 'vs' },
      fragment: { module, entryPoint: 'fs', targets: [{ format: this.format }] },
      // less-equal at z = 1: shades exactly the pixels no solid wrote.
      depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-list' },
      multisample: { count: this.sampleCount },
    });
    this.bind = device.createBindGroup({ layout, entries: [{ binding: 0, resource: { buffer: this.buf } }] });
  }

  /** Pack + upload this frame's uniforms. */
  write(
    s: SkyState, sky: Sky3d, time: number,
    fwd: [number, number, number], right: [number, number, number], up: [number, number, number],
    tanX: number, tanY: number,
  ): void {
    // The storm dial: more cloud, darker cloud, dimmer sun.
    const storm = Math.min(1, Math.max(0, sky.storm));
    const coverage = sky.coverage + (0.92 - sky.coverage) * storm;
    const density = Math.min(1, sky.density + 0.45 * storm);
    const cutoff = 0.72 - coverage * 0.5;            // more coverage = lower cutoff
    const sunI = s.sunI * (1 - 0.65 * storm);
    const dayLum = 0.18 + sunI * 0.85;
    const darken = 1 - 0.55 * storm;
    const lit: [number, number, number] = [
      (0.62 + s.sunColor[0] * 0.38) * dayLum * darken,
      (0.62 + s.sunColor[1] * 0.38) * dayLum * darken,
      (0.62 + s.sunColor[2] * 0.38) * dayLum * darken,
    ];
    const shade: [number, number, number] = [
      (s.zenith[0] * 0.5 + 0.10) * dayLum * darken,
      (s.zenith[1] * 0.5 + 0.11) * dayLum * darken,
      (s.zenith[2] * 0.5 + 0.13) * dayLum * darken,
    ];
    const d = this.data;
    d.set([fwd[0], fwd[1], fwd[2], tanX], 0);
    d.set([right[0], right[1], right[2], tanY], 4);
    d.set([up[0], up[1], up[2], time], 8);
    d.set([s.sunPos[0], s.sunPos[1], s.sunPos[2], sunI], 12);
    d.set([s.sunColor[0], s.sunColor[1], s.sunColor[2], sky.stars ? s.moon : 0], 16);
    d.set([s.zenith[0], s.zenith[1], s.zenith[2], sky.stars ? s.stars : 0], 20);
    d.set([s.horizon[0], s.horizon[1], s.horizon[2], cutoff], 24);
    d.set([s.glow[0], s.glow[1], s.glow[2], density], 28);
    d.set([lit[0], lit[1], lit[2], 0.85], 32);              // cloud uv scale
    // Wind speed factor: the old fixed 0.006 uv/s took ~a minute for a cloud
    // to cross its own width — "the clouds don't move". 0.012 at the default
    // dial reads as a live sky; cloudSpeed scales from becalmed to racing.
    d.set([shade[0], shade[1], shade[2], 0.012 * sky.cloudSpeed], 36);
    d.set([sky.wind.x, sky.wind.z, sky.clouds ? 1 : 0, 0], 40);
    // fog.w = the star frame's angle (accumulated + geared in Sky3d.tick).
    d.set([s.fog[0], s.fog[1], s.fog[2], sky.starAngle], 44);
    this.device.queue.writeBuffer(this.buf, 0, this.data);
  }

  draw(pass: GPURenderPassEncoder): void {
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(3);
  }
}
