// LIGHTING 2.0 TIER 1 (parity-plan Phase 4) — CLUSTERED FORWARD+ lights.
// The WebGPU-native move: a compute pass bins point/spot lights into froxel
// clusters (screen tiles × logarithmic depth slices, in VIEW space); the
// mesh fragment reads its cluster's short list and shades only the lights
// that can actually reach it. Dozens-to-hundreds of dynamic lights, one
// geometry pass, no deferred G-buffer.
//
// Division of labour: THIS module owns the light handles, the view-space
// packing, the cluster table and its compute kernel, and the group(1) bind
// the mesh pipeline consumes. world3d.ts owns the mesh shader's shading
// loop and the directional shadow map (both live in MESH_WGSL).
//
// Pure parts (froxel bounds, CPU binning twin, WGSL assembly) are exported
// and dist-tested — cluster bugs are invisible until a light pops at a tile
// boundary, so the binning maths gets a CPU twin, the crTrail precedent.

import { BITS, shaderModule } from './gpu.js';
import { rgba } from './color.js';
import { createGrainTexture } from './terrain3d.js';
import type { Mat4 } from './math3d.js';

export const LIGHT_FLOATS = 16;              // 4 vec4s per light
export const MAX_LIGHTS = 256;
export const CLUSTER_X = 16;
export const CLUSTER_Y = 8;
export const CLUSTER_Z = 24;
export const CLUSTER_COUNT = CLUSTER_X * CLUSTER_Y * CLUSTER_Z;
// Cluster capacity: overflow TRUNCATES a cluster's list, and neighbouring
// clusters keep DIFFERENT subsets — the froxel grid becomes visible as
// moving rectangular patches (seen on the lights3d plaza at 15, and again
// at 31 past ~110 lights). The 200-light plaza peaks at ~62 per cluster
// (with the clusterNear clamp below — without it, far froxels are so deep
// no cap holds), and grazing camera angles push higher: 127 leaves real
// headroom. Memory is still trivial (3072 clusters × 128 u32 = 1.5 MB);
// only genuinely crowded clusters pay the longer fragment loop.
export const MAX_PER_CLUSTER = 127;          // + 1 count word = 128 u32 stride
// The lighting uniform (LU) shared by the kernel and the mesh FS:
// view mat4 | shadowVP mat4 | params (lightCount, slices, near, far) |
// grid (tilesX, tilesY, screenW, screenH) | proj (tanHalfX, tanHalfY, 0, 0) |
// shadow (on, biasNdc, texelUv, normalOffWorld)
export const LU_FLOATS = 16 + 16 + 4 * 4;

export interface LightConfig {
  type?: 'point' | 'spot';
  x?: number; y?: number; z?: number;
  color?: string;
  /** Linear brightness multiplier (default 1). Falloff is INVERSE-SQUARE
   * (physical): brightness at distance d is ~intensity / d², so far throws
   * need BIG numbers — rule of thumb: intensity ≈ wanted-punch × d². A
   * lamp 14 units above the ground wants ~200, not ~10. */
  intensity?: number;
  /** Falloff radius in world units (default 8): the light reaches zero
   * here, and the cluster binning uses it — keep it honest. */
  radius?: number;
  /** Spot axis (spot only; any length; default straight down). */
  dir?: { x?: number; y?: number; z?: number };
  /** Spot cone half-angles in radians: full brightness inside `inner`,
   * zero past `outer` (defaults 0.35 / 0.55). */
  cone?: { inner?: number; outer?: number };
}

/** A live light — mutate everything per frame; kill() releases it. */
export class Light3d {
  type: 'point' | 'spot';
  x: number; y: number; z: number;
  color: string;
  intensity: number;
  radius: number;
  dir: { x: number; y: number; z: number };
  cone: { inner: number; outer: number };
  dead = false;

  constructor(c: LightConfig) {
    this.type = c.type ?? 'point';
    this.x = c.x ?? 0; this.y = c.y ?? 0; this.z = c.z ?? 0;
    this.color = c.color ?? '#ffffff';
    this.intensity = c.intensity ?? 1;
    this.radius = c.radius ?? 8;
    this.dir = { x: c.dir?.x ?? 0, y: c.dir?.y ?? -1, z: c.dir?.z ?? 0 };
    this.cone = { inner: c.cone?.inner ?? 0.35, outer: c.cone?.outer ?? 0.55 };
  }

  kill(): void { this.dead = true; }
}

// ---------------------------------------------------------------------------
// Pure froxel maths — the kernel's CPU twin.

export interface ClusterCfg {
  near: number; far: number;
  tanHalfX: number; tanHalfY: number;
}

/** Clustering uses its OWN near plane, clamped away from the camera near:
 * log slices from near 0.1 waste half the depth resolution inside 4.5
 * units of the camera, leaving the actual scene in a handful of HUGE
 * froxels that overflow any per-cluster cap. far/128 spreads the slices
 * over the visible range; slice 0 extends to the camera so fragments
 * closer than the clamp still shade (they read slice 0's list). */
export function clusterNear(near: number, far: number): number {
  return Math.max(near, far / 128);
}

/** View-space AABB of froxel (tx, ty, slice). View space: x right, y up,
 * camera looks down -z; tile (0,0) is the TOP-LEFT of the screen (fragment
 * coordinate convention — the FS derives its tile the same way). */
export function froxelBounds(tx: number, ty: number, slice: number, cfg: ClusterCfg): { min: [number, number, number]; max: [number, number, number] } {
  // Slice 0 reaches the CAMERA (zn = 0): fragments nearer than the cluster
  // near plane clamp to slice 0, so its bin must include their lights.
  const zn = slice === 0 ? 0 : cfg.near * Math.pow(cfg.far / cfg.near, slice / CLUSTER_Z);
  const zf = cfg.near * Math.pow(cfg.far / cfg.near, (slice + 1) / CLUSTER_Z);
  const x0 = (2 * tx / CLUSTER_X - 1) * cfg.tanHalfX;
  const x1 = (2 * (tx + 1) / CLUSTER_X - 1) * cfg.tanHalfX;
  const y0 = (1 - 2 * ty / CLUSTER_Y) * cfg.tanHalfY;         // top edge (+y)
  const y1 = (1 - 2 * (ty + 1) / CLUSTER_Y) * cfg.tanHalfY;   // bottom edge
  // Frustum sides scale linearly with depth — the AABB spans both planes.
  const xs = [x0 * zn, x0 * zf, x1 * zn, x1 * zf];
  const ys = [y0 * zn, y0 * zf, y1 * zn, y1 * zf];
  return {
    min: [Math.min(...xs), Math.min(...ys), -zf],
    max: [Math.max(...xs), Math.max(...ys), -zn],
  };
}

/** The kernel's slice mapping: view distance → logarithmic z slice. */
export function zSlice(viewDist: number, cfg: ClusterCfg): number {
  const s = Math.floor(Math.log(viewDist / cfg.near) / Math.log(cfg.far / cfg.near) * CLUSTER_Z);
  return Math.min(CLUSTER_Z - 1, Math.max(0, s));
}

/** CPU twin of the binning kernel: lights are (viewX, viewY, viewZ, radius)
 * quads. Returns per-cluster light-index lists (tests compare against the
 * same maths the kernel runs). */
export function binLightsCpu(lights: ReadonlyArray<[number, number, number, number]>, cfg: ClusterCfg): number[][] {
  const out: number[][] = [];
  for (let c = 0; c < CLUSTER_COUNT; c++) {
    const tx = c % CLUSTER_X;
    const ty = Math.floor(c / CLUSTER_X) % CLUSTER_Y;
    const slice = Math.floor(c / (CLUSTER_X * CLUSTER_Y));
    const b = froxelBounds(tx, ty, slice, cfg);
    const list: number[] = [];
    for (let i = 0; i < lights.length && list.length < MAX_PER_CLUSTER; i++) {
      const [lx, ly, lz, r] = lights[i];
      const cx = Math.max(b.min[0], Math.min(b.max[0], lx));
      const cy = Math.max(b.min[1], Math.min(b.max[1], ly));
      const cz = Math.max(b.min[2], Math.min(b.max[2], lz));
      const d2 = (lx - cx) ** 2 + (ly - cy) ** 2 + (lz - cz) ** 2;
      if (d2 <= r * r) list.push(i);
    }
    out.push(list);
  }
  return out;
}

/** Assemble the cluster-binning kernel (pure string work — dist-tested). */
export function buildClusterWGSL(): string {
  return /* wgsl */ `
struct LU {
  view: mat4x4f,
  shadowVP: mat4x4f,
  params: vec4f,      // lightCount, slices, near, far
  grid: vec4f,        // tilesX, tilesY, screenW, screenH
  proj: vec4f,        // tanHalfX, tanHalfY, 0, 0
  shadow: vec4f,      // on, biasNdc, texelUv, normalOffWorld
}
@group(0) @binding(0) var<uniform> lu: LU;
@group(0) @binding(1) var<storage, read> lights: array<vec4f>;   // 4 vec4 per light, VIEW space
@group(0) @binding(2) var<storage, read_write> clusters: array<u32>;

const TX = ${CLUSTER_X}u;
const TY = ${CLUSTER_Y}u;
const TZ = ${CLUSTER_Z}u;
const STRIDE = ${MAX_PER_CLUSTER + 1}u;

@compute @workgroup_size(64)
fn cs(@builtin(global_invocation_id) gid: vec3u) {
  let c = gid.x;
  if (c >= TX * TY * TZ) { return; }
  let tx = f32(c % TX);
  let ty = f32((c / TX) % TY);
  let slice = f32(c / (TX * TY));
  let near = lu.params.z;
  let far = lu.params.w;
  var zn = near * pow(far / near, slice / f32(TZ));
  if (slice < 0.5) { zn = 0.0; }   // slice 0 reaches the camera
  let zf = near * pow(far / near, (slice + 1.0) / f32(TZ));
  let x0 = (2.0 * tx / f32(TX) - 1.0) * lu.proj.x;
  let x1 = (2.0 * (tx + 1.0) / f32(TX) - 1.0) * lu.proj.x;
  let y0 = (1.0 - 2.0 * ty / f32(TY)) * lu.proj.y;
  let y1 = (1.0 - 2.0 * (ty + 1.0) / f32(TY)) * lu.proj.y;
  let bmin = vec3f(
    min(min(x0 * zn, x0 * zf), min(x1 * zn, x1 * zf)),
    min(min(y0 * zn, y0 * zf), min(y1 * zn, y1 * zf)),
    -zf,
  );
  let bmax = vec3f(
    max(max(x0 * zn, x0 * zf), max(x1 * zn, x1 * zf)),
    max(max(y0 * zn, y0 * zf), max(y1 * zn, y1 * zf)),
    -zn,
  );
  var n = 0u;
  let count = u32(lu.params.x);
  for (var i = 0u; i < count; i = i + 1u) {
    if (n >= STRIDE - 1u) { break; }
    let l = lights[i * 4u];                    // viewPos.xyz + radius
    let p = clamp(l.xyz, bmin, bmax);
    let d = l.xyz - p;
    if (dot(d, d) <= l.w * l.w) {
      clusters[c * STRIDE + 1u + n] = i;
      n = n + 1u;
    }
  }
  clusters[c * STRIDE] = n;
}
`;
}

/** The ACTIVATION pool: when more lights are registered than `max`, keep
 * the ones whose light SPHERES come closest to the camera — view-space
 * distance minus radius, so a big streetlamp beats a nearby candle it
 * would out-reach. Pure (dist-tested); order is preserved under the cap. */
export function selectLights(list: Light3d[], view: Mat4, max: number): Light3d[] {
  if (list.length <= max) return list;
  const scored = list.map((l) => {
    const vx = view[0] * l.x + view[4] * l.y + view[8] * l.z + view[12];
    const vy = view[1] * l.x + view[5] * l.y + view[9] * l.z + view[13];
    const vz = view[2] * l.x + view[6] * l.y + view[10] * l.z + view[14];
    return { l, k: Math.hypot(vx, vy, vz) - l.radius };
  });
  scored.sort((a, b) => a.k - b.k);
  scored.length = max;
  return scored.map((s) => s.l);
}

// ---------------------------------------------------------------------------
// The system: packing + compute + the group(1) bind for the mesh pipeline.

export class Lights3d {
  private list: Light3d[] = [];
  private lightData = new Float32Array(MAX_LIGHTS * LIGHT_FLOATS);
  private luData = new Float32Array(LU_FLOATS);

  private device!: GPUDevice;
  private pipeline!: GPUComputePipeline;
  /** The group(1) layout the MESH pipeline shares (world3d builds its
   * pipeline layout with this). */
  layout!: GPUBindGroupLayout;
  bind!: GPUBindGroup;
  private lu!: GPUBuffer;
  private lightsBuf!: GPUBuffer;
  private clustersBuf!: GPUBuffer;
  private computeBind!: GPUBindGroup;
  private sampler!: GPUSampler;
  private dummyShadow!: GPUTextureView;
  private shadowView: GPUTextureView | null = null;
  private causticSampler!: GPUSampler;
  private dummyCaustic!: GPUTextureView;
  private causticView: GPUTextureView | null = null;
  private grainView!: GPUTextureView;

  constructor(device: GPUDevice) {
    this.rebuild(device);
  }

  get count(): number {
    return this.list.filter((l) => !l.dead).length;
  }

  /** Lights actually uploaded + binned LAST frame (≤ MAX_LIGHTS — the
   * activation pool picks the nearest when more are registered). */
  activeCount = 0;

  light(config: LightConfig = {}): Light3d {
    const l = new Light3d(config);
    // No hard cap on REGISTRATION: a sprawling world registers every
    // lantern once and forgets about them — each frame the ACTIVATION pool
    // uploads the MAX_LIGHTS whose spheres come closest to the camera.
    this.list.push(l);
    return l;
  }

  /** Point the group(1) bind at the shadow map (world3d owns the texture;
   * null reverts to the 1×1 dummy). */
  setShadowMap(view: GPUTextureView | null): void {
    this.shadowView = view;
    this.makeBind();
  }

  /** Point the group(1) bind at the baked caustic pattern (underwater3d owns
   * the texture; null reverts to the 1×1 black dummy = no dapple). */
  setCaustic(view: GPUTextureView | null): void {
    this.causticView = view;
    this.makeBind();
  }

  /**
   * Per-frame: pack live lights into VIEW space, fill the shared LU uniform
   * (view/shadow matrices + cluster params), and encode the binning kernel.
   * Runs before the render passes (same encoder).
   */
  update(
    encoder: GPUCommandEncoder,
    view: Mat4, near: number, far: number,
    tanHalfX: number, tanHalfY: number,
    screenW: number, screenH: number,
    shadowVP: Mat4 | null, shadowBias: number, shadowTexel: number,
    shadowNormalOff = 0,
  ): void {
    this.list = this.list.filter((l) => !l.dead);
    near = clusterNear(near, far);
    const active = selectLights(this.list, view, MAX_LIGHTS);
    const n = active.length;
    this.activeCount = n;
    const d = this.lightData;
    for (let i = 0; i < n; i++) {
      const l = active[i];
      const o = i * LIGHT_FLOATS;
      // world → view (rigid): position via the full matrix, direction via
      // the rotation part.
      const vx = view[0] * l.x + view[4] * l.y + view[8] * l.z + view[12];
      const vy = view[1] * l.x + view[5] * l.y + view[9] * l.z + view[13];
      const vz = view[2] * l.x + view[6] * l.y + view[10] * l.z + view[14];
      const c = rgba(l.color);
      d[o] = vx; d[o + 1] = vy; d[o + 2] = vz; d[o + 3] = l.radius;
      d[o + 4] = c[0] * l.intensity; d[o + 5] = c[1] * l.intensity; d[o + 6] = c[2] * l.intensity;
      d[o + 7] = l.type === 'spot' ? 1 : 0;
      const dl = Math.hypot(l.dir.x, l.dir.y, l.dir.z) || 1;
      const wx = l.dir.x / dl, wy = l.dir.y / dl, wz = l.dir.z / dl;
      d[o + 8] = view[0] * wx + view[4] * wy + view[8] * wz;
      d[o + 9] = view[1] * wx + view[5] * wy + view[9] * wz;
      d[o + 10] = view[2] * wx + view[6] * wy + view[10] * wz;
      d[o + 11] = Math.cos(l.cone.outer);
      d[o + 12] = Math.cos(l.cone.inner);
      d[o + 13] = 0; d[o + 14] = 0; d[o + 15] = 0;
    }
    const u = this.luData;
    u.set(view, 0);
    if (shadowVP) u.set(shadowVP, 16);
    u[32] = n; u[33] = CLUSTER_Z; u[34] = near; u[35] = far;
    u[36] = CLUSTER_X; u[37] = CLUSTER_Y; u[38] = screenW; u[39] = screenH;
    u[40] = tanHalfX; u[41] = tanHalfY; u[42] = 0; u[43] = 0;
    u[44] = shadowVP ? 1 : 0; u[45] = shadowBias; u[46] = shadowTexel; u[47] = shadowNormalOff;
    this.device.queue.writeBuffer(this.lu, 0, u);
    if (n > 0) {
      this.device.queue.writeBuffer(this.lightsBuf, 0, d.buffer, 0, n * LIGHT_FLOATS * 4);
      const pass = encoder.beginComputePass();
      pass.setPipeline(this.pipeline);
      pass.setBindGroup(0, this.computeBind);
      pass.dispatchWorkgroups(Math.ceil(CLUSTER_COUNT / 64));
      pass.end();
    }
    // n == 0: the FS reads lightCount 0 and skips the loop — stale cluster
    // data is unreachable.
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    // group(1) for the MESH pipeline: LU + lights + clusters + shadow map +
    // comparison sampler.
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_FRAGMENT | BITS.STAGE_COMPUTE, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT | BITS.STAGE_COMPUTE, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, buffer: { type: 'read-only-storage' } },
        { binding: 3, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'depth' } },
        { binding: 4, visibility: BITS.STAGE_FRAGMENT, sampler: { type: 'comparison' } },
        // The baked underwater caustic pattern + its repeat/mipped sampler.
        // Only the MESH FS declares these; every other group(1) consumer
        // simply ignores the extra entries.
        { binding: 5, visibility: BITS.STAGE_FRAGMENT, texture: {} },
        { binding: 6, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
        // The baked close-range ground grain (terrain3d) — always present.
        { binding: 7, visibility: BITS.STAGE_FRAGMENT, texture: {} },
      ],
    });
    // The kernel writes clusters, so it gets its own layout (read_write).
    const computeLayout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_COMPUTE, buffer: { type: 'storage' } },
      ],
    });
    const module = shaderModule(device, buildClusterWGSL(), 'Lights3d cluster');
    this.pipeline = device.createComputePipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [computeLayout] }),
      compute: { module, entryPoint: 'cs' },
    });
    this.lu = device.createBuffer({ size: LU_FLOATS * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.lightsBuf = device.createBuffer({ size: MAX_LIGHTS * LIGHT_FLOATS * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.clustersBuf = device.createBuffer({ size: CLUSTER_COUNT * (MAX_PER_CLUSTER + 1) * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    this.sampler = device.createSampler({ compare: 'less-equal', magFilter: 'linear', minFilter: 'linear' });
    const dummy = device.createTexture({ size: { width: 1, height: 1 }, format: 'depth24plus', usage: BITS.TEXTURE_BINDING | BITS.RENDER_ATTACHMENT });
    this.dummyShadow = dummy.createView();
    this.shadowView = null;
    this.causticSampler = device.createSampler({
      addressModeU: 'repeat', addressModeV: 'repeat',
      magFilter: 'linear', minFilter: 'linear', mipmapFilter: 'linear',
    });
    const dummyC = device.createTexture({ size: { width: 1, height: 1 }, format: 'r8unorm', usage: BITS.TEXTURE_BINDING | 0x2 /* COPY_DST */ });
    device.queue.writeTexture({ texture: dummyC }, new Uint8Array([0]), {}, { width: 1, height: 1 });
    this.dummyCaustic = dummyC.createView();
    this.causticView = null;
    this.grainView = createGrainTexture(device).createView();
    this.computeBind = device.createBindGroup({
      layout: computeLayout,
      entries: [
        { binding: 0, resource: { buffer: this.lu } },
        { binding: 1, resource: { buffer: this.lightsBuf } },
        { binding: 2, resource: { buffer: this.clustersBuf } },
      ],
    });
    this.makeBind();
  }

  private makeBind(): void {
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.lu } },
        { binding: 1, resource: { buffer: this.lightsBuf } },
        { binding: 2, resource: { buffer: this.clustersBuf } },
        { binding: 3, resource: this.shadowView ?? this.dummyShadow },
        { binding: 4, resource: this.sampler },
        { binding: 5, resource: this.causticView ?? this.dummyCaustic },
        { binding: 6, resource: this.causticSampler },
        { binding: 7, resource: this.grainView },
      ],
    });
  }
}
