// GLB (glTF 2.0 Binary) parser — Phase 3 stages 2+3 of
// docs/webgpu-engine-v2-parity-plan.md. PURE data-in/data-out: an ArrayBuffer
// goes in, plain typed arrays + material/image records come out. No DOM, no
// GPU, no fetch, and NO runtime deps — the chunk reader is written by hand
// (a plan mandate). The loader/GPU upload layer lives elsewhere; keeping the
// parse pure means it runs headless under node:test against the real
// checked-in sample models.
//
// Output shape is renderer-ready, not glTF-shaped: every mesh primitive is
// expanded to a NON-INDEXED triangle soup at stride 8 (pos3 normal3 uv2).
// STATIC primitives get the owning node's WORLD transform baked in —
// positions moved by the full matrix, normals by the inverse-transpose
// upper-3×3 then renormalised (a plain rotate breaks under the non-uniform
// scales the sample set actually uses). Animated/skinned content is RETAINED
// instead: a primitive stays UNBAKED (verts as authored — node-local, or
// skin-space for skinned meshes) when it is skinned or when its node or any
// ancestor is targeted by an animation channel, and the node hierarchy,
// animation channels and skins come out on `rig` for the runtime to sample.
// Unbaked positions are still pushed through the static world matrix for the
// overall bounds so fitVerts keeps working.

// ---------------------------------------------------------------------------
// Public output types
// ---------------------------------------------------------------------------

export interface GlbMaterial {
  name: string;
  /** baseColorFactor rgba (default [1,1,1,1]). */
  color: [number, number, number, number];
  /** metallicFactor (default 1 per spec). */
  metallic: number;
  /** roughnessFactor (default 1). */
  rough: number;
  /** images[] index for baseColorTexture, if any. */
  colorImage?: number;
  /** metallicRoughness texture image index (glTF: g = rough, b = metallic
   * — MULTIPLIES the factors). DamagedHelmet-class models keep all their
   * material variation here. */
  mrImage?: number;
  /** images[] index for normalTexture, if any. */
  normalImage?: number;
  /** normalTexture.scale (default 1), only when normalImage present. */
  normalScale?: number;
  /** emissiveFactor if non-zero. */
  emissive?: [number, number, number];
}

export interface GlbImage {
  mimeType: string; // 'image/png' | 'image/jpeg'
  bytes: Uint8Array; // view into the BIN chunk (no copy needed)
}

export interface GlbPrimitiveOut {
  /** NON-INDEXED triangle soup, stride 8: pos(3) normal(3) uv(2). When
   * `baked`, the owning node's WORLD transform is applied to positions and
   * (inverse-transpose-rotated, renormalised) normals; otherwise verts are
   * as authored — node-local, or skin-space for skinned primitives. */
  verts: Float32Array;
  /** materials[] index or null. */
  material: number | null;
  /** Owning node index into rig.nodes (always set, even when rig is null). */
  node: number;
  /** skins[] index, or null when the primitive is not skinned. */
  skin: number | null;
  /** true = verts carry the world transform (the static fast path). */
  baked: boolean;
  /** 4 joint indices per vertex (into skins[skin].joints), expanded
   * non-indexed like verts. Only present when skinned. */
  joints?: Uint16Array;
  /** 4 weights per vertex, normalized to sum 1 (degenerate all-zero quads
   * become [1,0,0,0]). Only present when skinned. */
  weights?: Float32Array;
}

export interface GlbNodeOut {
  name: string;
  /** Parent node index, -1 for roots. */
  parent: number;
  /** Local TRS (matrix nodes are decomposed — glTF forbids skew so the
   * decomposition is exact). */
  t: [number, number, number];
  r: [number, number, number, number]; // quaternion x,y,z,w
  s: [number, number, number];
}

export interface GlbChannel {
  node: number;
  path: 'translation' | 'rotation' | 'scale';
  interpolation: 'LINEAR' | 'STEP' | 'CUBICSPLINE';
  times: Float32Array;
  /** Packed values: 3 floats per key (t/s) or 4 (rotation). For CUBICSPLINE
   * the raw inTangent/value/outTangent triplets are packed as authored (3×
   * the element count per key) — the runtime samples the middle element. */
  values: Float32Array;
}

export interface GlbAnimOut {
  name: string; // 'anim0', 'anim1'… when unnamed
  duration: number; // max end time across channels
  channels: GlbChannel[];
}

export interface GlbSkinOut {
  joints: number[]; // node indices
  inverseBind: Float32Array; // 16 floats per joint, column-major
}

export interface GlbRig {
  nodes: GlbNodeOut[];
  anims: GlbAnimOut[];
  skins: GlbSkinOut[];
}

export interface GlbData {
  primitives: GlbPrimitiveOut[];
  materials: GlbMaterial[];
  images: GlbImage[];
  bounds: { min: [number, number, number]; max: [number, number, number] };
  /** Node hierarchy + animations + skins — null when the file has neither
   * animations nor skins (everything baked, nothing to drive). */
  rig: GlbRig | null;
}

// ---------------------------------------------------------------------------
// Narrow glTF JSON shapes (only what we consume)
// ---------------------------------------------------------------------------

interface GltfBufferView {
  buffer: number;
  byteOffset?: number;
  byteLength: number;
  byteStride?: number;
}

interface GltfAccessor {
  bufferView?: number;
  byteOffset?: number;
  componentType: number;
  normalized?: boolean;
  count: number;
  type: string;
}

interface GltfPrimitive {
  attributes: Record<string, number>;
  indices?: number;
  material?: number;
  mode?: number;
}

interface GltfMesh {
  primitives: GltfPrimitive[];
}

interface GltfNode {
  name?: string;
  children?: number[];
  mesh?: number;
  skin?: number;
  matrix?: number[];
  translation?: number[];
  rotation?: number[];
  scale?: number[];
}

interface GltfAnimationSampler {
  input: number;
  output: number;
  interpolation?: string;
}

interface GltfAnimationChannel {
  sampler: number;
  target: { node?: number; path: string };
}

interface GltfAnimation {
  name?: string;
  samplers: GltfAnimationSampler[];
  channels: GltfAnimationChannel[];
}

interface GltfSkin {
  joints: number[];
  inverseBindMatrices?: number;
}

interface GltfScene {
  nodes?: number[];
}

interface GltfTextureInfo {
  index: number;
  scale?: number;
}

interface GltfPbr {
  baseColorFactor?: number[];
  metallicFactor?: number;
  roughnessFactor?: number;
  metallicRoughnessTexture?: { index: number };
  baseColorTexture?: GltfTextureInfo;
}

interface GltfMaterial {
  name?: string;
  pbrMetallicRoughness?: GltfPbr;
  normalTexture?: GltfTextureInfo;
  emissiveFactor?: number[];
  extensions?: Record<string, unknown>;
}

interface GltfTexture {
  source?: number;
}

interface GltfImage {
  uri?: string;
  mimeType?: string;
  bufferView?: number;
}

interface GltfDoc {
  scene?: number;
  scenes?: GltfScene[];
  nodes?: GltfNode[];
  meshes?: GltfMesh[];
  accessors?: GltfAccessor[];
  bufferViews?: GltfBufferView[];
  materials?: GltfMaterial[];
  textures?: GltfTexture[];
  images?: GltfImage[];
  animations?: GltfAnimation[];
  skins?: GltfSkin[];
}

// ---------------------------------------------------------------------------
// GLB container — hand-rolled chunk reader (plan mandate: no runtime deps)
// ---------------------------------------------------------------------------

const GLB_MAGIC = 0x46546c67; // 'glTF'
const CHUNK_JSON = 0x4e4f534a; // 'JSON'
const CHUNK_BIN = 0x004e4942; // 'BIN\0'

interface GlbChunks {
  json: GltfDoc;
  /** BIN chunk as a view into the source buffer (empty if absent). */
  bin: Uint8Array;
  binView: DataView;
}

function readChunks(buffer: ArrayBuffer): GlbChunks {
  if (buffer.byteLength < 12) {
    throw new Error(`GLB: truncated header — ${buffer.byteLength} bytes, need at least 12`);
  }
  const head = new DataView(buffer);
  const magic = head.getUint32(0, true);
  if (magic !== GLB_MAGIC) {
    throw new Error(`GLB: bad magic 0x${magic.toString(16)} — expected 0x46546c67 ('glTF')`);
  }
  const version = head.getUint32(4, true);
  if (version !== 2) {
    throw new Error(`GLB: unsupported version ${version} — only glTF 2.0 binary is supported`);
  }
  const total = Math.min(head.getUint32(8, true), buffer.byteLength);

  let json: GltfDoc | null = null;
  let bin: Uint8Array | null = null;
  let binView: DataView | null = null;

  let offset = 12;
  while (offset + 8 <= total) {
    const chunkLen = head.getUint32(offset, true);
    const chunkType = head.getUint32(offset + 4, true);
    const dataStart = offset + 8;
    if (dataStart + chunkLen > buffer.byteLength) {
      throw new Error('GLB: chunk overruns file — declared length exceeds buffer');
    }
    if (chunkType === CHUNK_JSON && json === null) {
      const text = new TextDecoder().decode(new Uint8Array(buffer, dataStart, chunkLen));
      json = JSON.parse(text) as GltfDoc;
    } else if (chunkType === CHUNK_BIN && bin === null) {
      bin = new Uint8Array(buffer, dataStart, chunkLen);
      binView = new DataView(buffer, dataStart, chunkLen);
    }
    // Unknown chunk types are skipped per spec.
    offset = dataStart + chunkLen;
  }

  if (json === null) {
    throw new Error('GLB: missing JSON chunk (0x4E4F534A)');
  }
  if (bin === null) {
    // Legal per spec (all-embedded-uri assets), but our accessor reads will
    // throw a descriptive error if anything actually references buffer 0.
    bin = new Uint8Array(0);
    binView = new DataView(new ArrayBuffer(0));
  }
  return { json, bin, binView: binView as DataView };
}

// ---------------------------------------------------------------------------
// Accessor reads — respects byteStride (interleaved buffers), byteOffsets,
// and normalized u8/u16 → float (TEXCOORD variants)
// ---------------------------------------------------------------------------

const F32 = 5126;
const U32 = 5125;
const U16 = 5123;
const U8 = 5121;

const COMPONENT_BYTES: Record<number, number> = { [U8]: 1, [U16]: 2, [U32]: 4, [F32]: 4 };
const TYPE_COMPONENTS: Record<string, number> = { SCALAR: 1, VEC2: 2, VEC3: 3, VEC4: 4, MAT4: 16 };

/** Read accessor `index` as flat floats (count × components). */
function readAccessorF32(doc: GltfDoc, binView: DataView, index: number): Float32Array {
  const acc = doc.accessors?.[index];
  if (!acc) throw new Error(`GLB: accessor ${index} missing`);
  const comps = TYPE_COMPONENTS[acc.type];
  if (!comps) throw new Error(`GLB: accessor ${index} has unsupported type '${acc.type}'`);
  const compBytes = COMPONENT_BYTES[acc.componentType];
  if (!compBytes) {
    throw new Error(`GLB: accessor ${index} has unsupported componentType ${acc.componentType}`);
  }
  const out = new Float32Array(acc.count * comps);
  if (acc.bufferView === undefined) return out; // spec: zero-filled

  const bv = doc.bufferViews?.[acc.bufferView];
  if (!bv) throw new Error(`GLB: bufferView ${acc.bufferView} missing`);
  if (binView.byteLength === 0) {
    throw new Error('GLB: accessor references the BIN chunk but the file has none');
  }
  const stride = bv.byteStride ?? comps * compBytes;
  const base = (bv.byteOffset ?? 0) + (acc.byteOffset ?? 0);
  const type = acc.componentType;
  const normalized = acc.normalized === true;

  for (let i = 0; i < acc.count; i++) {
    const row = base + i * stride;
    for (let c = 0; c < comps; c++) {
      const at = row + c * compBytes;
      let v: number;
      if (type === F32) v = binView.getFloat32(at, true);
      else if (type === U32) v = binView.getUint32(at, true);
      else if (type === U16) v = normalized ? binView.getUint16(at, true) / 65535 : binView.getUint16(at, true);
      else v = normalized ? binView.getUint8(at) / 255 : binView.getUint8(at);
      out[i * comps + c] = v;
    }
  }
  return out;
}

/** Read a SCALAR index accessor as u32s. */
function readIndices(doc: GltfDoc, binView: DataView, index: number): Uint32Array {
  const acc = doc.accessors?.[index];
  if (!acc) throw new Error(`GLB: index accessor ${index} missing`);
  const compBytes = COMPONENT_BYTES[acc.componentType];
  if (!compBytes || acc.componentType === F32) {
    throw new Error(`GLB: index accessor ${index} has unsupported componentType ${acc.componentType}`);
  }
  const out = new Uint32Array(acc.count);
  if (acc.bufferView === undefined) return out;
  const bv = doc.bufferViews?.[acc.bufferView];
  if (!bv) throw new Error(`GLB: bufferView ${acc.bufferView} missing`);
  const stride = bv.byteStride ?? compBytes;
  const base = (bv.byteOffset ?? 0) + (acc.byteOffset ?? 0);
  const type = acc.componentType;
  for (let i = 0; i < acc.count; i++) {
    const at = base + i * stride;
    out[i] = type === U32 ? binView.getUint32(at, true) : type === U16 ? binView.getUint16(at, true) : binView.getUint8(at);
  }
  return out;
}

// ---------------------------------------------------------------------------
// Minimal column-major mat4 helpers (local — the parser stays dependency-free)
// ---------------------------------------------------------------------------

type Mat4 = Float32Array; // 16 floats, column-major

function mat4Identity(): Mat4 {
  const m = new Float32Array(16);
  m[0] = m[5] = m[10] = m[15] = 1;
  return m;
}

/** out = a · b (column-major). */
function mat4Multiply(a: Mat4, b: Mat4): Mat4 {
  const out = new Float32Array(16);
  for (let c = 0; c < 4; c++) {
    for (let r = 0; r < 4; r++) {
      out[c * 4 + r] =
        a[r] * b[c * 4] + a[4 + r] * b[c * 4 + 1] + a[8 + r] * b[c * 4 + 2] + a[12 + r] * b[c * 4 + 3];
    }
  }
  return out;
}

/** Compose T·R·S from glTF node fields (quaternion is [x,y,z,w]). */
function mat4FromTrs(t: number[] | undefined, r: number[] | undefined, s: number[] | undefined): Mat4 {
  const [tx, ty, tz] = t ?? [0, 0, 0];
  const [qx, qy, qz, qw] = r ?? [0, 0, 0, 1];
  const [sx, sy, sz] = s ?? [1, 1, 1];

  // Rotation matrix from the (assumed unit) quaternion.
  const x2 = qx + qx, y2 = qy + qy, z2 = qz + qz;
  const xx = qx * x2, xy = qx * y2, xz = qx * z2;
  const yy = qy * y2, yz = qy * z2, zz = qz * z2;
  const wx = qw * x2, wy = qw * y2, wz = qw * z2;

  const m = new Float32Array(16);
  m[0] = (1 - (yy + zz)) * sx;
  m[1] = (xy + wz) * sx;
  m[2] = (xz - wy) * sx;
  m[4] = (xy - wz) * sy;
  m[5] = (1 - (xx + zz)) * sy;
  m[6] = (yz + wx) * sy;
  m[8] = (xz + wy) * sz;
  m[9] = (yz - wx) * sz;
  m[10] = (1 - (xx + yy)) * sz;
  m[12] = tx;
  m[13] = ty;
  m[14] = tz;
  m[15] = 1;
  return m;
}

/** Inverse-transpose of the upper 3×3, returned ROW-major (9 floats) so that
 * n'ᵣ = Σ N[r*3+c]·n_c. Falls back to the raw upper 3×3 if degenerate. */
function normalMatrix(m: Mat4): Float32Array {
  const a00 = m[0], a10 = m[1], a20 = m[2];
  const a01 = m[4], a11 = m[5], a21 = m[6];
  const a02 = m[8], a12 = m[9], a22 = m[10];

  // Cofactor matrix; inverse-transpose = cofactors / det.
  const c00 = a11 * a22 - a12 * a21;
  const c01 = -(a10 * a22 - a12 * a20);
  const c02 = a10 * a21 - a11 * a20;
  const c10 = -(a01 * a22 - a02 * a21);
  const c11 = a00 * a22 - a02 * a20;
  const c12 = -(a00 * a21 - a01 * a20);
  const c20 = a01 * a12 - a02 * a11;
  const c21 = -(a00 * a12 - a02 * a10);
  const c22 = a00 * a11 - a01 * a10;

  const det = a00 * c00 + a01 * c01 + a02 * c02;
  const out = new Float32Array(9);
  if (Math.abs(det) < 1e-12) {
    // Degenerate scale — best effort: rotate by the raw 3×3 (renormalised later).
    out[0] = a00; out[1] = a01; out[2] = a02;
    out[3] = a10; out[4] = a11; out[5] = a12;
    out[6] = a20; out[7] = a21; out[8] = a22;
    return out;
  }
  const inv = 1 / det;
  out[0] = c00 * inv; out[1] = c01 * inv; out[2] = c02 * inv;
  out[3] = c10 * inv; out[4] = c11 * inv; out[5] = c12 * inv;
  out[6] = c20 * inv; out[7] = c21 * inv; out[8] = c22 * inv;
  return out;
}

/** Decompose a column-major TRS matrix into t / quaternion / s. glTF forbids
 * skew in node matrices, so this is exact for any legal file. A mirrored
 * matrix (negative determinant) folds the flip into sx. */
function decomposeTrs(m: Mat4): { t: [number, number, number]; r: [number, number, number, number]; s: [number, number, number] } {
  const t: [number, number, number] = [m[12], m[13], m[14]];

  let sx = Math.hypot(m[0], m[1], m[2]);
  const sy = Math.hypot(m[4], m[5], m[6]);
  const sz = Math.hypot(m[8], m[9], m[10]);
  const det =
    m[0] * (m[5] * m[10] - m[6] * m[9]) -
    m[4] * (m[1] * m[10] - m[2] * m[9]) +
    m[8] * (m[1] * m[6] - m[2] * m[5]);
  if (det < 0) sx = -sx;

  const ix = sx !== 0 ? 1 / sx : 0;
  const iy = sy !== 0 ? 1 / sy : 0;
  const iz = sz !== 0 ? 1 / sz : 0;
  // Pure rotation matrix (column-major 3×3).
  const r00 = m[0] * ix, r10 = m[1] * ix, r20 = m[2] * ix;
  const r01 = m[4] * iy, r11 = m[5] * iy, r21 = m[6] * iy;
  const r02 = m[8] * iz, r12 = m[9] * iz, r22 = m[10] * iz;

  // Shepperd's method — pick the largest diagonal term for stability.
  let qx: number, qy: number, qz: number, qw: number;
  const trace = r00 + r11 + r22;
  if (trace > 0) {
    const s = Math.sqrt(trace + 1) * 2;
    qw = 0.25 * s;
    qx = (r21 - r12) / s;
    qy = (r02 - r20) / s;
    qz = (r10 - r01) / s;
  } else if (r00 > r11 && r00 > r22) {
    const s = Math.sqrt(1 + r00 - r11 - r22) * 2;
    qw = (r21 - r12) / s;
    qx = 0.25 * s;
    qy = (r01 + r10) / s;
    qz = (r02 + r20) / s;
  } else if (r11 > r22) {
    const s = Math.sqrt(1 + r11 - r00 - r22) * 2;
    qw = (r02 - r20) / s;
    qx = (r01 + r10) / s;
    qy = 0.25 * s;
    qz = (r12 + r21) / s;
  } else {
    const s = Math.sqrt(1 + r22 - r00 - r11) * 2;
    qw = (r10 - r01) / s;
    qx = (r02 + r20) / s;
    qy = (r12 + r21) / s;
    qz = 0.25 * s;
  }

  return { t, r: [qx, qy, qz, qw], s: [sx, sy, sz] };
}

// ---------------------------------------------------------------------------
// Rig — node hierarchy, animation channels, skins (retained for the runtime)
// ---------------------------------------------------------------------------

function parseNodes(nodes: GltfNode[]): GlbNodeOut[] {
  const parents = new Int32Array(nodes.length).fill(-1);
  for (let i = 0; i < nodes.length; i++) {
    const children = nodes[i].children;
    if (children) {
      for (let c = 0; c < children.length; c++) parents[children[c]] = i;
    }
  }
  const out: GlbNodeOut[] = [];
  for (let i = 0; i < nodes.length; i++) {
    const node = nodes[i];
    if (node.matrix && node.matrix.length === 16) {
      const { t, r, s } = decomposeTrs(Float32Array.from(node.matrix));
      out.push({ name: node.name ?? `node${i}`, parent: parents[i], t, r, s });
      continue;
    }
    const [tx, ty, tz] = node.translation ?? [0, 0, 0];
    const [qx, qy, qz, qw] = node.rotation ?? [0, 0, 0, 1];
    const [sx, sy, sz] = node.scale ?? [1, 1, 1];
    out.push({
      name: node.name ?? `node${i}`,
      parent: parents[i],
      t: [tx, ty, tz],
      r: [qx, qy, qz, qw],
      s: [sx, sy, sz],
    });
  }
  return out;
}

function parseAnimations(doc: GltfDoc, binView: DataView): GlbAnimOut[] {
  const out: GlbAnimOut[] = [];
  const src = doc.animations ?? [];
  for (let i = 0; i < src.length; i++) {
    const anim = src[i];
    const channels: GlbChannel[] = [];
    let duration = 0;
    for (let c = 0; c < anim.channels.length; c++) {
      const ch = anim.channels[c];
      const path = ch.target.path;
      // Morph target 'weights' channels are not supported — skipped, the rest
      // of the animation still plays.
      if (path !== 'translation' && path !== 'rotation' && path !== 'scale') continue;
      if (ch.target.node === undefined) continue;
      const sampler = anim.samplers[ch.sampler];
      if (!sampler) continue;
      if (path === 'rotation') {
        const outAcc = doc.accessors?.[sampler.output];
        if (outAcc && outAcc.componentType !== F32) {
          throw new Error(
            `GLB: animation rotation output accessor ${sampler.output} has componentType ${outAcc.componentType} — only f32 rotations are supported (normalized integer quaternions are not)`,
          );
        }
      }
      const times = readAccessorF32(doc, binView, sampler.input);
      const values = readAccessorF32(doc, binView, sampler.output);
      const raw = sampler.interpolation;
      const interpolation: GlbChannel['interpolation'] =
        raw === 'STEP' ? 'STEP' : raw === 'CUBICSPLINE' ? 'CUBICSPLINE' : 'LINEAR';
      // Duration straight from the data — input accessor `max` is optional.
      if (times.length > 0 && times[times.length - 1] > duration) duration = times[times.length - 1];
      channels.push({ node: ch.target.node, path, interpolation, times, values });
    }
    out.push({ name: anim.name ?? `anim${i}`, duration, channels });
  }
  return out;
}

function parseSkins(doc: GltfDoc, binView: DataView): GlbSkinOut[] {
  const out: GlbSkinOut[] = [];
  const src = doc.skins ?? [];
  for (let i = 0; i < src.length; i++) {
    const skin = src[i];
    const joints = skin.joints ?? [];
    let inverseBind: Float32Array;
    if (skin.inverseBindMatrices !== undefined) {
      inverseBind = readAccessorF32(doc, binView, skin.inverseBindMatrices);
    } else {
      // Spec default: identity inverse-bind for every joint.
      inverseBind = new Float32Array(joints.length * 16);
      for (let j = 0; j < joints.length; j++) {
        const o = j * 16;
        inverseBind[o] = inverseBind[o + 5] = inverseBind[o + 10] = inverseBind[o + 15] = 1;
      }
    }
    out.push({ joints: joints.slice(), inverseBind });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Materials + images
// ---------------------------------------------------------------------------

function textureToImage(doc: GltfDoc, textureIndex: number): number | undefined {
  const source = doc.textures?.[textureIndex]?.source;
  if (source === undefined || !doc.images?.[source]) return undefined;
  return source;
}

function parseMaterials(doc: GltfDoc): GlbMaterial[] {
  const out: GlbMaterial[] = [];
  const src = doc.materials ?? [];
  for (let i = 0; i < src.length; i++) {
    const m = src[i];
    const mat: GlbMaterial = {
      name: m.name ?? `material${i}`,
      color: [1, 1, 1, 1],
      metallic: 1,
      rough: 1,
    };
    const pbr = m.pbrMetallicRoughness;
    if (pbr) {
      const c = pbr.baseColorFactor;
      if (c && c.length >= 4) mat.color = [c[0], c[1], c[2], c[3]];
      if (pbr.metallicFactor !== undefined) mat.metallic = pbr.metallicFactor;
      if (pbr.roughnessFactor !== undefined) mat.rough = pbr.roughnessFactor;
      if (pbr.baseColorTexture) {
        const img = textureToImage(doc, pbr.baseColorTexture.index);
        if (img !== undefined) mat.colorImage = img;
      }
      if (pbr.metallicRoughnessTexture) {
        const img = textureToImage(doc, pbr.metallicRoughnessTexture.index);
        if (img !== undefined) mat.mrImage = img;
      }
    } else if (m.extensions && 'KHR_materials_pbrSpecularGlossiness' in m.extensions) {
      // Spec-gloss-only material: neutral diffuse fallback (non-metal).
      mat.metallic = 0;
    }
    if (m.normalTexture) {
      const img = textureToImage(doc, m.normalTexture.index);
      if (img !== undefined) {
        mat.normalImage = img;
        mat.normalScale = m.normalTexture.scale ?? 1;
      }
    }
    const e = m.emissiveFactor;
    if (e && e.length >= 3 && (e[0] !== 0 || e[1] !== 0 || e[2] !== 0)) {
      mat.emissive = [e[0], e[1], e[2]];
    }
    out.push(mat);
  }
  return out;
}

function parseImages(doc: GltfDoc, bin: Uint8Array): GlbImage[] {
  const out: GlbImage[] = [];
  const src = doc.images ?? [];
  for (let i = 0; i < src.length; i++) {
    const img = src[i];
    const bv = img.bufferView !== undefined ? doc.bufferViews?.[img.bufferView] : undefined;
    if (!bv || img.uri !== undefined) {
      // uri-backed (or broken) image: keep the slot so material indices stay
      // consistent, but mark it unsupported.
      out.push({ mimeType: 'unsupported/uri', bytes: new Uint8Array(0) });
      continue;
    }
    out.push({
      mimeType: img.mimeType ?? 'image/png',
      bytes: bin.subarray(bv.byteOffset ?? 0, (bv.byteOffset ?? 0) + bv.byteLength),
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Geometry — expand every TRIANGLES primitive to non-indexed soup. Baked
// primitives come out in world space; unbaked (animated/skinned) keep their
// authored coordinates and only pass through the world matrix for bounds.
// ---------------------------------------------------------------------------

const TRIANGLES = 4;

function expandPrimitive(
  doc: GltfDoc,
  binView: DataView,
  prim: GltfPrimitive,
  world: Mat4,
  bounds: { min: [number, number, number]; max: [number, number, number] },
  nodeIndex: number,
  skinIndex: number | null,
  baked: boolean,
): GlbPrimitiveOut | null {
  if ((prim.mode ?? TRIANGLES) !== TRIANGLES) return null;
  const posIndex = prim.attributes['POSITION'];
  if (posIndex === undefined) return null;

  const pos = readAccessorF32(doc, binView, posIndex);
  const posCount = (pos.length / 3) | 0;
  const normalIndex = prim.attributes['NORMAL'];
  const nrm = normalIndex !== undefined ? readAccessorF32(doc, binView, normalIndex) : null;
  const uvIndex = prim.attributes['TEXCOORD_0'];
  const uv = uvIndex !== undefined ? readAccessorF32(doc, binView, uvIndex) : null;
  const idx = prim.indices !== undefined ? readIndices(doc, binView, prim.indices) : null;
  const jointsIndex = prim.attributes['JOINTS_0'];
  const weightsIndex = prim.attributes['WEIGHTS_0'];
  const skinned = skinIndex !== null && jointsIndex !== undefined && weightsIndex !== undefined;
  const srcJoints = skinned ? readAccessorF32(doc, binView, jointsIndex) : null;
  const srcWeights = skinned ? readAccessorF32(doc, binView, weightsIndex) : null;

  const count = idx ? idx.length : posCount;
  const verts = new Float32Array(count * 8);
  const nm = normalMatrix(world);
  const m0 = world[0], m1 = world[1], m2 = world[2];
  const m4 = world[4], m5 = world[5], m6 = world[6];
  const m8 = world[8], m9 = world[9], m10 = world[10];
  const m12 = world[12], m13 = world[13], m14 = world[14];
  const { min, max } = bounds;
  const joints = srcJoints ? new Uint16Array(count * 4) : null;
  const weights = srcWeights ? new Float32Array(count * 4) : null;

  for (let k = 0; k < count; k++) {
    const s = idx ? idx[k] : k;
    const px = pos[s * 3], py = pos[s * 3 + 1], pz = pos[s * 3 + 2];
    // World-space position: written to verts when baked, and ALWAYS fed to
    // the bounds so fitVerts sees a meaningful static pose either way.
    const wx = m0 * px + m4 * py + m8 * pz + m12;
    const wy = m1 * px + m5 * py + m9 * pz + m13;
    const wz = m2 * px + m6 * py + m10 * pz + m14;
    const o = k * 8;
    if (baked) {
      verts[o] = wx;
      verts[o + 1] = wy;
      verts[o + 2] = wz;
    } else {
      verts[o] = px;
      verts[o + 1] = py;
      verts[o + 2] = pz;
    }
    if (wx < min[0]) min[0] = wx;
    if (wy < min[1]) min[1] = wy;
    if (wz < min[2]) min[2] = wz;
    if (wx > max[0]) max[0] = wx;
    if (wy > max[1]) max[1] = wy;
    if (wz > max[2]) max[2] = wz;

    if (nrm) {
      const nx = nrm[s * 3], ny = nrm[s * 3 + 1], nz = nrm[s * 3 + 2];
      let tx: number, ty: number, tz: number;
      if (baked) {
        tx = nm[0] * nx + nm[1] * ny + nm[2] * nz;
        ty = nm[3] * nx + nm[4] * ny + nm[5] * nz;
        tz = nm[6] * nx + nm[7] * ny + nm[8] * nz;
      } else {
        tx = nx; ty = ny; tz = nz;
      }
      const len = Math.sqrt(tx * tx + ty * ty + tz * tz);
      if (len > 1e-12) {
        const inv = 1 / len;
        tx *= inv; ty *= inv; tz *= inv;
      }
      verts[o + 3] = tx;
      verts[o + 4] = ty;
      verts[o + 5] = tz;
    }
    if (uv) {
      // glTF uv origin is top-left and our sampling is top-down: use AS-IS.
      verts[o + 6] = uv[s * 2];
      verts[o + 7] = uv[s * 2 + 1];
    }

    if (joints && weights && srcJoints && srcWeights) {
      const j = k * 4;
      joints[j] = srcJoints[s * 4];
      joints[j + 1] = srcJoints[s * 4 + 1];
      joints[j + 2] = srcJoints[s * 4 + 2];
      joints[j + 3] = srcJoints[s * 4 + 3];
      const w0 = srcWeights[s * 4], w1 = srcWeights[s * 4 + 1];
      const w2 = srcWeights[s * 4 + 2], w3 = srcWeights[s * 4 + 3];
      const sum = w0 + w1 + w2 + w3;
      if (sum > 1e-6) {
        const inv = 1 / sum;
        weights[j] = w0 * inv;
        weights[j + 1] = w1 * inv;
        weights[j + 2] = w2 * inv;
        weights[j + 3] = w3 * inv;
      } else {
        // Degenerate all-zero quad: bind fully to the first joint.
        weights[j] = 1;
        weights[j + 1] = 0;
        weights[j + 2] = 0;
        weights[j + 3] = 0;
      }
    }
  }

  if (!nrm) {
    // FLAT normals per triangle, computed from the expanded positions in
    // whichever space the verts came out in (world when baked — so
    // non-uniform scale is handled for free — authored space otherwise).
    const tris = (count / 3) | 0;
    for (let t = 0; t < tris; t++) {
      const a = t * 24, b = a + 8, c = a + 16;
      const e1x = verts[b] - verts[a], e1y = verts[b + 1] - verts[a + 1], e1z = verts[b + 2] - verts[a + 2];
      const e2x = verts[c] - verts[a], e2y = verts[c + 1] - verts[a + 1], e2z = verts[c + 2] - verts[a + 2];
      let nx = e1y * e2z - e1z * e2y;
      let ny = e1z * e2x - e1x * e2z;
      let nz = e1x * e2y - e1y * e2x;
      const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
      if (len > 1e-12) {
        const inv = 1 / len;
        nx *= inv; ny *= inv; nz *= inv;
      } else {
        nx = 0; ny = 0; nz = 1;
      }
      verts[a + 3] = nx; verts[a + 4] = ny; verts[a + 5] = nz;
      verts[b + 3] = nx; verts[b + 4] = ny; verts[b + 5] = nz;
      verts[c + 3] = nx; verts[c + 4] = ny; verts[c + 5] = nz;
    }
  }

  const out: GlbPrimitiveOut = {
    verts,
    material: prim.material ?? null,
    node: nodeIndex,
    skin: skinned ? skinIndex : null,
    baked,
  };
  if (joints && weights) {
    out.joints = joints;
    out.weights = weights;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

export function parseGlb(buffer: ArrayBuffer): GlbData {
  const { json: doc, bin, binView } = readChunks(buffer);
  const nodes = doc.nodes ?? [];

  // Rig first — the bake rule below needs the animated-node set. A node is
  // targeted when ANY channel of ANY animation drives it.
  const anims = parseAnimations(doc, binView);
  const skins = parseSkins(doc, binView);
  const animated = new Set<number>();
  for (let a = 0; a < anims.length; a++) {
    const channels = anims[a].channels;
    for (let c = 0; c < channels.length; c++) animated.add(channels[c].node);
  }

  const primitives: GlbPrimitiveOut[] = [];
  const bounds = {
    min: [Infinity, Infinity, Infinity] as [number, number, number],
    max: [-Infinity, -Infinity, -Infinity] as [number, number, number],
  };

  // Recursive scene walk, accumulating parent·child world matrices. Verts
  // are BAKED with the world transform unless the primitive is skinned or
  // its node (or any ancestor) is animated — those stay authored-space and
  // the world matrix only feeds the bounds.
  const walk = (index: number, parent: Mat4, ancestorAnimated: boolean): void => {
    const node = nodes[index];
    if (!node) return;
    const local = node.matrix && node.matrix.length === 16
      ? Float32Array.from(node.matrix)
      : mat4FromTrs(node.translation, node.rotation, node.scale);
    const world = mat4Multiply(parent, local);
    const nodeAnimated = ancestorAnimated || animated.has(index);
    if (node.mesh !== undefined) {
      const mesh = doc.meshes?.[node.mesh];
      if (mesh) {
        const skinIndex = node.skin !== undefined && skins[node.skin] ? node.skin : null;
        const baked = skinIndex === null && !nodeAnimated;
        for (let p = 0; p < mesh.primitives.length; p++) {
          const out = expandPrimitive(doc, binView, mesh.primitives[p], world, bounds, index, skinIndex, baked);
          if (out) primitives.push(out);
        }
      }
    }
    if (node.children) {
      for (let c = 0; c < node.children.length; c++) walk(node.children[c], world, nodeAnimated);
    }
  };

  const scene = doc.scenes?.[doc.scene ?? 0];
  const roots = scene?.nodes ?? [];
  const identity = mat4Identity();
  for (let i = 0; i < roots.length; i++) walk(roots[i], identity, false);

  if (!Number.isFinite(bounds.min[0])) {
    bounds.min = [0, 0, 0];
    bounds.max = [0, 0, 0];
  }

  const rig: GlbRig | null =
    anims.length > 0 || skins.length > 0 ? { nodes: parseNodes(nodes), anims, skins } : null;

  return {
    primitives,
    materials: parseMaterials(doc),
    images: parseImages(doc, bin),
    bounds,
    rig,
  };
}
