// TERRAIN — the heightfield floor of the RICH ENVIRONMENTS kit (E1 of the
// environments plan). Everything else in the kit stands on this: water laps
// against its shores, foliage scatters over it, karts and boards ride
// `heightAt`, snow carving mutates it.
//
// Doctrine (docs/webgpu-engine-v2-environments-plan.md):
//   - MECHANICS BEFORE ASSETS: with zero textures the terrain still looks
//     good — a seeded-noise heightfield coloured by height/slope BANDS baked
//     into one colormap canvas (the standalone-texture path models use).
//   - CPU REPLICA IS THE CONTRACT: `heightAt` interpolates the SAME
//     triangles the GPU rasterises (quad diagonal and all), so a wheel
//     placed at heightAt(x, z) sits exactly on the rendered ground.
//   - Chunked `static: true` meshes → the GPU-cull path handles the draw
//     side with no special casing.
//
// Everything in this file is pure (no GPU, no DOM) and dist-tested; the
// canvas/texture/mesh plumbing lives in world3d.terrain().

import { rgba } from './color.js';
import { BITS } from './gpu.js';
import { noisePerm, perlin2, fbm2 } from './noise.js';

// ── Seeded noise ────────────────────────────────────────────────────────────
// The gradient-noise field comes from noise.ts (perlin2/fbm2/noisePerm — the
// same seeded, DOM-free machinery the noise textures use). Only a cheap
// integer hash is added here, for per-texel colormap grain.

/** Deterministic integer-lattice hash → [0, 1). Same (ix, iz, seed) is the
 * same value on every machine — terrain is reproducible by seed. */
export function hash2(ix: number, iz: number, seed: number): number {
  let h = Math.imul(ix, 374761393) ^ Math.imul(iz, 668265263) ^ Math.imul(seed | 0, 1274126177);
  h = Math.imul(h ^ (h >>> 13), 1103515245);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const smoothstep = (e0: number, e1: number, x: number): number => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

// ── Shapes: world (x, z) → normalised height [0, 1] ────────────────────────

export type TerrainShape = 'island' | 'hills' | 'mountains' | 'dunes' | 'flat'
  | ((x: number, z: number) => number);

function shapeFn(shape: TerrainShape, seed: number, size: number, featureSize?: number): (x: number, z: number) => number {
  if (typeof shape === 'function') return shape;
  const perm = noisePerm(seed);
  // SCALE SENSE (Rich, on E1: "you feel like God looking down on earth"):
  // landform frequency is set by featureSize in WORLD UNITS, not by the
  // terrain size — otherwise a bigger terrain is just a ZOOMED-IN small one
  // and nothing gains scale. Default keeps ~3 features per side.
  const fs = featureSize ?? size / 3;
  const f = 1 / fs;
  switch (shape) {
    case 'flat':
      return () => 0;
    case 'hills':
      return (x, z) => {
        const h = 0.5 + 0.5 * fbm2(x * f, z * f, perm, { octaves: 5 });
        return Math.min(1, Math.max(0, h)) ** 1.3;
      };
    case 'mountains':
      return (x, z) => {
        // Ridged fbm: fold each octave over its zero crossing → sharp crests.
        let sum = 0, amp = 1, norm = 0, fx = x * f, fz = z * f;
        for (let o = 0; o < 5; o++) {
          sum += (1 - Math.abs(perlin2(fx, fz, perm))) * amp;
          norm += amp; amp *= 0.5; fx *= 2.1; fz *= 2.1;
        }
        return Math.min(1, Math.max(0, sum / norm)) ** 1.9;
      };
    case 'dunes':
      return (x, z) => {
        // Wind-aligned crests, domain-warped so rows wander; asymmetric
        // profile (long windward slope, short slip face).
        const warp = fbm2(x * f * 2.5, z * f * 2.5, perm, { octaves: 3 }) * fs * 0.15;
        const d = ((x * 0.9 + z * 0.35 + warp) * 2.33) / fs;
        const fr = d - Math.floor(d);
        const profile = fr < 0.72 ? fr / 0.72 : (1 - fr) / 0.28;
        return 0.08 + 0.3 * profile + 0.12 * (0.5 + 0.5 * fbm2(x * f, z * f, perm, { octaves: 3 }));
      };
    case 'island':
    default:
      return (x, z) => {
        const base = 0.5 + 0.5 * fbm2(x * f, z * f, perm, { octaves: 5 });
        const r = Math.hypot(x, z) / (size * 0.5);
        const fall = 1 - smoothstep(0.45, 0.95, r);
        return Math.min(1, Math.max(0, base * fall)) ** 1.15;
      };
  }
}

// ── The heightfield ─────────────────────────────────────────────────────────

export interface TerrainBand {
  /** Normalised height [0, 1] this colour is centred on (relative to `height`). */
  h: number;
  color: string;
  /** Colour steep faces blend toward inside this band (cliffs). */
  steep?: string;
}

export interface TerrainOptions {
  /** World units per side (default 400). Terrain is centred on the origin. */
  size?: number;
  /** Grid quads per side (default 128 → 33k triangles). */
  res?: number;
  /** World height of a shape value of 1 (default 30). */
  height?: number;
  /** Base elevation added to every sample (default 0). */
  y?: number;
  seed?: number;
  /** Landform: preset name or a (x, z) → [0, 1] function (default 'island'). */
  shape?: TerrainShape;
  /** World units per large landform feature (default size/3). KEEP THIS
   * ABSOLUTE when you grow `size` (e.g. ~300) so a bigger terrain gains
   * MORE hills rather than the same hills zoomed up — that difference is
   * the whole sense of scale. */
  featureSize?: number;
  /** Band palette + material preset (default 'grass'). */
  surface?: 'grass' | 'sand' | 'snow' | 'rock';
  /** Override the surface preset's colour bands. */
  bands?: TerrainBand[];
  /** Baked colormap resolution (default 1024). */
  colormapRes?: number;
  /** Soft GROUND DETAIL baked into the grass bands of the colormap: fine
   * turf mottle so bare ground between blades reads as grass, not flat green
   * (0 = off/default — byte-identical to no detail; ~0.4 is a gentle meadow).
   * ZERO runtime cost — it's baked into the colormap already sampled as the
   * terrain's albedo, so it can never regress frame rate (unlike the removed
   * per-pixel detail shader). Only the grass bands take it; sand/rock/snow are
   * untouched. Pair with a higher `colormapRes` (e.g. 2048) for finer turf. */
  groundDetail?: number;
  /** Chunks per side (default auto — a divisor of res near res/16). */
  chunks?: number;
  /** `static: true` meshes (GPU-culled; default true). Set false only if
   * you plan to mutate chunk transforms — heights are edited via the field. */
  static?: boolean;
}

export class Heightfield {
  readonly size: number;
  readonly res: number;
  readonly height: number;
  readonly baseY: number;
  readonly seed: number;
  /** (res+1)² world-Y samples, row-major, z-major rows. */
  readonly heights: Float32Array;

  constructor(opts: TerrainOptions = {}) {
    this.size = opts.size ?? 400;
    this.res = Math.max(1, Math.round(opts.res ?? 128));
    this.height = opts.height ?? 30;
    this.baseY = opts.y ?? 0;
    this.seed = opts.seed ?? 1;
    const fn = shapeFn(opts.shape ?? 'island', this.seed, this.size, opts.featureSize);
    const v = this.res + 1;
    this.heights = new Float32Array(v * v);
    for (let iz = 0; iz < v; iz++) {
      const wz = (iz / this.res - 0.5) * this.size;
      for (let ix = 0; ix < v; ix++) {
        const wx = (ix / this.res - 0.5) * this.size;
        this.heights[iz * v + ix] = this.baseY + fn(wx, wz) * this.height;
      }
    }
  }

  /** Grid sample, clamped at the edges. */
  gridY(ix: number, iz: number): number {
    const v = this.res + 1;
    const cx = Math.min(v - 1, Math.max(0, ix));
    const cz = Math.min(v - 1, Math.max(0, iz));
    return this.heights[cz * v + cx];
  }

  /**
   * Ground height at a world position — TRIANGLE-EXACT: interpolates over
   * the same two triangles per quad the mesh rasterises (diagonal from
   * (ix+1, iz) to (ix, iz+1)), so objects placed here sit ON the render.
   * Clamps outside the terrain.
   */
  heightAt(x: number, z: number): number {
    const gx = Math.min(this.res - 1e-6, Math.max(0, (x / this.size + 0.5) * this.res));
    const gz = Math.min(this.res - 1e-6, Math.max(0, (z / this.size + 0.5) * this.res));
    const ix = Math.floor(gx), iz = Math.floor(gz);
    const fx = gx - ix, fz = gz - iz;
    const a = this.gridY(ix, iz), b = this.gridY(ix + 1, iz);
    const c = this.gridY(ix, iz + 1), d = this.gridY(ix + 1, iz + 1);
    if (fx + fz <= 1) return a + (b - a) * fx + (c - a) * fz;
    return d + (c - d) * (1 - fx) + (b - d) * (1 - fz);
  }

  /** SMOOTH vertex normal at a grid point (central differences) — the same
   * normals the mesh verts carry, so shading and queries agree. */
  vertexNormal(ix: number, iz: number): [number, number, number] {
    const cell = this.size / this.res;
    const dx = (this.gridY(ix + 1, iz) - this.gridY(ix - 1, iz)) / (2 * cell);
    const dz = (this.gridY(ix, iz + 1) - this.gridY(ix, iz - 1)) / (2 * cell);
    const il = 1 / Math.hypot(dx, 1, dz);
    return [-dx * il, il, -dz * il];
  }

  /** Smooth surface normal at a world position (bilinear vertex normals). */
  normalAt(x: number, z: number): { x: number; y: number; z: number } {
    const gx = Math.min(this.res - 1e-6, Math.max(0, (x / this.size + 0.5) * this.res));
    const gz = Math.min(this.res - 1e-6, Math.max(0, (z / this.size + 0.5) * this.res));
    const ix = Math.floor(gx), iz = Math.floor(gz);
    const fx = gx - ix, fz = gz - iz;
    const a = this.vertexNormal(ix, iz), b = this.vertexNormal(ix + 1, iz);
    const c = this.vertexNormal(ix, iz + 1), d = this.vertexNormal(ix + 1, iz + 1);
    const nx = (a[0] + (b[0] - a[0]) * fx) * (1 - fz) + (c[0] + (d[0] - c[0]) * fx) * fz;
    const ny = (a[1] + (b[1] - a[1]) * fx) * (1 - fz) + (c[1] + (d[1] - c[1]) * fx) * fz;
    const nz = (a[2] + (b[2] - a[2]) * fx) * (1 - fz) + (c[2] + (d[2] - c[2]) * fx) * fz;
    const il = 1 / Math.hypot(nx, ny, nz);
    return { x: nx * il, y: ny * il, z: nz * il };
  }

  /** 0 = flat, 1 = vertical (it's just 1 - normalAt().y). */
  slopeAt(x: number, z: number): number {
    return 1 - this.normalAt(x, z).y;
  }
}

// ── Chunk mesh extraction ───────────────────────────────────────────────────

export interface TerrainChunk {
  /** UNIT-space triangle soup (pos+normal+uv, 8 floats/vert): positions in
   * [-0.5, 0.5]³ of the placement below, normals already WORLD-space (the
   * instance carries no rotation, so they pass through the shader exactly). */
  verts: Float32Array<ArrayBuffer>;
  x: number; y: number; z: number;
  w: number; h: number; d: number;
}

/** Build one chunk's mesh. Edge verts sample the SHARED heightfield grid, so
 * adjacent chunks are seamless by construction. */
export function chunkVerts(hf: Heightfield, cx: number, cz: number, chunksPerSide: number, colormapRes = 1024): TerrainChunk {
  const q = hf.res / chunksPerSide;               // quads per chunk side
  if (q !== Math.floor(q)) throw new Error('terrain: chunks must divide res');
  const chunkW = hf.size / chunksPerSide;
  const xc = (cx + 0.5) * chunkW - hf.size / 2;
  const zc = (cz + 0.5) * chunkW - hf.size / 2;
  const x0 = cx * q, z0 = cz * q;
  let minY = Infinity, maxY = -Infinity;
  for (let iz = 0; iz <= q; iz++) {
    for (let ix = 0; ix <= q; ix++) {
      const y = hf.gridY(x0 + ix, z0 + iz);
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  const midY = (minY + maxY) / 2;
  const rangeY = Math.max(maxY - minY, 1e-3);
  // Inset uv half a texel so linear sampling never wraps at the [0,1] edges.
  const inset = 0.5 / colormapRes, span = 1 - 1 / colormapRes;

  const verts = new Float32Array(q * q * 6 * 8);
  let o = 0;
  const emit = (ix: number, iz: number): void => {
    const wx = ((x0 + ix) / hf.res - 0.5) * hf.size;
    const wz = ((z0 + iz) / hf.res - 0.5) * hf.size;
    const wy = hf.gridY(x0 + ix, z0 + iz);
    const n = hf.vertexNormal(x0 + ix, z0 + iz);
    verts[o++] = (wx - xc) / chunkW;
    verts[o++] = (wy - midY) / rangeY;
    verts[o++] = (wz - zc) / chunkW;
    verts[o++] = n[0]; verts[o++] = n[1]; verts[o++] = n[2];
    verts[o++] = inset + (wx / hf.size + 0.5) * span;
    verts[o++] = inset + (wz / hf.size + 0.5) * span;
  };
  for (let iz = 0; iz < q; iz++) {
    for (let ix = 0; ix < q; ix++) {
      // Diagonal (ix+1, iz) → (ix, iz+1): the SAME split heightAt assumes.
      // CCW seen from +Y (front faces up).
      emit(ix, iz); emit(ix, iz + 1); emit(ix + 1, iz);
      emit(ix + 1, iz); emit(ix, iz + 1); emit(ix + 1, iz + 1);
    }
  }
  return { verts, x: xc, y: midY, z: zc, w: chunkW, h: rangeY, d: chunkW };
}

