/**
 * Bake the band colormap: one RGBA pixel field over the whole terrain
 * (world XZ → uv), colour from the height-band gradient, blended toward the
 * band's `steep` colour on slopes, with two scales of noise jitter so flats
 * aren't airbrushed. Pure — world3d puts it on a canvas.
 */
export function bakeColormapPixels(hf: Heightfield, bands: TerrainBand[], res: number, seed = 1, detail = 0): Uint8ClampedArray<ArrayBuffer> {
  const px = new Uint8ClampedArray(res * res * 4);
  const sorted = [...bands].sort((a, b) => a.h - b.h);
  const cols = sorted.map((b) => rgba(b.color));
  const steeps = sorted.map((b) => rgba(b.steep ?? b.color));
  const jperm = noisePerm(seed ^ 0x51ab);
  const jitterF = 24 / res;
  // GROUND DETAIL (opt-in): two extra, FINER octaves of turf mottle (wavelength
  // ~1.7 u and ~0.6 u, vs the broad 16 u jitter above) painted only where the
  // ground is grassy, so bare earth between blades reads as textured turf
  // instead of flat green. Baked once — zero runtime cost.
  const dperm = noisePerm(seed ^ 0x2c9e);
  const dF1 = 240 / res, dF2 = 680 / res;
  let o = 0;
  for (let py = 0; py < res; py++) {
    const wz = ((py + 0.5) / res - 0.5) * hf.size;
    for (let pxi = 0; pxi < res; pxi++) {
      const wx = ((pxi + 0.5) / res - 0.5) * hf.size;
      const h01 = Math.min(1, Math.max(0, (hf.heightAt(wx, wz) - hf.baseY) / Math.max(hf.height, 1e-6)));
      const slope = 1 - hf.normalAt(wx, wz).y;
      // Band gradient: soft-edged bands, not a linear wash.
      let i = 0;
      while (i < sorted.length - 1 && h01 >= sorted[i + 1].h) i++;
      const j = Math.min(i + 1, sorted.length - 1);
      const gap = Math.max(sorted[j].h - sorted[i].h, 1e-6);
      const t = i === j ? 0 : smoothstep(0.15, 0.85, (h01 - sorted[i].h) / gap);
      const sMix = smoothstep(0.22, 0.5, slope);
      let r = 0, g = 0, b = 0;
      for (let k = 0; k < 3; k++) {
        const flat = cols[i][k] + (cols[j][k] - cols[i][k]) * t;
        const steep = steeps[i][k] + (steeps[j][k] - steeps[i][k]) * t;
        const v = flat + (steep - flat) * sMix;
        if (k === 0) r = v; else if (k === 1) g = v; else b = v;
      }
      // Jitter: broad patches + per-texel grain.
      let jit = 1 + perlin2(pxi * jitterF, py * jitterF, jperm) * 0.06 + (hash2(pxi, py, seed) - 0.5) * 0.05;
      // Opt-in fine turf mottle, gated to grassy pixels (green dominant, not on
      // sand/rock/snow) so it only textures actual grass. Two octaves give the
      // ground a soft grain at eye level without any per-frame shader work.
      // NOTE: r,g,b are 0..1 here (scaled by 255 on write) — the grassiness
      // gate must compare in that space, not 0..255.
      let dr = r, dg = g, db = b;
      if (detail > 0) {
        const grassy = Math.max(0, Math.min(1, (g - Math.max(r, b)) / 0.12));
        if (grassy > 0) {
          const m = perlin2(pxi * dF1, py * dF1, dperm) * 0.62 + perlin2(pxi * dF2, py * dF2, dperm) * 0.38;
          const k = m * detail * grassy;
          // Luminance grain + a small chroma fleck (drier/olive where the noise
          // is high, deeper green where low) so it reads as TURF, not a dimmer.
          const lum = 1 + k * 0.26;
          dr = r * lum * (1 + k * 0.10);
          dg = g * lum;
          db = b * lum * (1 - k * 0.12);
        }
      }
      // SAND VARIATION (always on): warm, bright, low-green pixels get a
      // GENTLE multi-texel wash so flat band colour doesn't read as a
      // yellow smear from a distance. NOT per-texel: texel-scale speckle
      // (the original hash + near-Nyquist perlin) magnifies into chunky
      // lego blobs at standing height — exactly the colormap's texel print
      // (Rich's beach shot, twice). Fine close-range grain lives in the
      // mesh FS's world-space grain texture instead, which fades itself
      // with distance and never shows the texel grid.
      {
        const sandy = Math.max(0, Math.min(1, ((r + g) * 0.5 - b - 0.04) / 0.12))
          * (1 - Math.max(0, Math.min(1, (g - Math.max(r, b)) / 0.08)));
        if (sandy > 0) {
          // BROAD and GENTLE: ±6% at a ~2-unit wavelength read as blotchy
          // "skin disease" from standing height (Rich, round 3) — dune-scale
          // shading wants a long wavelength and a whisper of contrast.
          const sp = perlin2(pxi * dF1 * 0.55, py * dF1 * 0.55, dperm);
          const kk = 1 + sp * 0.035 * sandy;
          dr *= kk; dg *= kk; db *= kk * 0.99;
        }
      }
      px[o++] = dr * 255;
      px[o++] = dg * 255;
      px[o++] = db * 255;
      px[o++] = 255;
    }
  }
  return px;
}

// ── Close-range ground grain ────────────────────────────────────────────────
// The colormap's texels span >1 world unit on any real terrain: magnified
// bilinear texels read as LEGO BRICKS at ankle height (Rich's beach shot),
// and the per-texel speckle bake makes the blocks pop harder. The fix is a
// small TILEABLE world-space speckle the mesh FS multiplies over sandy
// albedo near the camera — its mip chain averages to 0.5, so it fades
// itself out with distance and can never change the terrain's look from
// afar. Baked once here (pure + dist-testable), uploaded by Lights3d.

/** One tileable grain field, size×size, values ~[0, 1] around a 0.5 mean:
 * three DECORRELATED octaves of wrapped-lattice value noise (the second
 * axis-swapped, the third diagonal-offset — same-orientation lattices gave
 * the sand a visible uniform grid with long stripes; Rich's image) + a
 * per-texel hash sparkle. */
export function bakeGrainField(size = 256): Float32Array {
  const out = new Float32Array(size * size);
  const sm = (v: number): number => v * v * (3 - 2 * v);
  const val = (x: number, y: number, period: number, seed: number): number => {
    const xi = Math.floor(x), yi = Math.floor(y);
    const h = (ix: number, iy: number): number =>
      hash2(((ix % period) + period) % period, ((iy % period) + period) % period, seed);
    const a = h(xi, yi), b = h(xi + 1, yi), c = h(xi, yi + 1), d = h(xi + 1, yi + 1);
    const ux = sm(x - xi), uy = sm(y - yi);
    return a + (b - a) * ux + (c - a) * uy + (a - b - c + d) * ux * uy;
  };
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = (x + 0.5) / size, v = (y + 0.5) / size;
      const g = 0.42 * val(u * 23, v * 23, 23, 0x5a17)             // soft clumps
        + 0.33 * val(v * 61, u * 61, 61, 0x92d3)                   // axis-swapped grit
        + 0.25 * val(u * 97 + v * 41, v * 97 - u * 41, 97, 0x1cb5); // diagonal fleck
      const sparkle = (hash2(x, y, 0x31f7) - 0.5) * 0.5;           // per-texel grains
      out[y * size + x] = Math.min(1, Math.max(0, 0.5 + (g - 0.5) * 0.95 + sparkle));
    }
  }
  return out;
}

/** Bake the grain into an r8unorm texture with a full box-filter mip chain
 * (the deep mips are the distance fade — they converge on the 0.5 mean). */
export function createGrainTexture(device: GPUDevice, size = 256): GPUTexture {
  const mips = 1 + Math.floor(Math.log2(size));
  const tex = device.createTexture({
    size: { width: size, height: size },
    format: 'r8unorm',
    mipLevelCount: mips,
    usage: BITS.TEXTURE_BINDING | 0x2 /* texture COPY_DST */,
  });
  let field = bakeGrainField(size);
  let w = size;
  for (let m = 0; m < mips; m++) {
    const bytes = new Uint8Array(w * w);
    for (let i = 0; i < w * w; i++) {
      const v = Math.round(field[i] * 255);
      bytes[i] = v < 0 ? 0 : v > 255 ? 255 : v;
    }
    device.queue.writeTexture({ texture: tex, mipLevel: m }, bytes, { bytesPerRow: w }, { width: w, height: w });
    if (m + 1 < mips) {
      const hw = w >> 1;
      const next = new Float32Array(hw * hw);
      for (let y = 0; y < hw; y++) {
        for (let x = 0; x < hw; x++) {
          const i0 = y * 2 * w + x * 2, i1 = i0 + w;
          next[y * hw + x] = (field[i0] + field[i0 + 1] + field[i1] + field[i1 + 1]) * 0.25;
        }
      }
      field = next; w = hw;
    }
  }
  return tex;
}

/** Pick a chunks-per-side that divides res — near res/16, capped at 8 per
 * side (64 buckets: past that, per-bucket cull dispatches + indirect draws
 * cost more than the culling saves). */
export function pickChunks(res: number, requested?: number): number {
  if (requested && res % requested === 0) return requested;
  let c = Math.max(1, Math.min(8, Math.round(res / 16)));
  while (c > 1 && res % c !== 0) c--;
  return c;
}

// ── E5: deformable surfaces — the SSX feature ──────────────────────────────
// A DEFORM MAP: a square window of carve depths (world units removed from
// the surface) that FOLLOWS the action. CPU-AUTHORITATIVE — the game stamps
// dents here, `depthAt` reads them back bilinearly (boards settle into
// their own ruts), and world3d uploads dirty texels to a r32float texture
// the terrain shader displaces/tints/rim-lights from. One array, two
// consumers, zero divergence — the water baked-ground lesson applied from
// day one.

export interface DeformOptions {
  /** Texels per side of the window (default 1024 — 4 MB of r32float). */
  res?: number;
  /** World units the window covers (default 480). Texel = window/res —
   * 0.47 u at the defaults. SIZE THIS FOR SPEED: the window rides
   * ~30% behind the carver, so trail persistence ≈ 0.8 × window — a
   * 28 u/s snowboarder keeps ~14 s of line at the default. Texels
   * should stay ≲ the carver radius or stamps fall between them. */
  window?: number;
  /** Maximum carve depth in world units (default 0.6). Stamps clamp here —
   * re-riding a trail compacts it, never digs to bedrock. */
  depth?: number;
  /** Refill rate, depth-units/second (default 0 — snow: trails persist).
   * Sand wants ~0.1–0.3 so tracks slowly drift shut. */
  heal?: number;
  /** Exposed under-layer colour (default per surface: compressed blue-white
   * for snow, dark wet sand, dirt for grass). */
  under?: string;
  /** Trench-edge normal strength (default 1 = physical gradient). */
  rim?: number;
  /** Snow glint strength (default 0.6 on 'snow' surfaces, else 0). */
  sparkle?: number;
  /** GEOMETRIC sink cap on the BASE terrain, world units (default 0.18).
   * The base mesh's verts are metres apart, so it can't render a
   * board-width trench — the far/persistent line is fragment work on it
   * (tint + rim normals) with at most this much real dip. The NEAR
   * trench is real geometry on the high-poly snow layer (see `layer`). */
  sink?: number;
  /** SNOW LAYER (E5, the real deformable geometry): a dense follow-grid
   * mesh — the WebGPU stand-in for tessellation (Batman: Arkham Origins /
   * UE RVT do this with hardware tessellation) — that REPLACES the base
   * terrain around the rider: the base discards a disc under it, the
   * patch renders the SAME surface (triangle-exact) minus the carve. One
   * surface, never two → no z-fighting, and the trench is real geometry
   * you can fly a probe line into. `false` disables it (base-only, the
   * flat fragment-trail look). Default on. */
  layer?: boolean;
  /** Snow/sand depth available to carve into (default 0.6): conceptually
   * the terrain surface IS the snow top and the ground sits `thickness`
   * below it — carves clamp here so a trench never reaches bedrock. */
  thickness?: number;
  /** Layer patch size in world units (default 240 — the real-geometry
   * radius around the rider; beyond it the base-terrain fragment trail
   * carries the line). */
  patch?: number;
  /** Grid cells per side of the patch (default 288 → ~0.83 u at the
   * default patch; keep the cell ≲ the carver radius). */
  cells?: number;
  /** Layer surface colour (default per surface: bright snow, warm sand). */
  albedo?: string;
}

export class DeformMap {
  readonly res: number;
  readonly window: number;
  readonly maxDepth: number;
  readonly sink: number;
  /** Depth of the deformable snow/sand layer above the base (see
   * DeformOptions.thickness). heightAt lifts the surface by this. */
  readonly thickness: number;
  /** High-poly patch size in world units (0 = no layer) — the feather
   * radius the RENDERED surface uses; snowSurfaceAt matches it. */
  readonly patchWin: number;
  /** Patch grid cells per side (the follow-grid resolution). */
  readonly patchCells: number;
  heal: number;
  /** The rider's live position, set by Terrain3d.stepCarvers (the deform
   * WINDOW rides ~30% behind this; the patch sits under the action). */
  focusX = 0;
  focusZ = 0;
  /** The patch centre SNAPPED to the cell grid. The follow-grid must land
   * on a fixed world lattice every frame — if it slid continuously with
   * the rider, each vertex would sample a moving world point and the
   * triangulation would SWIM (Rich: the trenches "ripple like water").
   * Snapping to whole cells makes the mesh world-stable (it re-indexes as
   * it shifts, but the surface is identical). */
  patchCx = 0;
  patchCz = 0;
  /** res² carve depths (≥ 0), row-major, z-major rows, texel centres. */
  readonly data: Float32Array;
  /** Window centre in world units — moves via follow(), quantised to texels. */
  cx = 0;
  cz = 0;
  /** Dirty texel rect [x0, z0) .. [x1, z1) for partial uploads. */
  dirtyX0 = 0; dirtyZ0 = 0; dirtyX1 = 0; dirtyZ1 = 0;
  /** The whole window changed (shift/heal) — upload everything. */
  fullDirty = false;
  private any = false;

  constructor(opts: DeformOptions = {}) {
    this.res = Math.max(16, Math.round(opts.res ?? 1024));
    this.window = opts.window ?? 480;
    this.thickness = opts.layer === false ? 0 : (opts.thickness ?? 0.6);
    // With a layer, the snow is only `thickness` deep — carves clamp there
    // (a trench never punches through to bedrock).
    this.maxDepth = this.thickness > 0
      ? Math.min(opts.depth ?? 0.6, this.thickness)
      : (opts.depth ?? 0.6);
    this.sink = Math.min(opts.sink ?? 0.18, this.maxDepth);
    this.patchWin = this.thickness > 0 ? (opts.patch ?? 240) : 0;
    this.patchCells = Math.max(2, Math.round(opts.cells ?? 288));
    this.heal = opts.heal ?? 0;
    this.data = new Float32Array(this.res * this.res);
  }

  /** World units per texel. */
  get texel(): number { return this.window / this.res; }

  private markDirty(x0: number, z0: number, x1: number, z1: number): void {
    if (this.dirtyX1 <= this.dirtyX0) {
      this.dirtyX0 = x0; this.dirtyZ0 = z0; this.dirtyX1 = x1; this.dirtyZ1 = z1;
    } else {
      this.dirtyX0 = Math.min(this.dirtyX0, x0); this.dirtyZ0 = Math.min(this.dirtyZ0, z0);
      this.dirtyX1 = Math.max(this.dirtyX1, x1); this.dirtyZ1 = Math.max(this.dirtyZ1, z1);
    }
  }

  /** Stamp one bowl-profiled dent: depth d at the centre easing to 0 at
   * radius r. MAX-blends with what's there (carving is compaction, not
   * excavation — the same pass twice is one trench, not two deep). */
  stamp(x: number, z: number, r: number, d: number): void {
    const t = this.texel, res = this.res;
    const gx = (x - this.cx) / t + res / 2 - 0.5;
    const gz = (z - this.cz) / t + res / 2 - 0.5;
    const gr = r / t;
    const x0 = Math.max(0, Math.floor(gx - gr)), x1 = Math.min(res - 1, Math.ceil(gx + gr));
    const z0 = Math.max(0, Math.floor(gz - gr)), z1 = Math.min(res - 1, Math.ceil(gz + gr));
    if (x1 < x0 || z1 < z0) return;
    const depth = Math.min(d, this.maxDepth);
    for (let iz = z0; iz <= z1; iz++) {
      for (let ix = x0; ix <= x1; ix++) {
        const dist = Math.hypot(ix - gx, iz - gz) / gr;
        if (dist >= 1) continue;
        // NARROW AND DEEP (the SSX board cut, Rich's reference): a flat
        // full-depth core out past half the radius, then a steep wall.
        // The renderer's berm lips form along the skirt this leaves.
        const fall = 1 - smoothstep(0.55, 1, dist);
        const v = depth * fall;
        const i = iz * res + ix;
        if (v > this.data[i]) { this.data[i] = v; this.any = true; }
      }
    }
    this.markDirty(x0, z0, x1 + 1, z1 + 1);
  }

  /** Stamp a capsule: discs along the segment every half-texel — the
   * board's frame-to-frame trail with no dashed gaps at speed. */
  line(x0: number, z0: number, x1: number, z1: number, r: number, d: number): void {
    const len = Math.hypot(x1 - x0, z1 - z0);
    const step = Math.max(this.texel * 0.5, r * 0.25);
    const n = Math.max(1, Math.ceil(len / step));
    for (let i = 0; i <= n; i++) {
      const f = i / n;
      this.stamp(x0 + (x1 - x0) * f, z0 + (z1 - z0) * f, r, d);
    }
  }

  /** Carve depth at a world position — the SAME manual bilinear over texel
   * centres the shader runs, including its window-edge fade, so a board at
   * heightAt() sits exactly on the rendered snow. 0 outside the window. */
  depthAt(x: number, z: number): number {
    const u = (x - this.cx) / this.window + 0.5;
    const v = (z - this.cz) / this.window + 0.5;
    const edge = Math.min(Math.min(u, 1 - u), Math.min(v, 1 - v));
    if (edge <= 0) return 0;
    const res = this.res;
    const gx = u * res - 0.5, gz = v * res - 0.5;
    const ix = Math.floor(gx), iz = Math.floor(gz);
    const fx = gx - ix, fz = gz - iz;
    const cl = (i: number): number => Math.min(res - 1, Math.max(0, i));
    const x0 = cl(ix), x1 = cl(ix + 1), z0 = cl(iz), z1 = cl(iz + 1);
    const a = this.data[z0 * res + x0], b = this.data[z0 * res + x1];
    const c = this.data[z1 * res + x0], dd = this.data[z1 * res + x1];
    const bi = (a + (b - a) * fx) * (1 - fz) + (c + (dd - c) * fx) * fz;
    const et = Math.min(1, Math.max(0, edge / 0.06));
    return bi * et * et * (3 - 2 * et);
  }

  /** Re-centre the window on (x, z) when it has drifted more than an eighth
   * of the window — COPY-ON-SHIFT: content moves by whole texels so every
   * carve keeps its world position; texels scrolling in are fresh snow.
   * Returns true when a shift happened (the texture needs a full upload). */
  follow(x: number, z: number): boolean {
    const t = this.texel;
    const sx = Math.round((x - this.cx) / t), sz = Math.round((z - this.cz) / t);
    const thresh = this.res / 8;
    if (Math.abs(sx) < thresh && Math.abs(sz) < thresh) return false;
    const res = this.res, data = this.data;
    // data_new[iz][ix] = data_old[iz + sz][ix + sx] — iterate in the safe
    // direction for each axis so in-place copy never reads clobbered rows.
    const zs = sz > 0 ? 0 : res - 1, ze = sz > 0 ? res : -1, zd = sz > 0 ? 1 : -1;
    for (let iz = zs; iz !== ze; iz += zd) {
      const src = iz + sz;
      if (src < 0 || src >= res) {
        data.fill(0, iz * res, iz * res + res);
        continue;
      }
      if (sx >= 0) {
        data.copyWithin(iz * res, src * res + sx, src * res + res);
        data.fill(0, iz * res + res - sx, iz * res + res);
      } else {
        data.copyWithin(iz * res - sx, src * res, src * res + res + sx);
        data.fill(0, iz * res, iz * res - sx);
      }
    }
    this.cx += sx * t;
    this.cz += sz * t;
    this.fullDirty = true;
    return true;
  }

  private healAcc = 0;

  /** Uniform refill (sand): every carve shallows by heal·dt. Applied in
   * 0.1 s quanta — every heal tick re-uploads the whole map, and 10 Hz
   * is invisible on a slow drift-shut. */
  healStep(dt: number): void {
    if (this.heal <= 0 || !this.any) return;
    this.healAcc += dt;
    if (this.healAcc < 0.1) return;
    const dec = this.heal * this.healAcc;
    this.healAcc = 0;
    let left = false;
    for (let i = 0; i < this.data.length; i++) {
      const v = this.data[i];
      if (v <= 0) continue;
      const nv = v - dec;
      this.data[i] = nv > 0 ? nv : 0;
      if (nv > 0) left = true;
    }
    this.any = left;
    this.fullDirty = true;
  }

  clearDirty(): void {
    this.fullDirty = false;
    this.dirtyX0 = this.dirtyZ0 = this.dirtyX1 = this.dirtyZ1 = 0;
  }
}

/** The high-poly snow-layer PATCH: a unit grid in XZ ([-0.5, 0.5], y = 0),
 * `cells`² quads as a plain pos+normal+uv soup (the VS displaces it by the
 * baked base height + thickness − carve, so the trench is REAL geometry).
 * uv is 0..1 across the patch. Pure — world3d uploads it once. */
export function deformPatchVerts(cells: number): Float32Array<ArrayBuffer> {
  const c = Math.max(2, Math.round(cells));
  const v = new Float32Array(c * c * 6 * 8);
  let o = 0;
  const emit = (ix: number, iz: number): void => {
    v[o] = ix / c - 0.5; v[o + 1] = 0; v[o + 2] = iz / c - 0.5;
    v[o + 3] = 0; v[o + 4] = 1; v[o + 5] = 0;
    v[o + 6] = ix / c; v[o + 7] = iz / c;
    o += 8;
  };
  for (let iz = 0; iz < c; iz++) {
    for (let ix = 0; ix < c; ix++) {
      // HERRINGBONE the split direction per quad. A grid where every quad
      // splits the SAME diagonal shades a smooth trench wall into a
      // directional sawtooth (Rich's "weird offset angle") — the wall runs
      // across the uniform diagonals and every triangle leans the same way.
      // Alternating the diagonal cancels that bias into fine symmetric grain.
      if ((ix + iz) & 1) {
        emit(ix, iz); emit(ix, iz + 1); emit(ix + 1, iz);
        emit(ix + 1, iz); emit(ix, iz + 1); emit(ix + 1, iz + 1);
      } else {
        emit(ix, iz); emit(ix, iz + 1); emit(ix + 1, iz + 1);
        emit(ix, iz); emit(ix + 1, iz + 1); emit(ix + 1, iz);
      }
    }
  }
  return v;
}

// ── The live handle ─────────────────────────────────────────────────────────

import type { Mesh3d } from './world3d.js';
import type { Grass3d, GrassOptions } from './grass3d.js';

interface Carver {
  target: { x: number; y: number; z: number };
  radius: number;
  depth: number;
  lx: number;
  lz: number;
  /** Smoothed heading (unit-ish) — biases the follow window BEHIND you. */
  hx: number;
  hz: number;
  wasAir: boolean;
  dead: boolean;
}

/** Returned by world.terrain(): the heightfield queries games drive off,
 * plus the chunk meshes. Kill removes the chunks AND their buckets. */
export class Terrain3d {
  /** The deform window, once deformable() has been called. */
  deform: DeformMap | null = null;
  private carvers: Carver[] = [];

  constructor(
    readonly field: Heightfield,
    readonly meshes: Mesh3d[],
    private readonly onKill?: () => void,
    private readonly deformHook?: (map: DeformMap, opts: DeformOptions) => void,
    private readonly grassHook?: (opts: GrassOptions) => Grass3d,
  ) {}

  /**
   * Plant GRASS (E6 vegetation, Phase 2): a compute-driven follow-window of
   * instanced blades that ride this terrain's heightfield, tinted off its
   * colormap and lit like the ground. v1 is LUSH near the camera. Returns
   * the field handle (tune `span`, `cells`, `height`, `wind`, `color`).
   */
  grass(opts: GrassOptions = {}): Grass3d | null {
    return this.grassHook?.(opts) ?? null;
  }

  /**
   * Make the surface DEFORMABLE (E5 — the SSX feature): boards, wheels and
   * feet carve persistent dents the terrain renders as displaced, tinted,
   * rim-lit trenches. Snow trails persist; pass `heal` for sand that drifts
   * shut. The window follows the first carver. Idempotent.
   */
  deformable(opts: DeformOptions = {}): DeformMap {
    if (this.deform) return this.deform;
    this.deform = new DeformMap(opts);
    this.deformHook?.(this.deform, opts);
    return this.deform;
  }

  /** Auto-trail: carve a capsule along `target`'s ground track every frame
   * (any live {x, y, z} — a mesh, a group). Only carves ON CONTACT: catch
   * air and the trail breaks exactly where you left the snow. */
  carver(target: { x: number; y: number; z: number }, opts: { radius?: number; depth?: number } = {}): { kill: () => void } {
    const map = this.deformable();
    const c: Carver = {
      target,
      radius: opts.radius ?? 0.8,
      depth: opts.depth ?? map.maxDepth * 0.75,
      lx: target.x, lz: target.z, hx: 0, hz: 0, wasAir: true, dead: false,
    };
    this.carvers.push(c);
    return { kill: (): void => { c.dead = true; } };
  }

  /** Manual one-off stamp (a landing crater, a shovel). */
  carve(x: number, z: number, r: number, d: number): void {
    this.deformable().stamp(x, z, r, d);
  }

  /** Carve depth at (x, z) — 0 where untouched. */
  carveDepthAt(x: number, z: number): number {
    return this.deform ? this.deform.depthAt(x, z) : 0;
  }

  /** Advance the carvers + heal — world3d calls this once per frame with
   * wall-clock dt. Pure (no GPU): dist-testable. */
  stepCarvers(dt: number): void {
    const map = this.deform;
    if (!map) return;
    let followed = false;
    for (const c of this.carvers) {
      if (c.dead) continue;
      const t = c.target;
      if (!followed) {
        // The high-poly patch centres on the rider (real geometry under
        // the action), SNAPPED to the cell grid so the follow-grid is
        // world-stable (no swimming); the deform WINDOW rides ~30% BEHIND
        // the heading — you look back at where you've been, so ~80% of the
        // window is trail budget instead of unspent snow ahead.
        map.focusX = t.x; map.focusZ = t.z;
        if (map.patchWin > 0) {
          // Snap by TWO cells, not one: the patch grid is herringbone
          // (alternating diagonals by index parity), so a 1-cell shift
          // flips every quad's diagonal — the whole field re-tessellated
          // on every snap (Rich's frame-flickering sawtooth). A 2-cell
          // snap preserves parity: the geometry is IDENTICAL across
          // shifts, just re-indexed.
          const cell2 = (map.patchWin / map.patchCells) * 2;
          map.patchCx = Math.round(t.x / cell2) * cell2;
          map.patchCz = Math.round(t.z / cell2) * cell2;
        }
        const dx = t.x - c.lx, dz = t.z - c.lz;
        const dl = Math.hypot(dx, dz);
        if (dl > 1e-4) {
          c.hx += (dx / dl - c.hx) * Math.min(1, dt * 3);
          c.hz += (dz / dl - c.hz) * Math.min(1, dt * 3);
        }
        const bias = map.window * 0.3;
        map.follow(t.x - c.hx * bias, t.z - c.hz * bias);
        followed = true;
      }
      // Contact: the carved surface is where the rider sits, so compare
      // against heightAt (which already subtracts the trail).
      const touching = t.y - this.heightAt(t.x, t.z) < c.radius * 1.6 + 0.25;
      // ...and MOTION: a stationary board doesn't dig. Re-stamping a
      // fresh bowl every frame under a still rider kept reshaping the
      // trench (and, with heal, made him bob in his own hole — Rich's
      // judder + "recalculated every few frames").
      const dl2 = Math.hypot(t.x - c.lx, t.z - c.lz);
      if (touching && dl2 > 0.02) {
        if (c.wasAir) { c.lx = t.x; c.lz = t.z; }
        map.line(c.lx, c.lz, t.x, t.z, c.radius, c.depth);
        c.lx = t.x; c.lz = t.z;
      } else if (!touching) {
        c.lx = t.x; c.lz = t.z;
      }
      c.wasAir = !touching;
    }
    map.healStep(dt);
  }

  /** Ground height at (x, z) — the SNOW SURFACE a rider rides on. With a
   * deformable layer, the heightfield itself IS the snow top (the ground
   * sits `thickness` below — see groundAt) and the carve digs a REAL
   * trench straight into it: `field − carve` (carves are clamped to the
   * layer depth, so never below bedrock). This is exactly what the
   * high-poly patch renders around the rider — rider, probe and pixels
   * agree. Without a layer: field minus the small fragment-shaded sink. */
  heightAt(x: number, z: number): number {
    const base = this.field.heightAt(x, z);
    if (!this.deform) return base;
    if (this.deform.thickness <= 0) return base - Math.min(this.deform.depthAt(x, z), this.deform.sink);
    return base - this.deform.depthAt(x, z);
  }

  /** Depth of the carvable snow/sand layer (0 if not deformable or layer
   * disabled). The BEDROCK under the snow is `field.heightAt − thickness`
   * — see groundAt. */
  get snowThickness(): number { return this.deform?.thickness ?? 0; }

  /** The bedrock under the snow at (x, z): what a probe's base puck should
   * mark. Fresh snow sits `thickness` above it; a full-depth carve reaches
   * it exactly. Without a layer this is just the heightfield. */
  groundAt(x: number, z: number): number {
    return this.field.heightAt(x, z) - this.snowThickness;
  }

  /** @deprecated The patch now renders heightAt exactly (it replaces the
   * base terrain rather than floating above it) — use heightAt. */
  snowSurfaceAt(x: number, z: number): number {
    return this.heightAt(x, z);
  }
  /** Smooth surface normal at (x, z). */
  normalAt(x: number, z: number): { x: number; y: number; z: number } { return this.field.normalAt(x, z); }
  /** 0 flat → 1 vertical. */
  slopeAt(x: number, z: number): number { return this.field.slopeAt(x, z); }
  get size(): number { return this.field.size; }

  kill(): void {
    for (const m of this.meshes) m.kill();
    this.onKill?.();
  }
}
