// NAVMESH (agents Tier-3) — the vendored recast-navigation core wrapped for the
// engine. Where the built-in NavGrid (navgrid3d.ts) plans over a heightfield
// grid, this bakes a true Detour NAVMESH from real geometry (positions +
// indices — terrain chunks, authored level meshes), giving precise routes over
// arbitrary walkable surfaces + built-in Crowd local avoidance.
//
// recast is a ~800 KB WASM chunk, so — exactly like the Box3D/Box2D physics
// cores — it ships as a SEPARATE sibling artifact (`agents-nav-core.mjs`) that
// this wrapper dynamic-imports only on the first `agents.navmesh(...)`. Games
// that never bake a navmesh pay nothing. Module load here is DOM/GPU-free; the
// core is loaded lazily so dist tests can drive it in Node.

export interface NavVec3 { x: number; y: number; z: number }

// The vendored core surface is deliberately untyped (`any`) — the chunk carries
// its own behaviour; this wrapper is the typed contract (mirrors physics3d.ts).
type NavCore = any;

// ─── Lazy core loader (copied verbatim from physics3d.ts, INCLUDING the
// @vite-ignore variable-URL trap: a literal URL lets vite statically inline the
// ~800 KB WASM into the main bundle as base64, defeating the lazy chunk). ───
let corePromise: Promise<NavCore> | null = null;
async function loadNavCore(explicit?: string): Promise<NavCore> {
  if (corePromise) return corePromise;
  corePromise = (async () => {
    const candidates = (explicit
      ? [explicit]
      : [
          './agents-nav-core.mjs',            // next to webgpu.js (shipped)
          '../agents-nav-core.mjs',           // dist/webgpu/ types layout
          '../../vendor/agents-nav-core.mjs', // dev: src/lib → vendor/
        ]).map((p) => new URL(p, import.meta.url).href);
    let lastErr: unknown = null;
    for (const url of candidates) {
      try {
        const mod = await import(/* @vite-ignore */ url);
        return await mod.default();
      } catch (e) { lastErr = e; }
    }
    throw new Error('agents.navmesh: nav core module not found (agents-nav-core.mjs). ' + String(lastErr));
  })();
  return corePromise;
}

export interface NavMeshOptions {
  /** Explicit geometry: flat vertex xyz triples + triangle indices (CCW so the
   * walkable faces point UP). Pass your level's collision meshes here. */
  positions?: ArrayLike<number>;
  indices?: ArrayLike<number>;
  /** …OR auto-triangulate a heightfield into a grid mesh. */
  from?: 'terrain';
  heightAt?: (x: number, z: number) => number;
  size?: number;
  center?: { x: number; z: number };
  res?: number;

  // Recast bake params (sensible defaults; all world units unless noted).
  /** Voxel cell size — the navmesh resolution (default 0.3). */
  cellSize?: number;
  /** Voxel cell height (default 0.2). */
  cellHeight?: number;
  /** Agent radius: the navmesh is eroded by this so paths keep clearance (default 0.6). */
  agentRadius?: number;
  /** Agent height — minimum head-room (default 2). */
  agentHeight?: number;
  /** Max step/ledge the agent can climb (default 0.9). */
  agentMaxClimb?: number;
  /** Max walkable slope in degrees (default 50). */
  agentMaxSlope?: number;
  /** Override the core module URL (rarely needed). */
  module?: string;
}

/** Triangulate a heightfield region into a navmesh source mesh (CCW-up). */
export function terrainMesh(
  heightAt: (x: number, z: number) => number, size: number, res: number, cx = 0, cz = 0,
): { positions: Float32Array; indices: Uint32Array } {
  const n = Math.max(2, Math.floor(res));
  const step = size / (n - 1), x0 = cx - size / 2, z0 = cz - size / 2;
  const positions = new Float32Array(n * n * 3);
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      const x = x0 + i * step, z = z0 + j * step, o = (j * n + i) * 3;
      positions[o] = x; positions[o + 1] = heightAt(x, z); positions[o + 2] = z;
    }
  }
  const indices = new Uint32Array((n - 1) * (n - 1) * 6);
  let k = 0;
  for (let j = 0; j < n - 1; j++) {
    for (let i = 0; i < n - 1; i++) {
      const a = j * n + i, b = a + 1, c = a + n, d = c + 1;
      // CCW from above (normals up): a, c, b  and  b, c, d.
      indices[k++] = a; indices[k++] = c; indices[k++] = b;
      indices[k++] = b; indices[k++] = c; indices[k++] = d;
    }
  }
  return { positions, indices };
}

/** A baked Detour navmesh + query. Implements the `path()` planner contract so
 * it drops straight into the `navigate` behaviour (`{ kind:'navigate', grid }`)
 * exactly like the built-in NavGrid. */
export class NavMesh3d {
  /** @internal recast NavMesh */
  readonly raw: unknown;
  private core: NavCore;
  private query: any;
  private crowds: Crowd3d[] = [];
  // The point→polygon search box. TALL on Y so a query at y=0 still snaps to an
  // ELEVATED mesh (terrain/platforms); a few units on X/Z so nearby points snap.
  private ext = { x: 4, y: 400, z: 4 };
  dead = false;

  constructor(core: NavCore, navMesh: unknown) {
    this.core = core;
    this.raw = navMesh;
    this.query = new core.NavMeshQuery(navMesh);
  }

  /** A uniformly-random point ON the navmesh — for wander/patrol goals that are
   * guaranteed reachable (never inside a wall). Null if the mesh is empty. */
  randomPoint(): NavVec3 | null {
    const r = this.query.findRandomPoint();
    const p = r && r.randomPoint;
    return r && r.success && p ? { x: p.x, y: p.y, z: p.z } : null;
  }

  /** Snap a point to the nearest navmesh surface (null if off-mesh). */
  nearest(p: NavVec3): NavVec3 | null {
    const r = this.query.findClosestPoint({ x: p.x, y: p.y, z: p.z }, { halfExtents: this.ext });
    return r && r.success ? { x: r.point.x, y: r.point.y, z: r.point.z } : null;
  }

  /** Plan a path start→goal as world waypoints (empty when unreachable). The
   * `navigate` behaviour calls this — same contract as NavGrid.path(). */
  path(start: NavVec3, goal: NavVec3): NavVec3[] {
    const r = this.query.computePath(
      { x: start.x, y: start.y, z: start.z },
      { x: goal.x, y: goal.y, z: goal.z },
      { halfExtents: this.ext },
    );
    const pts: Array<{ x: number; y: number; z: number }> = (r && (r.path ?? r)) || [];
    if (!Array.isArray(pts) || (r && r.success === false)) return [];
    return pts.map((v) => ({ x: v.x, y: v.y, z: v.z }));
  }

  /** Create a recast Crowd for dense local avoidance among navmesh agents.
   * (Optional tier — most games use the built-in steering avoidance.) */
  crowd(opts: { maxAgents?: number; maxAgentRadius?: number } = {}): Crowd3d {
    const c = new Crowd3d(this.core, this.raw, opts);
    this.crowds.push(c);
    return c;
  }

  /** @internal advance any crowds this navmesh owns. */
  tick(dt: number): void { for (const c of this.crowds) c.update(dt); }

  kill(): void { this.dead = true; }
}

/** A thin wrapper over recast's Crowd: add agents bound to a target, step it,
 * read back positions. For dense groups that must not interpenetrate. */
export class Crowd3d {
  private raw: any;
  private core: NavCore;
  private agents: any[] = [];
  constructor(core: NavCore, navMesh: unknown, opts: { maxAgents?: number; maxAgentRadius?: number }) {
    this.core = core;
    this.raw = new core.Crowd(navMesh, { maxAgents: opts.maxAgents ?? 256, maxAgentRadius: opts.maxAgentRadius ?? 0.6 });
  }
  /** Add a crowd agent at a world position; returns its index. */
  add(pos: NavVec3, params: Record<string, number> = {}): number {
    const idx = this.raw.addAgent({ x: pos.x, y: pos.y, z: pos.z }, { radius: 0.6, height: 2, maxSpeed: 6, maxAcceleration: 20, ...params });
    this.agents.push(idx);
    return idx;
  }
  /** Point an agent at a world goal. */
  goto(idx: number, goal: NavVec3): void { this.raw.goto?.(idx, { x: goal.x, y: goal.y, z: goal.z }); }
  /** Current world position of a crowd agent. */
  position(idx: number): NavVec3 { const p = this.raw.getAgentPosition(idx); return { x: p.x, y: p.y, z: p.z }; }
  update(dt: number): void { this.raw.update(dt); }
}

/** Bake a NavMesh3d from geometry (loads the vendored core on first use). */
export async function buildNavMesh(opts: NavMeshOptions): Promise<NavMesh3d> {
  const core = await loadNavCore(opts.module);
  let positions = opts.positions, indices = opts.indices;
  if ((!positions || !indices) && opts.from === 'terrain') {
    if (!opts.heightAt || !opts.size) throw new Error('agents.navmesh({from:"terrain"}) needs heightAt + size');
    const m = terrainMesh(opts.heightAt, opts.size, opts.res ?? 64, opts.center?.x ?? 0, opts.center?.z ?? 0);
    positions = m.positions; indices = m.indices;
  }
  if (!positions || !indices) throw new Error('agents.navmesh needs { positions, indices } or { from:"terrain", heightAt, size }');
  const cs = opts.cellSize ?? 0.3, ch = opts.cellHeight ?? 0.2;
  // recast's walkable* params are in VOXELS — convert from world units.
  const cfg = {
    cs, ch,
    walkableSlopeAngle: opts.agentMaxSlope ?? 50,
    walkableHeight: Math.ceil((opts.agentHeight ?? 2) / ch),
    walkableClimb: Math.floor((opts.agentMaxClimb ?? 0.9) / ch),
    walkableRadius: Math.ceil((opts.agentRadius ?? 0.6) / cs),
  };
  const res = core.generateSoloNavMesh(positions, indices, cfg);
  if (!res.success) throw new Error('agents.navmesh: recast bake failed — ' + (res.error ?? 'no walkable polygons (check mesh winding is CCW-up and slope/agent params)'));
  return new NavMesh3d(core, res.navMesh);
}

/** The planner contract both NavGrid and NavMesh3d satisfy (for `navigate`). */
export interface PathPlanner {
  path(start: NavVec3, goal: NavVec3): NavVec3[];
}
