// 3D VECTOR LINES (the Phase-2 remainder — a verbatim Rich mandate:
// "wireframe OBJ meshes in the same aesthetic"). Instanced SEGMENTS with
// 3D endpoints: each expands to a screen-space quad in the vertex stage, so
// the capsule-SDF core renders at a PIXEL-CONSTANT width (the retro vector
// look — hairlines stay hairlines at any distance), while depth comes from
// the real 3D endpoints, so wireframes occlude correctly against the solid
// world. Drawn in the translucent pass: depth-tested, never written.
//
// WIREFRAME EXTRACTION: wireframeEdges() turns any triangle soup (the
// loaders' stride-8 verts) into clean outline edges — positions are welded,
// then an edge survives only if it borders ONE face (boundary) or its two
// faces meet at more than `angle` degrees (a crease). Interior diagonals of
// flat polygons vanish; a cube gives 12 edges, not 36 triangle sides.
//
// Pure parts (WGSL builder, edge extraction) are exported and dist-tested.

import { BITS, shaderModule } from './gpu.js';
import { rgba } from './color.js';
import { eulerToQuat, quatRotate } from './transform3d.js';
import type { Mat4 } from './math3d.js';

export const LINE3D_FLOATS = 16;   // a.xyz+widthPx | b.xyz+capped | c0 | c1

export interface VectorShape3dOptions {
  x?: number; y?: number; z?: number;
  yaw?: number; pitch?: number; roll?: number;
  scale?: number;
  color?: string;
  /** Core width in SCREEN PIXELS (default 1.5; < 1 = flat-cut hairline). */
  width?: number;
  alpha?: number;
  /** Join each polyline's last point back to its first. */
  closed?: boolean;
}

/** A retained 3D line shape — mutate the transform/style freely. */
export class VectorShape3d {
  x: number; y: number; z: number;
  yaw: number; pitch: number; roll: number;
  scale: number;
  color: string;
  width: number;
  alpha: number;
  dead = false;
  /** Shape-local segments [ax, ay, az, bx, by, bz]. */
  readonly segs: Array<[number, number, number, number, number, number]>;

  constructor(segs: Array<[number, number, number, number, number, number]>, o: VectorShape3dOptions = {}) {
    this.segs = segs;
    this.x = o.x ?? 0; this.y = o.y ?? 0; this.z = o.z ?? 0;
    this.yaw = o.yaw ?? 0; this.pitch = o.pitch ?? 0; this.roll = o.roll ?? 0;
    this.scale = o.scale ?? 1;
    this.color = o.color ?? '#7df9ff';
    this.width = o.width ?? 1.5;
    this.alpha = o.alpha ?? 1;
  }

  kill(): void { this.dead = true; }
}

/** Polylines → shape-local segments (shared by lines() and wireframes). */
export function polylinesToSegs(
  polylines: Array<Array<[number, number, number]>>, closed = false,
): Array<[number, number, number, number, number, number]> {
  const segs: Array<[number, number, number, number, number, number]> = [];
  for (const line of polylines) {
    for (let i = 0; i < line.length - 1; i++) {
      segs.push([...line[i], ...line[i + 1]] as [number, number, number, number, number, number]);
    }
    if (closed && line.length > 2) {
      segs.push([...line[line.length - 1], ...line[0]] as [number, number, number, number, number, number]);
    }
  }
  return segs;
}

/**
 * Extract WIREFRAME edges from a stride-8 triangle soup. Verts are welded
 * by position (1e-4 grid); an edge is kept when it borders one face only
 * (boundary/open geometry) or its faces crease by more than `angle`
 * degrees. Returns segments in the soup's own coordinate space.
 */
export function wireframeEdges(
  verts: Float32Array, angle = 20,
): Array<[number, number, number, number, number, number]> {
  // angle <= 0: keep EVERY unique edge (the classic full-mesh wireframe) —
  // the right look for SMOOTH models, where almost nothing creases and a
  // threshold leaves only scattered feature lines ("half the model").
  const all = angle <= 0;
  const cosT = Math.cos((angle * Math.PI) / 180);
  const weld = new Map<string, number>();
  const pos: number[][] = [];
  const idOf = (o: number): number => {
    const x = verts[o], y = verts[o + 1], z = verts[o + 2];
    const key = `${Math.round(x * 1e4)},${Math.round(y * 1e4)},${Math.round(z * 1e4)}`;
    let id = weld.get(key);
    if (id === undefined) {
      id = pos.length;
      weld.set(key, id);
      pos.push([x, y, z]);
    }
    return id;
  };
  // Edge key → face normals sharing it.
  const edges = new Map<string, { a: number; b: number; normals: number[][] }>();
  const triCount = Math.floor(verts.length / 24);
  for (let t = 0; t < triCount; t++) {
    const o = t * 24;
    const i0 = idOf(o), i1 = idOf(o + 8), i2 = idOf(o + 16);
    if (i0 === i1 || i1 === i2 || i2 === i0) continue;   // degenerate
    const p0 = pos[i0], p1 = pos[i1], p2 = pos[i2];
    const ux = p1[0] - p0[0], uy = p1[1] - p0[1], uz = p1[2] - p0[2];
    const vx = p2[0] - p0[0], vy = p2[1] - p0[1], vz = p2[2] - p0[2];
    let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const l = Math.hypot(nx, ny, nz);
    if (l < 1e-12) continue;
    nx /= l; ny /= l; nz /= l;
    for (const [a, b] of [[i0, i1], [i1, i2], [i2, i0]] as const) {
      const key = a < b ? `${a}:${b}` : `${b}:${a}`;
      let e = edges.get(key);
      if (!e) {
        e = { a: Math.min(a, b), b: Math.max(a, b), normals: [] };
        edges.set(key, e);
      }
      e.normals.push([nx, ny, nz]);
    }
  }
  const out: Array<[number, number, number, number, number, number]> = [];
  for (const e of edges.values()) {
    let keep = all || e.normals.length === 1;             // all / boundary
    if (!keep) {
      // Any pair of adjacent faces creasing harder than the threshold.
      outer: for (let i = 0; i < e.normals.length; i++) {
        for (let j = i + 1; j < e.normals.length; j++) {
          const [ax, ay, az] = e.normals[i];
          const [bx, by, bz] = e.normals[j];
          if (Math.abs(ax * bx + ay * by + az * bz) < cosT) { keep = true; break outer; }
        }
      }
    }
    if (keep) {
      const p = pos[e.a], q = pos[e.b];
      out.push([p[0], p[1], p[2], q[0], q[1], q[2]]);
    }
  }
  return out;
}

/** The 3D line shader (pure string — dist-tested). Screen-space width in
 * pixels, depth from the real endpoints. */
export function buildLine3dWGSL(): string {
  return /* wgsl */ `
struct U {
  viewProj: mat4x4f,
  screen: vec4f,       // w, h, cameraNear, 0
}
// posA: endpoint a (xyz) + core half-width in PIXELS
// posB: endpoint b (xyz) + capped (1 = round caps, 0 = hairline flat cut)
// c0/c1: rgba at a / b
struct Inst { posA: vec4f, posB: vec4f, c0: vec4f, c1: vec4f }
struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) local: vec2f,       // pixel space: along, across
  @location(1) len: f32,
  @location(2) coreHalf: f32,
  @location(3) c0: vec4f,
  @location(4) c1: vec4f,
  @location(5) capped: f32,
}
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> inst: array<Inst>;

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let d = inst[ii];
  var out: VSOut;
  var ca = u.viewProj * vec4f(d.posA.xyz, 1.0);
  var cb = u.viewProj * vec4f(d.posB.xyz, 1.0);
  // Near-plane clip in CLIP space (the near plane is z=0; a point nearer than
  // near — or behind the camera — has z<0). Both ends beyond it: nothing to
  // show, collapse. Otherwise slide the offending end DOWN the segment to the
  // z=0 crossing, so a long line (a floor grid straddling the camera) is
  // CLIPPED, not dropped whole. Clipping to z=0 keeps w>0, so the projection
  // below stays finite (a raw w<near test would explode the pixel coords).
  if (ca.z < 0.0 && cb.z < 0.0) {
    out.pos = vec4f(0.0, 0.0, -2.0, 1.0);
    return out;
  }
  if (ca.z < 0.0) { ca = mix(ca, cb, ca.z / (ca.z - cb.z)); }
  else if (cb.z < 0.0) { cb = mix(cb, ca, cb.z / (cb.z - ca.z)); }
  let half = vec2f(u.screen.x, u.screen.y) * 0.5;
  let pa = (ca.xy / ca.w) * half;          // pixel space, y up — SDF only
  let pb = (cb.xy / cb.w) * half;
  let ab = pb - pa;
  let len = max(1e-4, length(ab));
  let dir = ab / len;
  let n = vec2f(-dir.y, dir.x);
  let reach = d.posA.w + 2.0;
  let c01 = vec2f(f32(vi & 1u), f32(vi >> 1u));
  let along = mix(-reach, len + reach, c01.x);
  let across = (c01.y - 0.5) * 2.0 * reach;
  let px = pa + dir * along + n * across;
  // Back to clip: depth/w interpolate between the endpoints by the cap-
  // clamped fraction, so the line sits at its true 3D depth.
  let tz = clamp(c01.x, 0.0, 1.0);
  let cw = mix(ca.w, cb.w, tz);
  // Depth bias toward the camera, in WORLD units (~0.05): wireframe edges
  // lie EXACTLY on the surface that occludes them in hidden-line mode and
  // z-fight it without a bias. It must be world-PROPORTIONAL: perspective
  // depth compresses with distance (d(ndc)/d(world) ~ near / w^2), so a
  // constant NDC bias — the first attempt — outweighed entire model
  // thicknesses at range and let every back edge through. depth' =
  // depth - bias*near/w^2, i.e. clip z' = clip z - bias*near/w.
  let cz = mix(ca.z, cb.z, tz) - (0.05 * u.screen.z) / cw;
  out.pos = vec4f(px / half * cw, cz, cw);
  out.local = vec2f(along, across);
  out.len = len;
  out.coreHalf = d.posA.w;
  out.c0 = d.c0;
  out.c1 = d.c1;
  out.capped = d.posB.w;
  return out;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  // Capsule SDF in pixel space (the 2D vector recipe): round caps overlap
  // invisibly at alpha 1; hairlines (width < 1) cut flat instead — their
  // AA-limited caps double-blend into dots at every joint otherwise.
  var ax = in.local.x;
  if (in.capped < 0.5) { ax = clamp(ax, 0.0, in.len); }
  let q = vec2f(ax - clamp(ax, 0.0, in.len), in.local.y);
  let dist = length(q);
  var a = 1.0 - smoothstep(in.coreHalf - 0.5, in.coreHalf + 0.5, dist);
  if (in.capped < 0.5 && (in.local.x < 0.0 || in.local.x > in.len)) { a = 0.0; }
  let t = clamp(in.local.x / max(in.len, 1e-4), 0.0, 1.0);
  let c = mix(in.c0, in.c1, t);
  let alpha = c.a * a;
  return vec4f(c.rgb * alpha, alpha);
}
`;
}

/** The retained 3D vector layer — world3d owns one; shapes pack every
 * frame (transforms are live) into one instanced draw. */
export class Vector3dLayer {
  private device!: GPUDevice;
  private pipeline!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private bind!: GPUBindGroup;
  private uniforms!: GPUBuffer;
  private buf!: GPUBuffer;
  private data = new Float32Array(1024 * LINE3D_FLOATS);
  private uniformData = new Float32Array(20);
  readonly shapes: VectorShape3d[] = [];
  /** Segments packed this frame (the draw count). */
  count = 0;

  constructor(device: GPUDevice, private format: GPUTextureFormat, private sampleCount: number) {
    this.rebuild(device);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.layout = device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
      ],
    });
    this.uniforms = device.createBuffer({ size: this.uniformData.byteLength, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.buf = device.createBuffer({ size: this.data.byteLength, usage: BITS.STORAGE | BITS.COPY_DST });
    const mod = shaderModule(device, buildLine3dWGSL(), 'World3d vector lines');
    this.pipeline = device.createRenderPipeline({
      layout: device.createPipelineLayout({ bindGroupLayouts: [this.layout] }),
      vertex: { module: mod, entryPoint: 'vs' },
      fragment: {
        module: mod, entryPoint: 'fs',
        targets: [{
          format: this.format,
          blend: {
            color: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
            alpha: { srcFactor: 'one', dstFactor: 'one-minus-src-alpha' },
          },
        }],
      },
      depthStencil: { format: 'depth24plus', depthWriteEnabled: false, depthCompare: 'less-equal' },
      primitive: { topology: 'triangle-strip' },
      multisample: { count: this.sampleCount },
    });
    this.makeBind();
  }

  private makeBind(): void {
    this.bind = this.device.createBindGroup({
      layout: this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: { buffer: this.buf } },
      ],
    });
  }

  /** Pack + upload every live shape's segments (world.prepare calls this). */
  prepare(vp: Mat4, screenW: number, screenH: number, near = 0.1): void {
    let live = 0;
    for (let i = this.shapes.length - 1; i >= 0; i--) {
      if (this.shapes[i].dead) this.shapes.splice(i, 1);
      else live += this.shapes[i].segs.length;
    }
    this.count = 0;
    if (!live) return;
    if (live * LINE3D_FLOATS > this.data.length) {
      let len = this.data.length;
      while (len < live * LINE3D_FLOATS) len *= 2;
      this.data = new Float32Array(len);
      this.buf.destroy();
      this.buf = this.device.createBuffer({ size: len * 4, usage: BITS.STORAGE | BITS.COPY_DST });
      this.makeBind();
    }
    const d = this.data;
    for (const s of this.shapes) {
      const q = eulerToQuat(s.yaw, s.pitch, s.roll);
      const c = rgba(s.color);
      const a = s.alpha;
      const capped = s.width >= 1 ? 1 : 0;
      for (const seg of s.segs) {
        const o = this.count++ * LINE3D_FLOATS;
        const pa = quatRotate(q, seg[0] * s.scale, seg[1] * s.scale, seg[2] * s.scale);
        const pb = quatRotate(q, seg[3] * s.scale, seg[4] * s.scale, seg[5] * s.scale);
        d[o] = s.x + pa[0]; d[o + 1] = s.y + pa[1]; d[o + 2] = s.z + pa[2]; d[o + 3] = s.width / 2;
        d[o + 4] = s.x + pb[0]; d[o + 5] = s.y + pb[1]; d[o + 6] = s.z + pb[2]; d[o + 7] = capped;
        d[o + 8] = c[0]; d[o + 9] = c[1]; d[o + 10] = c[2]; d[o + 11] = c[3] * a;
        d[o + 12] = c[0]; d[o + 13] = c[1]; d[o + 14] = c[2]; d[o + 15] = c[3] * a;
      }
    }
    const u = this.uniformData;
    u.set(vp, 0);
    u[16] = screenW; u[17] = screenH; u[18] = near; u[19] = 0;
    this.device.queue.writeBuffer(this.uniforms, 0, u);
    this.device.queue.writeBuffer(this.buf, 0, this.data.buffer, 0, this.count * LINE3D_FLOATS * 4);
  }

  draw(pass: GPURenderPassEncoder): void {
    if (!this.count) return;
    pass.setPipeline(this.pipeline);
    pass.setBindGroup(0, this.bind);
    pass.draw(4, this.count);
  }
}
