// UNDERWATER — being BELOW the water, not merely under the water shader.
// Three cooperating pieces, all inside the lazy 3D chunk and byte-free until
// the first `world.underwater()`:
//
//   1. Underwater3d      — a pure/live CPU handle. Each tick it decides (from
//                          the analytic wave height, with a hysteresis band so
//                          bobbing at the line never strobes) whether the
//                          camera is SUBMERGED and how DEEP, then hands the
//                          renderer a retargeted fog so every existing 3D
//                          shader tints toward the water for free.
//   2. Underwater3dLayer — one fullscreen COMPOSITE (two blended draws in the
//                          scene pass, modelled on SsaoPass/RaysPass): per-
//                          channel Beer–Lambert extinction + in-scatter murk +
//                          a soft vignette + a waterline mask (the half-in/
//                          half-out split + a bright meniscus band). Reads the
//                          opaque worldDepth and reconstructs world position
//                          from the inverse view-projection.
//   3. (M2/M3) caustics in the mesh shader + the Snell's-window underside.
//
// The pure maths (submersionState / absorb / underwaterFog / presets) is
// dist-tested; this module loads DOM/GPU-free so the tests can import it.

import { BITS, shaderModule } from './gpu.js';
import { rgba } from './color.js';
import { DEPTH_FORMAT } from './batch.js';
import { mat4Inverse } from './math3d.js';
import type { Mat4 } from './math3d.js';
import type { Water3d } from './water3d.js';

// ── Config surface (data-driven — see docs/webgpu-underwater-plan.md §5) ────

export type UnderwaterPresetName = 'reef' | 'ocean' | 'pool' | 'murk';

export interface CausticOptions {
  /** Overall brightness (default from preset). */
  strength?: number;
  /** World units per caustic tile (default 6). */
  scale?: number;
  /** Animation speed multiplier (default 1). */
  speed?: number;
  /** Chromatic split in uv (default 0.0035, 0 = off). */
  rgbSplit?: number;
  /** Receiver depth at which caustics fade to zero (default 20). */
  maxDepth?: number;
}

export interface UnderwaterOptions {
  /** Which water body drives submersion; default = the first grid water. */
  water?: Water3d;
  /** 'auto' (default) = the camera-depth test; true/false forces it. */
  enable?: 'auto' | boolean;
  /** The body must be at least this deep to EVER activate (puddle guard). */
  minDepth?: number;
  /** Named starting point — fills everything below (default 'reef'). */
  preset?: UnderwaterPresetName;

  // Optics — per-channel Beer–Lambert (per world unit)
  /** View extinction σ (murk closing in), e.g. reef [0.35, 0.07, 0.03]. */
  sigma?: [number, number, number];
  /** Downwelling σ (sun-fade with depth) — a decoupled dial. */
  sunSigma?: [number, number, number];
  /** In-scatter murk colour (engine hex). */
  waterColor?: string;
  /** 0..1 master clarity — scales σ (1 = as authored, 0 = crystal). */
  clarity?: number;
  /** Artistic far clamp for the fog retarget (world units). */
  maxView?: number;

  // Caustics (M2)
  caustics?: boolean | CausticOptions;

  // Surface from below (M3)
  snell?: boolean;

  // Light shafts (M4)
  /** `intensity` scales brightness; `quantity` 0..1 sets how much of the
   * surface web sheds visible columns (0 = only the hottest cells). */
  rays?: boolean | { intensity?: number; quantity?: number };

  // Screen side — all subtle; wobble OFF by default (the nausea rule)
  /** Soft wide vignette 0..1 (default 0.25). */
  vignette?: number;
  /** Depth-grade / murk strength 0..1 (default 0.6). */
  grade?: number;
  /** Screen wobble in uv — clamped ≤ 0.003; default 0 (off). */
  wobble?: number;
}

export interface UnderwaterPreset {
  sigma: [number, number, number];
  sunSigma: [number, number, number];
  waterColor: string;
  maxView: number;
  caustics: Required<CausticOptions>;
  snell: boolean;
  vignette: number;
  grade: number;
}

const CAUS = (strength: number): Required<CausticOptions> =>
  ({ strength, scale: 18, speed: 1, rgbSplit: 0.0016, maxDepth: 20 });

/** Start values — Rich retunes by eye. BRIGHT-BY-DEFAULT: the original
 * triplets came from physical Jerlov tables (red dead in ~5 m) and read as
 * instant murk in a GAME — the references (stylised reef shots) have almost
 * no view extinction at all. `murk` keeps the heavy physical feel. */
export const UNDERWATER_PRESETS: Record<UnderwaterPresetName, UnderwaterPreset> = {
  reef: {
    sigma: [0.055, 0.028, 0.014], sunSigma: [0.045, 0.02, 0.011], waterColor: '#2f9fc4',
    maxView: 170, caustics: CAUS(1.0), snell: true, vignette: 0.12, grade: 0.2,
  },
  ocean: {
    sigma: [0.11, 0.055, 0.032], sunSigma: [0.08, 0.035, 0.02], waterColor: '#1f7ba0',
    maxView: 110, caustics: CAUS(0.8), snell: true, vignette: 0.2, grade: 0.4,
  },
  pool: {
    sigma: [0.03, 0.016, 0.01], sunSigma: [0.03, 0.014, 0.008], waterColor: '#4cc4e4',
    maxView: 220, caustics: CAUS(1.2), snell: true, vignette: 0.1, grade: 0.15,
  },
  murk: {
    sigma: [0.6, 0.25, 0.15], sunSigma: [0.3, 0.16, 0.1], waterColor: '#3d5544',
    maxView: 18, caustics: CAUS(0.3), snell: true, vignette: 0.4, grade: 0.85,
  },
};

// ── Pure helpers (dist-tested) ──────────────────────────────────────────────

/** The submersion decision. Hysteresis: the camera must cross `hysteresis`
 * BEYOND the surface line to flip state, so a hull bobbing exactly at the
 * waterline never strobes the whole effect on and off. `depth` is how far the
 * camera sits below the surface (0 when above). */
export function submersionState(
  prev: boolean, camY: number, surfY: number, hysteresis: number,
): { submerged: boolean; depth: number } {
  let submerged = prev;
  if (prev) {
    if (camY > surfY + hysteresis) submerged = false;
  } else if (camY < surfY - hysteresis) {
    submerged = true;
  }
  const depth = Math.max(0, surfY - camY);
  return { submerged, depth };
}

/** Per-channel Beer–Lambert transmittance exp(-σ·dist) — the CPU replica of
 * the shader's extinction law (used for the fog-colour darkening). */
export function absorb(
  sigma: readonly [number, number, number], dist: number,
): [number, number, number] {
  const d = Math.max(0, dist);
  return [Math.exp(-sigma[0] * d), Math.exp(-sigma[1] * d), Math.exp(-sigma[2] * d)];
}

const clamp01 = (v: number): number => (v < 0 ? 0 : v > 1 ? 1 : v);
const hex2 = (v: number): string => {
  const n = Math.round(clamp01(v) * 255);
  return (n < 16 ? '0' : '') + n.toString(16);
};
const toHex = (r: number, g: number, b: number): string => `#${hex2(r)}${hex2(g)}${hex2(b)}`;

/** The GENTLE base tint every existing 3D shader gets for free: the water
 * colour, darkened with depth by the downwelling law and desaturated toward
 * grey-green by storm, over a fog band that closes in with σ and storm. The
 * composite owns the per-channel extinction; this only has to make the murk,
 * translucents, beams and particles agree with the underwater look. */
export function underwaterFog(
  opts: { waterColor: string; sunSigma: [number, number, number]; sigma: [number, number, number]; maxView: number },
  depth: number,
  storm: number,
): { color: string; near: number; far: number } {
  const wc = rgba(opts.waterColor);
  const t = absorb(opts.sunSigma, depth);
  // Storm desaturates the murk toward a grey-green and darkens it a touch.
  const s = clamp01(storm);
  const grey = (wc[0] + wc[1] + wc[2]) / 3;
  const desat = (c: number): number => c + (grey - c) * s * 0.5;
  const dim = 1 - 0.2 * s;
  // Deeper = DARKER, for real. The old 0.5 luminance floor kept the murk
  // luminous at ANY depth — right for the snorkel-depth hero shot, absurd
  // 60 units down (Rich: "the kind of depth you need a torch at"). The
  // steepened law (t^1.8, floor 0.06) leaves the top ~5 units essentially
  // untouched and runs to near-black by torch depth.
  const dk = (v: number): number => 0.06 + 0.94 * Math.pow(Math.max(v, 0), 1.8);
  const r = desat(wc[0]) * dk(t[0]) * dim;
  const g = desat(wc[1]) * dk(t[1]) * dim;
  const b = desat(wc[2]) * dk(t[2]) * dim;
  const sigMax = Math.max(opts.sigma[0], opts.sigma[1], opts.sigma[2]) * (1 + s) || 1e-3;
  // maxView is the AT-DEPTH artistic clamp. Near the surface the water is
  // CLEAR (snorkel optics): visibility opens to ~4x maxView at the line and
  // tightens to maxView by ~3 units down — without this, dipping the camera
  // under at a beach slammed the fog to diving-depth murk instantly.
  const ck = clamp01(depth / 3);
  const surfaceOpen = 4 - 3 * (ck * ck * (3 - 2 * ck));
  // At depth the light fails and VISIBILITY closes in with it — the far
  // plane rides the mean surviving downwelling light (≈1 near the surface,
  // a quarter at torch depth: dark AND short-sighted).
  const tAvg = (t[0] + t[1] + t[2]) / 3;
  const darkClose = 0.25 + 0.75 * Math.pow(tAvg, 1.2);
  const far = Math.min((opts.maxView * surfaceOpen) / (1 + s * 0.8), 25 / sigMax) * darkClose;
  return { color: toHex(r, g, b), near: far * 0.02, far };
}

// ── Caustic pattern bake ────────────────────────────────────────────────────
// The Dave Hoskins tileable caustic loop (Shadertoy MdlXz8) is ~10 iterations
// of transcendentals per evaluation. Run ONCE per texel here it is free; run
// per FRAGMENT per frame (as M2 first shipped it) it costs whole frames — a
// beach view covers the entire visible seabed, so the mesh FS was paying the
// loop millions of times a frame and 120 fps fell to sub-20. So the pattern is
// baked on the CPU into a small tileable r8 texture with a full mip chain and
// the mesh FS pays two filtered taps. The dapple ANIMATION comes from the two
// samples scrolling at different scales/speeds and min-blending (the Zucconi
// recipe the plan prescribed) — the pattern itself never needs to change.

/** One Hoskins caustic field, size×size texels over one tile, row-major.
 * Values are the raw pattern (mostly 0..1 with sparkle peaks above 1). Pure +
 * deterministic for the dist tests; `t` picks the phase slice to bake. */
export function bakeCausticField(size = 256, t = 1.0): Float32Array {
  const TAU = Math.PI * 2;
  const inten = 0.005;
  const out = new Float32Array(size * size);
  for (let y = 0; y < size; y++) {
    const py = ((y + 0.5) / size) * TAU - 250;
    for (let x = 0; x < size; x++) {
      const px = ((x + 0.5) / size) * TAU - 250;
      let ix = px, iy = py, c = 1;
      for (let k = 0; k < 5; k++) {
        const nx = px + Math.cos(t - ix) + Math.sin(t + iy);
        const ny = py + Math.sin(t - iy) + Math.cos(t + ix);
        ix = nx; iy = ny;
        c += 1 / Math.hypot(px / (Math.sin(ix + t) / inten), py / (Math.cos(iy + t) / inten));
      }
      c /= 5;
      c = 1.17 - Math.pow(c, 1.4);
      out[y * size + x] = Math.pow(Math.abs(c), 8);
    }
  }
  return out;
}

/** Bake the field into an r8unorm texture with a full 2×2-box mip chain (the
 * seabed recedes to the fog line — unmipped taps shimmer). The u8 texel stores
 * value/2 so the >1 sparkle peaks survive quantisation; the mesh FS multiplies
 * the tap by 2 to undo it. */
export function createCausticTexture(device: GPUDevice, size = 256): GPUTexture {
  const mips = 1 + Math.floor(Math.log2(size));
  const tex = device.createTexture({
    size: { width: size, height: size },
    format: 'rg8unorm',
    mipLevelCount: mips,
    usage: BITS.TEXTURE_BINDING | 0x2 /* texture COPY_DST */,
  });
  // TWO INDEPENDENT PHASES, one per channel: the mesh FS min-blends a tap of
  // R with a tap of G, so no repeating motif can ever line up with itself —
  // two taps of one field at related scales tiled visibly (Rich could point
  // at the repeats from a boat).
  let fieldR = bakeCausticField(size, 1.0);
  let fieldG = bakeCausticField(size, 3.7);
  let w = size;
  for (let m = 0; m < mips; m++) {
    const bytes = new Uint8Array(w * w * 2);
    for (let i = 0; i < w * w; i++) {
      const r = Math.round(fieldR[i] * 0.5 * 255);
      const g = Math.round(fieldG[i] * 0.5 * 255);
      bytes[i * 2] = r < 0 ? 0 : r > 255 ? 255 : r;
      bytes[i * 2 + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
    }
    device.queue.writeTexture(
      { texture: tex, mipLevel: m }, bytes, { bytesPerRow: w * 2 }, { width: w, height: w },
    );
    if (m + 1 < mips) {
      // Box-filter the FLOAT fields for the next level (pre-quantisation).
      const hw = w >> 1;
      const nextR = new Float32Array(hw * hw);
      const nextG = new Float32Array(hw * hw);
      for (let y = 0; y < hw; y++) {
        for (let x = 0; x < hw; x++) {
          const i0 = y * 2 * w + x * 2, i1 = i0 + w;
          nextR[y * hw + x] = (fieldR[i0] + fieldR[i0 + 1] + fieldR[i1] + fieldR[i1 + 1]) * 0.25;
          nextG[y * hw + x] = (fieldG[i0] + fieldG[i0 + 1] + fieldG[i1] + fieldG[i1 + 1]) * 0.25;
        }
      }
      fieldR = nextR; fieldG = nextG; w = hw;
    }
  }
  return tex;
}

// ── The live handle ─────────────────────────────────────────────────────────

/** Returned by `world.underwater()`. Read `submerged`/`depth`; every option
 * below is a live-mutable field (no rebuild). */
export class Underwater3d {
  water: Water3d | null;
  enable: 'auto' | boolean;
  minDepth: number;

  sigma: [number, number, number];
  sunSigma: [number, number, number];
  waterColor: string;
  clarity: number;
  maxView: number;

  caustics: Required<CausticOptions>;
  causticsOn: boolean;
  snell: boolean;
  rays: boolean;
  /** Underwater shaft brightness multiplier (rays: { intensity }). */
  rayStrength = 0.8;
  /** 0..1 — how much of the surface web sheds visible columns (rays:
   * { quantity }). 0 = a few hot cells only, 1 = most of the web. */
  rayQuantity = 0.45;
  /** World units below the flat water level at which the beam tops start.
   * 0 = right up in the waves (Rich's preference for the ABZU wall); raise
   * to pull the tops down away from the surface. */
  rayBand = 0;
  /** Shaft arc PACKING in world units — smaller = MANY more, tighter beams
   * in the ring (the ABZU wall is a dense field, not a few streaks). */
  rayGap = 12;
  /** Shaft FLICKER 0..2 — the beams do NOT move; they FADE in and out on
   * their own phase+speed, like a long streak of piano keys constantly
   * playing (Rich/ABZU). 0 = all steady on; 1 = gentle; 2 = frantic. */
  rayFlicker = 0.7;
  /** WALL DISTANCE (world units): the ring of beams sits this far from the
   * camera and follows it — "just out of reach". Raise to push the wall of
   * light further back. */
  rayNear = 40;
  vignette: number;
  grade: number;
  wobble: number;

  /** Read-only, updated each tick. */
  submerged = false;
  /** Camera depth below the surface (0 when above). */
  depth = 0;
  /** Whether the composite pass should run this frame (submerged, or within a
   * small band above the surface so the crossing splits cleanly). */
  active = false;
  /** 0 near the surface → 1 fully under (drives whole-frame vs split mask). */
  fullUnder = 0;
  /** The surface height used for the mask this tick. */
  surfaceY = 0;
  /** Caustics run whenever the body exists and the sun is up — NOT tied to the
   * camera being submerged (the seabed dapples when seen from ABOVE too). */
  causticActive = false;
  /** Storm- and sun-coupled caustic values, refreshed each tick. */
  causticStrengthNow = 0;
  causticSpeedNow = 1;
  /** The fog to apply while submerged (recomputed each tick). */
  fogNow: { color: string; near: number; far: number } = { color: '#0b0e1a', near: 0, far: 1 };

  dead = false;

  /** True when no explicit waterColor was given: the palette then FOLLOWS
   * the water body's tint (seaColor dial and all) every tick. */
  autoColor: boolean;

  constructor(opts: UnderwaterOptions = {}, water: Water3d | null = null) {
    const p = UNDERWATER_PRESETS[opts.preset ?? 'reef'];
    this.water = opts.water ?? water;
    this.enable = opts.enable ?? 'auto';
    this.minDepth = opts.minDepth ?? 0.75;
    this.sigma = opts.sigma ? [...opts.sigma] : [...p.sigma];
    this.sunSigma = opts.sunSigma ? [...opts.sunSigma] : [...p.sunSigma];
    this.autoColor = opts.waterColor === undefined;
    this.waterColor = opts.waterColor ?? p.waterColor;
    this.clarity = opts.clarity ?? 1;
    this.maxView = opts.maxView ?? p.maxView;
    const c = opts.caustics;
    this.causticsOn = c !== false;
    this.caustics = { ...p.caustics, ...(typeof c === 'object' ? c : {}) };
    this.snell = opts.snell ?? p.snell;
    this.rays = opts.rays !== false;
    this.rayStrength = typeof opts.rays === 'object' && opts.rays.intensity !== undefined ? opts.rays.intensity : 0.8;
    if (typeof opts.rays === 'object' && opts.rays.quantity !== undefined) this.rayQuantity = opts.rays.quantity;
    this.vignette = opts.vignette ?? p.vignette;
    this.grade = opts.grade ?? p.grade;
    this.wobble = Math.min(0.003, Math.max(0, opts.wobble ?? 0));
  }

  /** Apply a named preset over the live fields (keeps `water`/`enable`). */
  setPreset(name: UnderwaterPresetName): void {
    const p = UNDERWATER_PRESETS[name];
    if (!p) return;
    this.sigma = [...p.sigma];
    this.sunSigma = [...p.sunSigma];
    this.waterColor = p.waterColor;
    this.maxView = p.maxView;
    this.caustics = { ...p.caustics };
    this.vignette = p.vignette;
    this.grade = p.grade;
  }

  /** 0 near the surface → 1 at snorkel-to-dive depth: the preset optics are
   * tuned for BEING DOWN there — applied at full strength the moment the
   * camera dips under, ankle-deep water at a beach slammed to instant murk.
   * Updated each tick from camera depth; scales the view extinction. */
  shallowK = 1;

  /** σ scaled by the clarity dial (0 = crystal, 1 = as authored) and the
   * shallow-water ramp (ankle-deep = near-clear, diving = full preset). */
  viewSigma(): [number, number, number] {
    const k = clamp01(this.clarity) * (0.22 + 0.78 * this.shallowK);
    return [this.sigma[0] * k, this.sigma[1] * k, this.sigma[2] * k];
  }

  /** Downwelling sigma scaled by clarity and the shallow ramp — the dial and
   * snorkel depth brighten the sun-fade the same way they thin the murk. */
  sunSigmaNow(): [number, number, number] {
    const k = (0.3 + 0.7 * clamp01(this.clarity)) * (0.35 + 0.65 * this.shallowK);
    return [this.sunSigma[0] * k, this.sunSigma[1] * k, this.sunSigma[2] * k];
  }

  /** Update submersion state + the fog for this frame. Pure w.r.t. the world:
   * the caller reads `submerged`/`fogNow`/`active` and applies them. `surfY`
   * is the exact wave height at the camera column (water.heightAt); `sunI` is
   * the world sun intensity (0 at night → no caustics). */
  tick(camX: number, camY: number, camZ: number, surfY: number, storm: number, sunI = 1): void {
    const s = clamp01(storm);
    const sK = clamp01(sunI);
    // Caustics are gated on the body + sun, NOT on the camera being under —
    // shallow sand shimmers whether you look down from above or up from below.
    this.causticActive = this.enable !== false && this.causticsOn && !!this.water && sK > 0.01;
    this.causticStrengthNow = this.caustics.strength * (1 - 0.7 * s) * sK;
    this.causticSpeedNow = this.caustics.speed * (1 + s * 0.6);
    // Puddle guard: a body shallower than minDepth under the camera column
    // never triggers anything (a puddle must not go "underwater").
    const w = this.water;
    const bodyDeepEnough = !w || w.kind !== 'grid' || !w.ground
      ? true
      : (w.levelNow() - w.ground(camX, camZ)) >= this.minDepth;
    if (this.enable === false || !bodyDeepEnough) {
      this.submerged = false; this.active = false; this.depth = 0; this.fullUnder = 0;
      return;
    }
    this.surfaceY = surfY;
    if (this.enable === true) {
      this.submerged = true;
      this.depth = Math.max(0, surfY - camY);
    } else {
      const st = submersionState(this.submerged, camY, surfY, 0.1);
      this.submerged = st.submerged;
      this.depth = st.depth;
    }
    // The composite runs while submerged OR within a small band above the
    // surface (so looking down through the line splits cleanly). fullUnder
    // ramps 0→1 just below the surface: near the line the per-pixel waterline
    // mask carries the split; deeper, the whole frame is underwater.
    const below = surfY - camY;                       // >0 when submerged
    this.active = this.enable === true || below > -0.6;
    this.fullUnder = clamp01(below / 0.5);
    const dk = clamp01(this.depth / 3);
    this.shallowK = dk * dk * (3 - 2 * dk);           // clear at the surface
    // The palette follows the BODY's tint unless explicitly authored: the
    // underwater world should look like the sea you dived into (seaColor
    // dial included), brightened toward its shallow hue.
    const wb = this.water as unknown as { shallow?: string; deep?: string } | null;
    if (this.autoColor && wb?.shallow && wb?.deep) {
      const sh = rgba(wb.shallow), dp = rgba(wb.deep);
      const lift = (a: number, b: number): number => clamp01((a * 0.7 + b * 0.3) * 1.35);
      this.waterColor = toHex(lift(sh[0], dp[0]), lift(sh[1], dp[1]), lift(sh[2], dp[2]));
    }
    this.fogNow = underwaterFog(
      { waterColor: this.waterColor, sunSigma: this.sunSigmaNow(), sigma: this.viewSigma(), maxView: this.maxView },
      this.depth, storm,
    );
  }

  /** God-ray shaft modulation while submerged (M4): reuse the surface god-ray
   * pass but ATTENUATE it by the downwelling law (shafts die with depth) and
   * TINT it toward the water hue. Null when not submerged or rays disabled —
   * the caller leaves the surface shafts untouched. */
  shaftMod(): { atten: number; tint: [number, number, number] } | null {
    if (!this.submerged || !this.rays) return null;
    const t = absorb(this.sunSigma, this.depth);
    const wc = rgba(this.waterColor);
    return { atten: (t[0] + t[1] + t[2]) / 3, tint: [wc[0], wc[1], wc[2]] };
  }

  kill(): void { this.dead = true; }
}

// ── The GPU composite layer ─────────────────────────────────────────────────

// invVP (16) | camPos.xyz+on (4) | sigma.rgb+surfaceY (4) |
// sunSigma.rgb+fullUnder (4) | waterColor.rgb+grade (4) |
// feather,meniscus,vignette,wobble (4)
const UU_FLOATS = 36;

function underwaterWGSL(ms: boolean): string {
  const depthType = ms ? 'texture_depth_multisampled_2d' : 'texture_depth_2d';
  return /* wgsl */ `
struct UU {
  invVP: mat4x4f,
  cam: vec4f,        // xyz camera, w = on (0/1)
  sigma: vec4f,      // rgb view extinction, w = surfaceY
  sunSigma: vec4f,   // rgb downwelling, w = fullUnder (0..1)
  water: vec4f,      // rgb murk colour, w = grade
  screen: vec4f,     // feather, meniscus, vignette, wobble
}
@group(0) @binding(0) var<uniform> uu: UU;
@group(0) @binding(1) var depthTex: ${depthType};
@group(0) @binding(4) var shaftTex: texture_2d<f32>;    // half-res billboard shaft target
@group(0) @binding(5) var shaftSamp: sampler;           // clamp + linear

struct VSOut { @builtin(position) pos: vec4f, @location(0) uv: vec2f }

@vertex
fn vs(@builtin(vertex_index) vi: u32) -> VSOut {
  var out: VSOut;
  let x = f32((vi << 1u) & 2u);
  let y = f32(vi & 2u);
  out.pos = vec4f(x * 2.0 - 1.0, 1.0 - y * 2.0, 0.0, 1.0);
  out.uv = vec2f(x, y);
  return out;
}

fn worldAt(uv: vec2f, d: f32) -> vec3f {
  let ndc = vec4f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0, d, 1.0);
  let w = uu.invVP * ndc;
  return w.xyz / w.w;
}

// Everything both draws share: the per-pixel reconstruction, the waterline
// mask, the transmittances. Returns (below, transmit.rgb, viewTransAvg) via
// out params packed into two vec4s to keep it branch-light.
struct Terms {
  below: f32,
  transmit: vec3f,   // per-channel scene multiplier before the mask
  inscat: vec3f,     // per-channel in-scatter (before the mask)
  meniscus: f32,
}

fn terms(in: VSOut) -> Terms {
  var t: Terms;
  // The depth texel for this fullscreen fragment, from its uv.
  let dims = vec2i(textureDimensions(depthTex));
  let px = clamp(vec2i(in.uv * vec2f(dims)), vec2i(0), dims - 1);
  let d = textureLoad(depthTex, px, 0);
  let world = worldAt(in.uv, d);
  let viewDist = max(distance(uu.cam.xyz, world), 1e-4);
  let rayDir = (world - uu.cam.xyz) / viewDist;
  // ABSORB ONLY THE UNDERWATER PART OF THE RAY. The opaque depth knows
  // nothing about the (translucent) water surface: for every ceiling pixel
  // it reports the terrain or sky FAR BEHIND it, so exp(-sigma*~900) slammed
  // the whole from-below view to murk at ANY clarity (Rich: waves visible
  // only at exactly clarity 0). Rays that exit the surface are clamped at
  // the analytic waterline plane — light from above is only attenuated
  // below it.
  var wDist = viewDist;
  if (rayDir.y > 1e-4) {
    wDist = min(wDist, max(uu.sigma.w - uu.cam.y, 0.0) / rayDir.y);
  }
  let hit = uu.cam.xyz + rayDir * wDist;
  let pd = max(0.0, uu.sigma.w - hit.y);              // receiver depth below surface
  let sunTint = exp(-uu.sunSigma.rgb * pd);
  let viewTrans = exp(-uu.sigma.rgb * wDist);

  // Soft vignette, slightly bottom-weighted (murk gathers at the edges).
  let r = length((in.uv - vec2f(0.5, 0.44)) * vec2f(1.15, 1.0));
  let vig = 1.0 - uu.screen.z * smoothstep(0.28, 0.85, r);

  t.transmit = sunTint * viewTrans * vig;
  t.inscat = uu.water.rgb * (1.0 - viewTrans);

  // Waterline mask — RAY-BASED: a pixel is "underwater view" when the view
  // ray is below the surface right AT THE CAMERA, not when its geometry is.
  // The first cut masked on scene height, which is true for the whole seabed
  // seen through the water from above — the entire shallows slammed to murk
  // the moment the camera came near the line, double-fogging what the water
  // surface shader already renders (Rich: "instant murk with the ball still
  // half above water"). Sampling the ray a short step from the camera gives
  // the crossing split for free and leaves above-water views untouched.
  let rayY = uu.cam.y + rayDir.y * 0.35;
  var below = smoothstep(-0.08, 0.08, uu.sigma.w - rayY);
  below = max(below, uu.sunSigma.w);                  // fullUnder
  t.below = below * uu.cam.w;                         // × on
  // A thin bright meniscus band right at the crossing (only near the line).
  let men = smoothstep(0.16, 0.0, abs(uu.sigma.w - rayY));
  t.meniscus = men * uu.screen.y * (1.0 - uu.sunSigma.w) * uu.cam.w;
  return t;
}

// MULTIPLY draw: out = dst * mix(1, transmit, below). Blend zero/src.
@fragment
fn fsMul(in: VSOut) -> @location(0) vec4f {
  let t = terms(in);
  let m = mix(vec3f(1.0), t.transmit, t.below);
  return vec4f(m, 1.0);
}

// ADD draw: out = dst + below*inscatter + shafts + meniscus. Blend one/one.
@fragment
fn fsAdd(in: VSOut) -> @location(0) vec4f {
  let t = terms(in);
  var add = t.inscat * t.below + uu.water.rgb * (t.meniscus * 0.6) + vec3f(t.meniscus * 0.25);
  // Shafts: a 9-tap bilinear blur of the half-res billboard shaft target —
  // each tap already averages 4 texels, so this is ~a 7x7 full-res kernel.
  // Smooth by construction; beams are soft light, blur only helps them.
  let ts = 1.0 / vec2f(textureDimensions(shaftTex));
  var sh = textureSampleLevel(shaftTex, shaftSamp, in.uv, 0.0).r * 0.2;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(1.5 * ts.x, 0.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(-1.5 * ts.x, -0.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(-0.5 * ts.x, 1.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(0.5 * ts.x, -1.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(2.5 * ts.x, -1.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(-2.5 * ts.x, 1.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(1.5 * ts.x, 2.5 * ts.y), 0.0).r * 0.1;
  sh += textureSampleLevel(shaftTex, shaftSamp, in.uv + vec2f(-1.5 * ts.x, -2.5 * ts.y), 0.0).r * 0.1;
  let shaftCol = mix(vec3f(1.0), uu.water.rgb, 0.45);
  add += shaftCol * sh;
  return vec4f(add, 0.0);
}
`;
}

// ── BILLBOARD LIGHT SHAFTS ───────────────────────────────────────────────────
// The replacement for the doomed view-ray volumetric march (11 rounds of
// stacked discs). A shaft is now GEOMETRY: a world-anchored vertical-axis
// billboard quad hung under the surface, leaning along the refracted sun,
// drawn ADDITIVELY with soft falloffs. There is NO march and NO per-step
// sampling of the view ray, so it physically CANNOT band/disc or scroll —
// this is the approach shipping games use under a translucent water surface
// (post-process god rays get blocked by the surface; the
// Papadopoulos-Papaioannou survey names the view-ray family as the banding
// one). Instances are a camera-following world grid (snapped, per-cell hash
// stable) so shafts hold still in the world; the existing half-res target +
// blur composite still smooths them.
const MAX_SHAFTS = 640;
const SB_FLOATS = 52;   // viewProj(16) invVP(16) cam(4) sun(4) sunCol(4) parm(4) fade(4)

/** Stable per-cell hash → [0,1). Keeps each WORLD cell's shaft identical as
 * the follow-grid recenters, so shafts never twinkle or swim. */
function cellHash(ix: number, iz: number, seed: number): number {
  let h = (ix * 374761393 + iz * 668265263 + seed * 1274126177) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = (h ^ (h >>> 16)) >>> 0;
  return h / 4294967296;
}

function shaftBillWGSL(ms: boolean): string {
  const depthType = ms ? 'texture_depth_multisampled_2d' : 'texture_depth_2d';
  return /* wgsl */ `
struct SB {
  viewProj: mat4x4f,
  invVP: mat4x4f,
  cam: vec4f,          // xyz camera
  sun: vec4f,          // xyz refracted sun-DOWN dir (normalised), w = intensity
  sunCol: vec4f,       // rgb sun colour, w = time
  parm: vec4f,         // level, band, sunSigma, depthCap
  fade: vec4f,         // nearStart, softK, farFade, unused
}
@group(0) @binding(0) var<uniform> sb: SB;
@group(0) @binding(1) var<storage, read> insts: array<vec4f>;   // 2 vec4/instance
@group(0) @binding(2) var depthTex: ${depthType};

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
  @location(1) world: vec3f,
  @location(2) bright: f32,
}

fn worldAt(uv: vec2f, d: f32) -> vec3f {
  let ndc = vec4f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0, d, 1.0);
  let w = sb.invVP * ndc;
  return w.xyz / w.w;
}

@vertex
fn vs(@builtin(vertex_index) vi: u32, @builtin(instance_index) ii: u32) -> VSOut {
  let p0 = insts[ii * 2u];        // baseX, baseZ, length, width
  let p1 = insts[ii * 2u + 1u];   // phase, brightness, -, -
  var corners = array<vec2f, 6>(
    vec2f(0.0, 0.0), vec2f(1.0, 0.0), vec2f(0.0, 1.0),
    vec2f(0.0, 1.0), vec2f(1.0, 0.0), vec2f(1.0, 1.0));
  let uv = corners[vi];
  let level = sb.parm.x;
  let band = sb.parm.y;
  // Shaft top starts a wave-band below the flat level (clears the ripples).
  let base = vec3f(p0.x, level - band, p0.y);
  let axis = normalize(sb.sun.xyz + vec3f(0.0, -1e-3, 0.0));   // down the sun
  let toCam = sb.cam.xyz - base;
  var right = cross(axis, toCam);
  let rl = length(right);
  right = select(vec3f(1.0, 0.0, 0.0), right / rl, rl > 1e-4);  // cylindrical billboard
  let along = uv.y * p0.z;
  let widen = 1.0 - uv.y * 0.35;                                // taper to a point (streak)
  // The shaft does NOT MOVE (Rich/ABZU: beams fade, they do not sway). Fixed
  // world geometry — so nothing can scroll.
  let world = base + axis * along + right * (uv.x - 0.5) * p0.w * widen;
  // PIANO-KEYS FLICKER: each beam fades in and out on its OWN phase+speed,
  // irregular (two incommensurate sines), spending time near zero so the
  // field constantly "plays". rayFlicker (fade.w) scales how deep it dips.
  let time = sb.sunCol.w;
  let flick = clamp(sb.fade.w, 0.0, 2.0);
  let spd = max(p1.z, 0.3) * (0.7 + 0.3 * flick);
  let t2 = time * spd;
  let raw = smoothstep(-0.35, 0.65, sin(t2 + p1.x) + 0.55 * sin(t2 * 0.63 + p1.x * 2.1));
  let pulse = mix(1.0, raw, min(flick, 1.0));                   // flick 0 = steady on
  var o: VSOut;
  o.pos = sb.viewProj * vec4f(world, 1.0);
  o.uv = uv;
  o.world = world;
  o.bright = p1.y * pulse;
  return o;
}

@fragment
fn fs(in: VSOut) -> @location(0) vec4f {
  let level = sb.parm.x;
  let sunSig = sb.parm.z;
  let cap = sb.parm.w;
  // Across-width soft edge, and a length fade: in just below the top, out
  // toward the bottom (shafts brightest near the surface, dissolving down).
  let edge = smoothstep(0.5, 0.1, abs(in.uv.x - 0.5));
  // Each beam dissolves at its OWN tip (its length is capped above the seabed
  // in pack()), so this bottom taper is the seabed fade — smooth, per-beam.
  let lenF = smoothstep(0.0, 0.1, in.uv.y) * (1.0 - smoothstep(0.5, 1.0, in.uv.y));
  let depthBelow = max(level - in.world.y, 0.0);
  let beer = exp(-sunSig * depthBelow);                        // dim with depth
  let capF = 1.0 - smoothstep(cap * 0.55, cap, depthBelow);    // dead by torch depth
  // SEABED FADE: the beam fades to TRANSPARENT as it APPROACHES the seabed,
  // dissolving cleanly ABOVE the floor rather than punching into it (ABZU;
  // subtle but matters in shallow water). fade.y is the fade distance: fully
  // gone AT the seabed, ramping to full over the last fade.y units above it
  // (and hidden entirely when behind, gap < 0).
  // The half-res target is quarter-area of the depth texture: full-res px =
  // half-res fragcoord x2.
  let dims = vec2i(textureDimensions(depthTex));
  let px = clamp(vec2i(in.pos.xy * 2.0), vec2i(0), dims - 1);
  let sceneD = textureLoad(depthTex, px, 0);
  let sceneW = worldAt(in.pos.xy * 2.0 / vec2f(dims), sceneD);
  let fragDist = distance(sb.cam.xyz, in.world);
  let sceneDist = distance(sb.cam.xyz, sceneW);
  let softZ = smoothstep(0.0, sb.fade.y, sceneDist - fragDist);
  // SAFE-DISTANCE near fade: beams FADE OUT as they approach the camera and
  // only appear beyond fade.x, so a cluster never fills the viewport — the
  // field stays a nice distance away as ONE clean layer (Rich/ABZU). Far
  // fade dissolves the grid-edge beams.
  let nearF = smoothstep(sb.fade.x, sb.fade.x + 24.0, fragDist);
  let farF = 1.0 - smoothstep(sb.fade.z * 0.75, sb.fade.z, distance(sb.cam.xz, in.world.xz));
  // PALE: the field is many faint beams that SUM softly, not a few bright
  // streaks — 0.5 keeps a single beam subtle so overlaps read as glow.
  let a = 0.5 * edge * lenF * beer * capF * softZ * nearF * farF * in.bright * sb.sun.w;
  return vec4f(a, 0.0, 0.0, 1.0);                              // additive scalar light
}
`;
}

export class Underwater3dLayer {
  /** Set by pack() each frame from the handle; composite() no-ops when off. */
  active = false;

  /** The baked tileable caustic pattern — world3d hands this to Lights3d so
   * the mesh FS (group(1) bindings 5/6) can tap it. Recreated on device loss;
   * the owner must re-call lights3d.setCaustic after rebuild(). */
  causticView!: GPUTextureView;

  private device!: GPUDevice;
  private mulPipeline!: GPURenderPipeline;
  private mulPipelineMS!: GPURenderPipeline;
  private addPipeline!: GPURenderPipeline;
  private addPipelineMS!: GPURenderPipeline;
  private layout!: GPUBindGroupLayout;
  private layoutMS!: GPUBindGroupLayout;
  private uniforms!: GPUBuffer;
  private linearSamp!: GPUSampler;
  private shaftTarget: GPUTexture | null = null;
  private shaftView: GPUTextureView | null = null;
  private dummyShaft!: GPUTextureView;
  private shaftDrawn = false;
  private data = new Float32Array(UU_FLOATS);
  // Billboard shafts.
  private bilPipeline!: GPURenderPipeline;
  private bilPipelineMS!: GPURenderPipeline;
  private bilLayout!: GPUBindGroupLayout;
  private bilLayoutMS!: GPUBindGroupLayout;
  private sbUniform!: GPUBuffer;
  private instBuffer!: GPUBuffer;
  private sbData = new Float32Array(SB_FLOATS);
  private instData = new Float32Array(MAX_SHAFTS * 8);
  private shaftCount = 0;

  constructor(device: GPUDevice, private format: GPUTextureFormat) {
    this.rebuild(device);
  }

  /** Pack the composite uniforms for this frame from the live handle. `vp` is
   * this frame's view-projection (inverted here for world reconstruction).
   * `sun` is the world light DIRECTION (pointing down-scene), `sunI` its
   * intensity (0 at night), `time` the wall clock for the shaft drift. */
  pack(
    uw: Underwater3d, vp: Mat4, eye: { x: number; y: number; z: number },
    sun: { x: number; y: number; z: number } = { x: 0, y: -1, z: 0 }, sunI = 1, time = 0, storm = 0,
  ): void {
    this.active = uw.active;
    if (!uw.active) return;
    const inv = mat4Inverse(vp);
    const sig = uw.viewSigma();
    // The in-scatter murk rides fogNow, NOT the raw waterColor: fogNow
    // carries the depth-darkening (and storm desaturation), so the murk
    // wall darkens with the dive. Raw waterColor painted BRIGHT cyan over
    // the correctly-darkened scene at torch depth (Rich's abyss test).
    const wc = rgba(uw.fogNow.color);
    const d = this.data;
    d.set(inv, 0);
    d.set([eye.x, eye.y, eye.z, 1], 16);
    d.set([sig[0], sig[1], sig[2], uw.surfaceY], 20);
    const ss = uw.sunSigmaNow();
    d.set([ss[0], ss[1], ss[2], uw.fullUnder], 24);
    d.set([wc[0], wc[1], wc[2], uw.grade], 28);
    // feather scales with depth so the split edge is crisp at the surface and
    // soft when deep; meniscus fades out as you sink.
    const feather = 0.12 + uw.fullUnder * 0.4;
    const meniscus = 0.5 * (1 - uw.fullUnder);
    d.set([feather, meniscus, uw.vignette, uw.wobble], 32);
    // Shafts: toward the sun; die at night, in storm murk-light, and when
    // the sun grazes the horizon (near-horizontal beams read as glitch).
    // CAMERA-DEPTH RAMP: invisible while wading, arriving by snorkel depth
    // (Rich: rays are a "you're properly under now" cue, not a waterline
    // strobe). The smoothstep runs 0.25 → 2.2 units of camera depth.
    const sl = Math.hypot(sun.x, sun.y, sun.z) || 1;
    const up = -sun.y / sl;
    const horizonK = Math.min(1, Math.max(0, (up - 0.08) / 0.2));
    const dk = Math.min(1, Math.max(0, (uw.depth - 0.2) / 1.2));
    const depthK = dk * dk * (3 - 2 * dk);           // fade IN over the first ~1m of submersion
    // FADE OUT as the CAMERA gets deep: sunlight does not reach far down, so
    // the whole wall dissolves past a depth (Rich: at ~48u they should be
    // gone). Clear water lets them survive deeper; murk kills them sooner.
    const clr = Math.min(1, Math.max(0, uw.clarity));
    const dStart = 12 + 12 * clr, dEnd = 30 + 18 * clr;
    const dd = Math.min(1, Math.max(0, (uw.depth - dStart) / (dEnd - dStart)));
    const deepK = 1 - dd * dd * (3 - 2 * dd);
    const shaftI = uw.rays ? uw.rayStrength * Math.max(0, sunI) * horizonK * depthK * deepK * (1 - 0.7 * Math.min(1, storm)) : 0;
    // The FLAT still-water level (tide-shifted but constant — NO fast wave
    // bob, NO camera dependence): the billboard shafts anchor to this so they
    // hold still in the world. rayBand = top-clear margin; rayGap = spacing.
    const flatLevel = uw.water && !uw.water.dead ? uw.water.levelNow() : uw.surfaceY;
    this.device.queue.writeBuffer(this.uniforms, 0, d);

    // ── BILLBOARD SHAFTS — the ABZU "WALL": ONE camera-following RING of
    // beams at a fixed radius, 360° around the camera so they span the whole
    // view whichever way you look, always "just out of reach". A single shell
    // = ONE layer = NO depth-stacking, so beams never pile up in depth and
    // overlap into solid-white blobs (Rich's key ABZU observation — a field
    // stacked into the distance does exactly that). The ring FOLLOWS the
    // camera position, but its beam azimuths are WORLD-fixed, so it pans
    // correctly when you turn and simply stays ahead when you move (no swim).
    const reach = 30 + 14 * Math.min(1, Math.max(0, uw.clarity));
    const radius = Math.max(uw.rayNear, 6);                 // the wall's distance ("out of reach")
    const beamSpacing = Math.max(uw.rayGap * 0.12, 1.2);    // arc gap → tightly-packed wall
    const N = Math.min(MAX_SHAFTS, Math.max(24, Math.round((2 * Math.PI * radius) / beamSpacing)));
    const TAU = 2 * Math.PI;
    const sb = this.sbData;
    sb.set(vp, 0);
    sb.set(inv, 16);
    sb.set([eye.x, eye.y, eye.z, 0], 32);
    // Refracted sun-DOWN: Snell steepens the horizontal component underwater
    // (sin θ_water = sin θ_air / 1.333), so shafts hang more vertically.
    const rr = 1 / 1.333;
    let ddx = (sun.x / sl) * rr, ddy = sun.y / sl, ddz = (sun.z / sl) * rr;
    const ddl = Math.hypot(ddx, ddy, ddz) || 1;
    sb.set([ddx / ddl, ddy / ddl, ddz / ddl, shaftI], 36);
    sb.set([1, 1, 1, time], 40);                          // rgb unused (composite tints), w = time
    sb.set([flatLevel, uw.rayBand, uw.sunSigma[1] * 0.6, reach], 44);
    // The ring already sits at `radius`; the near/far fades are gentle safety
    // on the ring tips, and fade.y is a SMALL occlusion-only seabed fade (the
    // main seabed dissolve is now GEOMETRIC — length capped by water depth).
    sb.set([radius * 0.15, 6.0, radius * 1.9, uw.rayFlicker], 48);
    this.device.queue.writeBuffer(this.sbUniform, 0, sb);

    let n = 0;
    if (shaftI > 0.001) {
      const inst = this.instData;
      const groundFn = uw.water && !uw.water.dead && uw.water.ground ? uw.water.ground : null;
      const axisYabs = Math.max(Math.abs(ddy / ddl), 0.25);   // vertical drop per unit shaft length
      const baseY = flatLevel - uw.rayBand;
      for (let i = 0; i < N; i++) {
        // World-fixed azimuth (+ a little jitter) so the ring pans, not spins.
        const az = (i / N) * TAU + (cellHash(i, 0, 5) - 0.5) * (TAU / N) * 0.8;
        const rj = radius * (0.85 + 0.3 * cellHash(i, 0, 3));   // thin radial band, not a hard cylinder
        const bx = eye.x + Math.cos(az) * rj;
        const bz = eye.z + Math.sin(az) * rj;
        // LENGTH CAPPED BY WATER DEPTH: the beam ends ~5u above the seabed and
        // dissolves via its OWN tip taper. NO hard "too short → drop" — that
        // popped the whole ring in/out at once when the camera crossed a depth
        // (Rich). Instead the length SHRINKS SMOOTHLY toward 0 in shallow water
        // (clamped ≥ 0), so a beam over shallows/beach just fades to nothing
        // continuously — never pops.
        let maxLen = reach;
        if (groundFn) maxLen = (baseY - groundFn(bx, bz) - 5) / axisYabs;
        const len = Math.max(0, Math.min(reach * (0.85 + 0.3 * cellHash(i, 0, 17)), maxLen));
        const o = n * 8;
        inst[o] = bx;                                                       // baseX
        inst[o + 1] = bz;                                                   // baseZ
        inst[o + 2] = len;                                                 // length (depth-capped)
        inst[o + 3] = 0.5 + 0.9 * cellHash(i, 0, 19);                      // width (THIN, always)
        inst[o + 4] = cellHash(i, 0, 23) * TAU;                           // phase
        inst[o + 5] = 0.12 + 0.18 * cellHash(i, 0, 29);                   // brightness (PALE)
        inst[o + 6] = 1.2 + 1.6 * cellHash(i, 0, 31);                     // FAST flicker speed
        inst[o + 7] = 0;
        n++;
      }
      this.device.queue.writeBuffer(this.instBuffer, 0, this.instData, 0, n * 8);
    }
    this.shaftCount = n;
  }

  /** Draw the BILLBOARD shafts into the half-res r8 target (additive),
   * encoder-level, BEFORE the scene pass that composites+blurs them. */
  renderShafts(encoder: GPUCommandEncoder, worldDepth: GPUTexture, canvasW: number, canvasH: number): void {
    this.shaftDrawn = false;
    if (!this.active) return;
    const w = Math.max(1, canvasW >> 1), h = Math.max(1, canvasH >> 1);
    if (!this.shaftTarget || this.shaftTarget.width !== w || this.shaftTarget.height !== h) {
      this.shaftTarget?.destroy();
      this.shaftTarget = this.device.createTexture({
        size: { width: w, height: h },
        format: 'r8unorm',
        usage: BITS.RENDER_ATTACHMENT | BITS.TEXTURE_BINDING,
      });
      this.shaftView = this.shaftTarget.createView();
    }
    const pass = encoder.beginRenderPass({
      colorAttachments: [{ view: this.shaftView!, loadOp: 'clear', clearValue: { r: 0, g: 0, b: 0, a: 1 }, storeOp: 'store' }],
    });
    // The target is always cleared (so 'drawn' means the composite may sample
    // it); we only issue the instanced draw when there are shafts this frame.
    if (this.shaftCount > 0) {
      const ms = worldDepth.sampleCount > 1;
      const bind = this.device.createBindGroup({
        layout: ms ? this.bilLayoutMS : this.bilLayout,
        entries: [
          { binding: 0, resource: { buffer: this.sbUniform } },
          { binding: 1, resource: { buffer: this.instBuffer } },
          { binding: 2, resource: worldDepth.createView() },
        ],
      });
      pass.setPipeline(ms ? this.bilPipelineMS : this.bilPipeline);
      pass.setBindGroup(0, bind);
      pass.draw(6, this.shaftCount);
    }
    pass.end();
    this.shaftDrawn = true;
  }

  /** The two blended draws, inside the open scene pass (depth attached
   * read-only; we sample the persistent worldDepth instead). */
  composite(pass: GPURenderPassEncoder, worldDepth: GPUTexture): void {
    if (!this.active) return;
    const ms = worldDepth.sampleCount > 1;
    const bind = this.device.createBindGroup({
      layout: ms ? this.layoutMS : this.layout,
      entries: [
        { binding: 0, resource: { buffer: this.uniforms } },
        { binding: 1, resource: worldDepth.createView() },
        { binding: 4, resource: this.shaftDrawn && this.shaftView ? this.shaftView : this.dummyShaft },
        { binding: 5, resource: this.linearSamp },
      ],
    });
    pass.setBindGroup(0, bind);
    pass.setPipeline(ms ? this.mulPipelineMS : this.mulPipeline);
    pass.draw(3);
    pass.setPipeline(ms ? this.addPipelineMS : this.addPipeline);
    pass.draw(3);
  }

  rebuild(device: GPUDevice): void {
    this.device = device;
    this.uniforms = device.createBuffer({ size: UU_FLOATS * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.causticView = createCausticTexture(device, 512).createView();
    this.linearSamp = device.createSampler({ magFilter: 'linear', minFilter: 'linear' });
    this.shaftTarget = null;
    this.shaftView = null;
    this.shaftDrawn = false;
    const dummy = device.createTexture({ size: { width: 1, height: 1 }, format: 'r8unorm', usage: BITS.TEXTURE_BINDING | 0x2 /* COPY_DST */ });
    device.queue.writeTexture({ texture: dummy }, new Uint8Array([0]), {}, { width: 1, height: 1 });
    this.dummyShaft = dummy.createView();

    // The composite draws (fsMul/fsAdd) sample the half-res billboard shaft
    // target at bindings 4/5.
    const layoutFor = (multisampled: boolean): GPUBindGroupLayout => device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'depth', multisampled } },
        { binding: 4, visibility: BITS.STAGE_FRAGMENT, texture: {} },
        { binding: 5, visibility: BITS.STAGE_FRAGMENT, sampler: {} },
      ],
    });
    this.layout = layoutFor(false);
    this.layoutMS = layoutFor(true);

    const make = (ms: boolean, entry: 'fsMul' | 'fsAdd'): GPURenderPipeline => {
      const module = shaderModule(device, underwaterWGSL(ms), `Underwater ${entry}${ms ? '(ms)' : ''}`);
      const blend: GPUBlendState = entry === 'fsMul'
        // out.rgb = dst.rgb * src.rgb (src = the multiplier); alpha untouched.
        ? { color: { srcFactor: 'zero', dstFactor: 'src' }, alpha: { srcFactor: 'zero', dstFactor: 'one' } }
        // out.rgb = dst.rgb + src.rgb (src = the in-scatter); alpha untouched.
        : { color: { srcFactor: 'one', dstFactor: 'one' }, alpha: { srcFactor: 'zero', dstFactor: 'one' } };
      return device.createRenderPipeline({
        layout: device.createPipelineLayout({ bindGroupLayouts: [ms ? this.layoutMS : this.layout] }),
        vertex: { module, entryPoint: 'vs' },
        fragment: { module, entryPoint: entry, targets: [{ format: this.format, blend }] },
        depthStencil: { format: DEPTH_FORMAT, depthWriteEnabled: false, depthCompare: 'always' },
        primitive: { topology: 'triangle-list' },
      });
    };
    this.mulPipeline = make(false, 'fsMul');
    this.mulPipelineMS = make(true, 'fsMul');
    this.addPipeline = make(false, 'fsAdd');
    this.addPipelineMS = make(true, 'fsAdd');
    // ── BILLBOARD SHAFT pipeline: instanced geometry drawn additively into
    // the half-res r8 target. Uniform + instance storage + the opaque depth
    // (for soft occlusion). No depth attachment — overlapping shafts sum.
    this.sbUniform = device.createBuffer({ size: SB_FLOATS * 4, usage: BITS.UNIFORM | BITS.COPY_DST });
    this.instBuffer = device.createBuffer({ size: MAX_SHAFTS * 8 * 4, usage: BITS.STORAGE | BITS.COPY_DST });
    const bilLayoutFor = (multisampled: boolean): GPUBindGroupLayout => device.createBindGroupLayout({
      entries: [
        { binding: 0, visibility: BITS.STAGE_VERTEX | BITS.STAGE_FRAGMENT, buffer: { type: 'uniform' } },
        { binding: 1, visibility: BITS.STAGE_VERTEX, buffer: { type: 'read-only-storage' } },
        { binding: 2, visibility: BITS.STAGE_FRAGMENT, texture: { sampleType: 'depth', multisampled } },
      ],
    });
    this.bilLayout = bilLayoutFor(false);
    this.bilLayoutMS = bilLayoutFor(true);
    const makeBil = (ms: boolean): GPURenderPipeline => {
      const module = shaderModule(device, shaftBillWGSL(ms), `Underwater shaft billboard${ms ? '(ms)' : ''}`);
      return device.createRenderPipeline({
        layout: device.createPipelineLayout({ bindGroupLayouts: [ms ? this.bilLayoutMS : this.bilLayout] }),
        vertex: { module, entryPoint: 'vs' },
        fragment: {
          module, entryPoint: 'fs',
          targets: [{
            format: 'r8unorm',
            // Additive: overlapping shafts sum their scalar light.
            blend: { color: { srcFactor: 'one', dstFactor: 'one' }, alpha: { srcFactor: 'one', dstFactor: 'one' } },
          }],
        },
        primitive: { topology: 'triangle-list', cullMode: 'none' },
      });
    };
    this.bilPipeline = makeBil(false);
    this.bilPipelineMS = makeBil(true);
  }
}
