// ORBIT RIG — the 3D camera controller (three.js OrbitControls' heir).
// One call wires the lot: left-drag orbits, right-drag (or shift+drag) pans,
// the wheel dollies TOWARD THE CURSOR (not the world centre — so you can
// zoom into any corner of a scene), and optional FLY keys (WASD/arrows +
// Q/E, shift = fast) move the pivot for debugging walkthroughs.
//
//   const rig = world.orbit({ dist: 26, pitch: 0.4, fly: true });
//   // rig.yaw / rig.pitch / rig.dist / rig.target stay live + mutable;
//   // rig.enabled = false releases the camera; rig.detach() unwires it.
//
// The rig writes world.camera every frame (game ticks it) — while enabled,
// don't drive the camera by hand as well.

import type { World3d } from './world3d.js';

export interface OrbitOptions {
  /** Start angles/distance (radians; pitch >0 looks down from above). */
  yaw?: number;
  pitch?: number;
  dist?: number;
  /** Orbit pivot (default the origin). */
  target?: { x: number; y: number; z: number };
  minDist?: number;
  maxDist?: number;
  minPitch?: number;
  maxPitch?: number;
  /** Wheel dollies toward the cursor point (default true; false = centre zoom). */
  zoomToCursor?: boolean;
  /** Right-drag / shift+drag pans the pivot (default true). */
  pan?: boolean;
  /** WASD/arrow + Q/E flying (default false — turn on for debugging). */
  fly?: boolean;
  /** Fly speed in world units/sec (default scales with dist). Shift = 3×. */
  flySpeed?: number;
  rotateSpeed?: number;
  zoomSpeed?: number;
  /** Idle spin in radians/sec — pauses while dragging or flying (default 0). */
  autoRotate?: number;
  /** GROUND CLAMP: world height at (x, z) — the camera never sinks below
   * it (+ `floorMargin`, default 1.5). Wire a terrain:
   * `floor: (x, z) => terrain.heightAt(x, z)`. Live-mutable on the rig. */
  floor?: (x: number, z: number) => number;
  floorMargin?: number;
}

/** Scale camera + target about a fixed world point (the zoom-to-cursor core:
 * pure, testable). Returns the new target; the camera derives from it. */
export function scaleAboutPoint(
  target: { x: number; y: number; z: number }, c: { x: number; y: number; z: number }, k: number,
): { x: number; y: number; z: number } {
  return { x: c.x + (target.x - c.x) * k, y: c.y + (target.y - c.y) * k, z: c.z + (target.z - c.z) * k };
}

export class OrbitRig {
  yaw: number;
  pitch: number;
  dist: number;
  target: { x: number; y: number; z: number };
  enabled = true;
  /** Idle spin in radians/sec — pauses while dragging or flying. Live-mutable. */
  autoRotate: number;
  /** Ground clamp (see OrbitOptions.floor). Live-mutable; null = off. */
  floor: ((x: number, z: number) => number) | null;
  floorMargin: number;
  /** WASD/arrow + Q/E flying. Live-mutable so a demo can flip a follow
   * camera into a free-fly probe cam without rebuilding the rig. */
  fly: boolean;

  /** The live object being followed (see follow()), or null. */
  private followObj: { x: number; y: number; z: number } | null = null;
  private followOffset = { x: 0, y: 0, z: 0 };
  private followEase = 0;

  private world: World3d;
  private canvas: HTMLCanvasElement;
  private o: Required<Pick<OrbitOptions, 'minDist' | 'maxDist' | 'minPitch' | 'maxPitch' | 'zoomToCursor' | 'pan' | 'rotateSpeed' | 'zoomSpeed'>> & { flySpeed?: number };
  /** Sticky explore flag: set by the first fly movement. While set, a
   * rotate-drag turns the view about the CAMERA (look-around) instead of
   * swinging the camera about the pivot. */
  private look = false;
  private mode: 'none' | 'rotate' | 'pan' = 'none';
  private lastX = 0;
  private lastY = 0;
  private keys = new Set<string>();
  private un: Array<() => void> = [];

  constructor(world: World3d, canvas: HTMLCanvasElement, opts: OrbitOptions = {}) {
    this.world = world;
    this.canvas = canvas;
    this.yaw = opts.yaw ?? 0.5;
    this.pitch = opts.pitch ?? 0.4;
    this.dist = opts.dist ?? 25;
    this.target = opts.target ? { ...opts.target } : { x: 0, y: 0, z: 0 };
    this.autoRotate = opts.autoRotate ?? 0;
    this.floor = opts.floor ?? null;
    this.floorMargin = opts.floorMargin ?? 1.5;
    this.fly = opts.fly ?? false;
    this.o = {
      minDist: opts.minDist ?? 1,
      maxDist: opts.maxDist ?? 500,
      minPitch: opts.minPitch ?? -1.45,
      maxPitch: opts.maxPitch ?? 1.45,
      zoomToCursor: opts.zoomToCursor ?? true,
      pan: opts.pan ?? true,
      rotateSpeed: opts.rotateSpeed ?? 1,
      zoomSpeed: opts.zoomSpeed ?? 1,
      flySpeed: opts.flySpeed,
    };
    this.wire();
    this.apply();
  }

  /** Camera-frame basis from the current angles (right, up, forward). */
  private basis(): { R: number[]; U: number[]; F: number[] } {
    const cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);
    const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
    const F = [sy * cp, -sp, -cy * cp];                  // camera → target (right-hand-turn yaw)
    const R = [cy, 0, sy];                               // = normalize(F × worldUp): screen-right
    const U = [R[1] * F[2] - R[2] * F[1], R[2] * F[0] - R[0] * F[2], R[0] * F[1] - R[1] * F[0]]; // R × F: screen-up
    return { R, U, F };
  }

  private wire(): void {
    const cv = this.canvas;
    const on = <E extends Event>(el: HTMLElement | Window, ev: string, fn: (e: E) => void, o?: AddEventListenerOptions): void => {
      el.addEventListener(ev, fn as unknown as EventListener, o);
      this.un.push(() => el.removeEventListener(ev, fn as unknown as EventListener));
    };
    on(cv, 'pointerdown', (e: PointerEvent) => {
      if (!this.enabled) return;
      this.mode = (e.button === 2 || e.shiftKey) && this.o.pan ? 'pan' : e.button === 0 || e.button === 2 ? 'rotate' : 'none';
      this.lastX = e.clientX; this.lastY = e.clientY;
      cv.setPointerCapture(e.pointerId);
    });
    on(cv, 'pointermove', (e: PointerEvent) => {
      if (!this.enabled || this.mode === 'none') return;
      const dx = e.clientX - this.lastX, dy = e.clientY - this.lastY;
      this.lastX = e.clientX; this.lastY = e.clientY;
      if (this.mode === 'rotate') {
        // ONE yaw sign for BOTH modes — the drag FOLLOWS THE POINTER
        // (the three.js/Blender convention): drag left → the view swings
        // left. HISTORY: orbit mode originally used the OPPOSITE sign and
        // explore mode "flipped relative to orbit" to compensate; every
        // drag-inversion bug this rig has had traced back to that split
        // (caught for the third time on night-city, where a character
        // pivot makes the wrong direction unmissable). Never flip ONE
        // mode again — a direction change belongs to both, right here.
        if (this.look) {
          // Explore mode (after flying): the CAMERA stays put and the view
          // direction swings — recompute the pivot `dist` ahead of the new
          // angles so cameraPos() lands exactly where it was.
          const P = this.cameraPos();
          this.yaw += dx * 0.005 * this.o.rotateSpeed;
          this.pitch = this.clampPitch(this.pitch + dy * 0.004 * this.o.rotateSpeed);
          const cp = Math.cos(this.pitch);
          this.target.x = P.x + Math.sin(this.yaw) * cp * this.dist;   // right-hand-turn yaw
          this.target.y = P.y - Math.sin(this.pitch) * this.dist;
          this.target.z = P.z - Math.cos(this.yaw) * cp * this.dist;
        } else {
          this.yaw += dx * 0.005 * this.o.rotateSpeed;
          this.pitch = this.clampPitch(this.pitch + dy * 0.004 * this.o.rotateSpeed);
        }
      } else {
        // Pan: move the pivot in the screen plane, scaled to world units at
        // target depth (one pixel drags the world one pixel).
        const { R, U } = this.basis();
        const per = (2 * this.dist * Math.tan(((this.world.camera.fov ?? 60) * Math.PI) / 360)) / Math.max(1, cv.clientHeight);
        this.target.x -= (R[0] * dx - U[0] * dy) * per;
        this.target.y -= (R[1] * dx - U[1] * dy) * per;
        this.target.z -= (R[2] * dx - U[2] * dy) * per;
      }
    });
    const end = (e: PointerEvent): void => { this.mode = 'none'; if (cv.hasPointerCapture?.(e.pointerId)) cv.releasePointerCapture(e.pointerId); };
    on(cv, 'pointerup', end);
    on(cv, 'pointercancel', end);
    on(cv, 'contextmenu', (e: Event) => { if (this.o.pan) e.preventDefault(); });
    on(cv, 'wheel', (e: WheelEvent) => {
      if (!this.enabled) return;
      e.preventDefault();
      const k = Math.exp(e.deltaY * 0.0012 * this.o.zoomSpeed);
      const next = Math.min(this.o.maxDist, Math.max(this.o.minDist, this.dist * k));
      const real = next / this.dist;                     // clamped factor
      if (this.o.zoomToCursor && Math.abs(1 - real) > 1e-6) {
        const c = this.cursorPivot(e);
        if (c) this.target = scaleAboutPoint(this.target, c, real);
      }
      this.dist = next;
    }, { passive: false });
    on(window, 'keydown', (e: KeyboardEvent) => {
      if (!this.fly || !this.enabled) return;
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT')) return;
      this.keys.add(e.code);
    });
    on(window, 'keyup', (e: KeyboardEvent) => this.keys.delete(e.code));
    on(window, 'blur', () => this.keys.clear());
  }

  /** World point under the cursor on the plane through the target ⊥ view —
   * the fixed point wheel zoom scales about. Null when the ray grazes. */
  private cursorPivot(e: WheelEvent): { x: number; y: number; z: number } | null {
    const { R, U, F } = this.basis();
    const rect = this.canvas.getBoundingClientRect();
    const ndcX = ((e.clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1;
    const ndcY = 1 - ((e.clientY - rect.top) / Math.max(1, rect.height)) * 2;
    const tf = Math.tan(((this.world.camera.fov ?? 60) * Math.PI) / 360);
    const aspect = rect.width / Math.max(1, rect.height);
    const D = [
      F[0] + (R[0] * ndcX * aspect + U[0] * ndcY) * tf,
      F[1] + (R[1] * ndcX * aspect + U[1] * ndcY) * tf,
      F[2] + (R[2] * ndcX * aspect + U[2] * ndcY) * tf,
    ];
    const dDotF = D[0] * F[0] + D[1] * F[1] + D[2] * F[2];
    if (dDotF < 0.05) return null;
    const P = this.cameraPos();
    const s = this.dist / dDotF;                          // hit the target-depth plane
    return { x: P.x + D[0] * s, y: P.y + D[1] * s, z: P.z + D[2] * s };
  }

  private cameraPos(): { x: number; y: number; z: number } {
    const cp = Math.cos(this.pitch);
    return {
      x: this.target.x - Math.sin(this.yaw) * cp * this.dist,   // right-hand-turn yaw
      y: this.target.y + Math.sin(this.pitch) * this.dist,
      z: this.target.z + Math.cos(this.yaw) * cp * this.dist,
    };
  }

  private clampPitch(p: number): number {
    return Math.max(this.o.minPitch, Math.min(this.o.maxPitch, p));
  }

  /**
   * FOLLOW a live moving object — pass the handle itself (a mesh, group,
   * or any `{x, y, z}`), NOT a snapshot of its position. The rig re-reads
   * it every frame at TICK time, which the engine runs AFTER your game
   * callback — so whatever your callback did last (a TerrainRider settling
   * the object's `y`, a physics step, a parent transform) is already
   * applied, and the camera can NEVER lag a frame behind it.
   *
   * This is the whole point: `rig.target.y = thing.y` copied INSIDE the
   * callback captures a stale value if anything updates `thing` afterwards
   * — a footgun that reads as the followed object "jittering" under any
   * acceleration. `follow()` removes the ordering from your hands.
   *
   *   rig.follow(player, { offset: { y: 2 } });   // chase the player
   *   rig.follow(null);                            // release (free look)
   *
   * `offset` is added to the object; `ease` (per-second) lags the pivot
   * for a soft chase (default 0 = locked to the object). Yaw/pitch/dist
   * stay yours to set (a chase demo eases `rig.yaw` toward the heading).
   */
  follow(obj: { x: number; y: number; z: number } | null, opts?: { offset?: { x?: number; y?: number; z?: number }; ease?: number }): void {
    this.followObj = obj;
    this.followOffset = { x: opts?.offset?.x ?? 0, y: opts?.offset?.y ?? 0, z: opts?.offset?.z ?? 0 };
    this.followEase = opts?.ease ?? 0;
    if (obj && this.followEase <= 0) {
      this.target.x = obj.x + this.followOffset.x;
      this.target.y = obj.y + this.followOffset.y;
      this.target.z = obj.z + this.followOffset.z;
    }
  }

  /** Per-frame: fly keys, then write the world camera. The game calls this. */
  update(dt: number): void {
    if (!this.enabled) return;
    // FOLLOW the live object (resolved here at tick time, so a rider that
    // finalised its y in the game callback is already applied — no lag).
    if (this.followObj) {
      const o = this.followObj, off = this.followOffset;
      const tx = o.x + off.x, ty = o.y + off.y, tz = o.z + off.z;
      if (this.followEase > 0) {
        const k = 1 - Math.exp(-dt * this.followEase);
        this.target.x += (tx - this.target.x) * k;
        this.target.y += (ty - this.target.y) * k;
        this.target.z += (tz - this.target.z) * k;
      } else {
        this.target.x = tx; this.target.y = ty; this.target.z = tz;
      }
    }
    // Idle spin belongs to showcase orbiting — once the user is EXPLORING
    // (look mode), an idle drift would sweep the camera about a pivot they
    // no longer think in terms of.
    if (this.autoRotate && this.mode === 'none' && !this.keys.size && !this.look) this.yaw += this.autoRotate * dt;
    if (this.fly && this.keys.size) {
      const k = this.keys;
      const ax = (k.has('KeyD') || k.has('ArrowRight') ? 1 : 0) - (k.has('KeyA') || k.has('ArrowLeft') ? 1 : 0);
      const az = (k.has('KeyW') || k.has('ArrowUp') ? 1 : 0) - (k.has('KeyS') || k.has('ArrowDown') ? 1 : 0);
      const ay = (k.has('KeyE') ? 1 : 0) - (k.has('KeyQ') ? 1 : 0);
      if (ax || ay || az) {
        // Flying flips the rig (stickily) into EXPLORE mode: from here on,
        // dragging LOOKS AROUND from the camera instead of orbiting the
        // pivot — Rich's model: keys translate you through the world, the
        // mouse orbits at your current location. Until the first fly key,
        // the rig is a pure orbit and showcase demos are unaffected.
        this.look = true;
        // Rigid translation at CONSTANT speed (camera + pivot together;
        // dist untouched, so a dist-derived flySpeed never decays mid-flight).
        const { R, F } = this.basis();
        const gl = Math.hypot(F[0], F[2]) || 1;           // level: ground-plane forward
        const fx = F[0] / gl, fz = F[2] / gl;
        const speed = (this.o.flySpeed ?? this.dist * 0.6) * (k.has('ShiftLeft') || k.has('ShiftRight') ? 3 : 1) * dt;
        this.target.x += (fx * az + R[0] * ax) * speed;
        this.target.z += (fz * az + R[2] * ax) * speed;
        this.target.y += ay * speed;
      }
    }
    this.apply();
  }

  private apply(): void {
    const cam = this.world.camera;
    const p = this.cameraPos();
    // Ground clamp: lift the EYE above the floor height at its own (x, z);
    // the look-at target is untouched, so a low orbit glides along the
    // terrain instead of tunnelling into it.
    if (this.floor) {
      const fy = this.floor(p.x, p.z) + this.floorMargin;
      if (p.y < fy) p.y = fy;
    }
    cam.x = p.x; cam.y = p.y; cam.z = p.z;
    cam.tx = this.target.x; cam.ty = this.target.y; cam.tz = this.target.z;
  }

  /** Unwire every listener (the rig keeps its last camera pose). */
  detach(): void {
    for (const fn of this.un) fn();
    this.un.length = 0;
    this.keys.clear();
  }
}
