// WATER — E3 of the RICH ENVIRONMENTS kit. ONE system, two shapes, every
// scale from ocean swell to a garden stream:
//
//   - GRID waters (sea / ocean / lake / pool): a shared unit grid displaced
//     by summed GERSTNER waves in the VS — real undulation and chop, with
//     an exact CPU replica (`water.heightAt`) so boats ride the actual
//     swell. Presets differ only in wave tables and colour — the sea and a
//     pond are the same water at different numbers.
//   - RIBBON waters (stream / waterfall): a strip following a Path3d over
//     the terrain, flow scrolling along it. Slope is a per-vertex fact —
//     steep sections FOAM UP and accelerate, so a waterfall is just a
//     stream whose path drops off a cliff. No separate system.
//
// Shading is shared and terrain-native: scene-depth SHORE BLEND (soft
// waterline + animated foam band where the water meets the land — pass B
// binds the opaque depth read-only, the same trick soft particles use),
// depth-tinted shallow→deep colour, fresnel ENV reflection (the sky dome —
// water reflects the same sky the world lights from, storm and sunset
// included), sun glint from u.sunCol, and the standard fog. The day/night
// dial changes the water for free.
//
// The pure maths (gerstnerY, ribbonVerts, presets) is dist-tested.

import { BITS, shaderModule } from './gpu.js';
import { rgba } from './color.js';
import { DEPTH_FORMAT } from './batch.js';
import { Path3d } from './path3d.js';
import { MAX_PER_CLUSTER } from './lights3d.js';

// ── Waves ───────────────────────────────────────────────────────────────────

export interface WaveDef {
  dir: { x: number; z: number };
  /** Amplitude in world units (crest = level + amp). */
  amp: number;
  /** Wavelength in world units. */
  len: number;
  /** Phase speed in world units / second. */
  speed: number;
  /** 0 = pure sine, 1 = sharp trochoidal crests. */
  steep: number;
}

/** Height offset of summed Gerstner waves at (x, z, t) — the CPU replica of
 * the vertex shader (sampled at the undisplaced position; the horizontal
 * swirl is < steep·amp and irrelevant for floating gameplay). */
export function gerstnerY(waves: WaveDef[], x: number, z: number, t: number): number {
  let y = 0;
  for (const w of waves) {
    const dl = Math.hypot(w.dir.x, w.dir.z) || 1;
    const k = (Math.PI * 2) / Math.max(w.len, 1e-3);
    const phase = k * ((w.dir.x / dl) * x + (w.dir.z / dl) * z) - k * w.speed * t;
    y += w.amp * Math.sin(phase);
  }
  return y;
}

/** The HORIZONTAL Gerstner displacement at a material point — the GPU VS
 * moves each grid vertex sideways by q·amp·cos (crests gather, troughs
 * spread; `q = steep/(k·amp·6)`, so amp cancels). heightAt inverts this so
 * boats sit on the surface that is VISIBLY at (x, z), not on the height of
 * water that has advected somewhere else — at high swell the difference is
 * a hull's worth of air (Rich's flying boat). Mirrors the VS exactly except
 * the camera-distance fade (gameplay queries are near the camera, fade = 1). */
export function gerstnerXZ(
  waves: WaveDef[], x: number, z: number, t: number,
  ampScale: number, steepScale: number, shoal: number,
): [number, number] {
  let dx = 0, dz = 0;
  const norm = steepNorm(waves, steepScale);           // the packing's fold guard
  for (const w of waves) {
    if (w.amp * ampScale < 1e-5) continue;            // the VS skips dead waves
    const dl = Math.hypot(w.dir.x, w.dir.z) || 1;
    const k = (Math.PI * 2) / Math.max(w.len, 1e-3);
    const phase = k * ((w.dir.x / dl) * x + (w.dir.z / dl) * z) - k * w.speed * t;
    const sharp = Math.min(1.4, w.steep * steepScale) * norm;
    const m = (sharp * shoal / (6 * k)) * Math.cos(phase);
    dx += m * (w.dir.x / dl);
    dz += m * (w.dir.z / dl);
  }
  return [dx, dz];
}

/** GERSTNER SELF-INTERSECTION GUARD. When the SUMMED crest steepness climbs
 * too high, the horizontal advection makes crest vertices cross past each
 * other and the surface folds — inverted, flat, jagged shards riding the
 * crests (Rich's teeth: onset at sea-preset swell ≈ 0.68 where Σ ≈ 3.8,
 * severe by 0.9 — later traced to water-over-water compositing, fixed by
 * the painter's-order grid; this guard stays for TRUE self-intersection).
 * Both the GPU packing and the CPU replica scale every wave's steepness by
 * this factor, so crests SATURATE instead of folding. Folding needs the sum
 * ≈ 6; 4.8 guards pathological custom wave tables while never touching the
 * shipped presets (the sea maxes at ≈ 4.5 at swell 1). */
export function steepNorm(waves: WaveDef[], steepScale: number): number {
  let sum = 0;
  for (const w of waves) {
    if (w.amp < 1e-5) continue;
    sum += Math.min(1.4, w.steep * steepScale);
  }
  return sum > 4.8 ? 4.8 / sum : 1;
}

